import type { MeaningPack } from '../../types';

export const taSmvVerses2: MeaningPack = {
  lang: 'ta',
  texts: {
    'sumadhva-vijaya-09': {
      verses: {
        '0.0': "பிறகு புறப்படும்படி அன்புடன் தூண்டிய தர்மனின் மகனும் பிறப்பற்றவனுமான நாராயணனை அங்கே வணங்கி, ஞானிகளின் தலைவரான ஆனந்ததீர்த்தர் வேதநாயகரான வேதவ்யாஸரை முன்னிட்டுக் கொண்டு சென்றார்.",
        '0.1': "மற்றொரு ஆஶ்ரமத்தை (வ்யாஸாஶ்ரமத்தை) அடைந்து, க்ருஷ்ணரிடமிருந்து (வேதவ்யாஸரிடமிருந்து) கேட்க வேண்டியதெல்லாம் கேட்டு, குருவின் மனக்கருத்தை நன்கு உணர்ந்து அதைப் பின்பற்றி, புறப்படத் தயாரானார்.",
        '0.2': "ஞானிகளின் சிரோமணியும் மஹாமதியுமான அவர், புன்முறுவலால் மென்மையான அழகிய முகமுடைய, வணங்கத்தக்க ஸஜ்ஜனர்களின் தலைவரான வ்யாஸரை வணங்கி, அவர் அனுமதியுடன் சென்றார்.",
        '0.3': "விரிந்த மனமுடைய மத்வரின் மனமே வ்யாஸருக்கு மிகப் பிரியமான உறைவிடம்; அதை அவர் ஒரு கணமும் விடவில்லை; ஆகவே மத்வர் தம் ஸ்வாமியை விட்டு ஒருபோதும் பிரியவில்லை.",
        '0.4': "வீரப் பார்வையால் சிங்கம் போலத் தோன்றி, அமைதியான பார்வையால் சாந்தர்களுக்கு மகிழ்ச்சி தந்து, வழியில் அங்கங்கே இனிதாக நடந்து, ஸர்வஜ்ஞர் மலையிலிருந்து இறங்கி வந்தார்.",
        '0.5': "கடலைக் கடந்து வந்த வானரேந்திரன் ஹனுமானைப் போல, ரத்னராஜத்தை (ஸ்யமந்தகத்தை) கொண்டு வந்த வாஸுதேவனைப் போல, சிறந்த மலரை (ஸௌகந்திகத்தை) கொண்டு வந்த பீமஸேனனைப் போல, அவர் தம்மவர்க்கு மகிழ்ச்சி அளித்தார்.",
        '0.6': "அக்னிஶர்மா முதலிய ஐந்தாறு அந்தணர்கள் தனித்தனியே கொண்டு வந்த ஏராளமான உணவு முழுவதையும் அவர் வியப்பின்றி ஏற்றார்; ப்ரளயத்தில் அனைத்தையும் உண்ணக் கூடியவருக்கு இது என்ன அதிசயம்!",
        '0.7': "(7–11 ஶ்லோகங்கள் ஒரே வாக்கியம்.) வ்யாஸதேவரின் இதயத்துக்கு மிகப் பிரியமானவனும், எண்ணற்ற நற்குணங்களுடையவனும், எல்லாக் குறைகளும் அற்றவனும், ஞானம் பக்தி முடிவற்ற இன்பம் அருள்பவனுமான வாஸுதேவனை நிலைநாட்டும் பாஷ்யத்தை அவர் இயற்றினார்;",
        '0.8': "அந்தப் பரம விஷயத்தைக் கூறும் சிறந்த வேதவாக்கியங்களை மீண்டும் மீண்டும் மேற்கோள் காட்டி, ஸ்ம்ருதி வசனங்களால் அவற்றின் பொருளைத் தகுந்த யுக்திகளுடன் தெளிவாக்கும் பாஷ்யம்;",
        '0.9': "சிறுவர் கூட்டத்துக்கும் நன்கு புரிய வைப்பது, ஆனால் பண்டிதர்களுக்கும் ஆழம் அறிய முடியாத சொற்களுடையது; அளவிட முடியாத கருத்துடையது, தெளிவும் மென்மையான அழகும் உடையதாயினும் எதிரிகளுக்கு அச்சம் தருவது;",
        '0.10': "குற்றமற்றது, பயனற்றுப் போகாத சொற்களுடையது, பாஷ்யத்தின் எல்லா இலக்கணங்களும் அமைந்தது, தேவர் தலைவர்களாலும் போற்றப்படுவது — அவருடைய இன்னொரு புனித வடிவம் போன்றது;",
        '0.11': "இவ்வாறு அளவற்ற ஞானமுடைய அவர், இருபத்தொரு தவறான பாஷ்யங்களை மறுப்பதும், முன்னும் இன்றும் பின்னும் யாராலும் ஒருபோதும் மறுக்க முடியாததுமான அற்புதமான ப்ரஹ்மஸூத்ர பாஷ்யத்தை இயற்றினார்.",
        '0.12': "இதன் ஒரே ஒரு எழுத்தை எழுதுபவனும் கங்கையின் மங்கல அலைகள் மோதும் கரையில் அழகிய ஹரிகோயிலைக் கட்டியவனுக்குச் சமமான புண்ணியம் பெறுவான்; இங்கே ஸத்யதீர்த்தர் பாஷ்யம் முழுவதையும் எழுதினார்.",
        '0.13': "அங்கே இறைவனை வணங்கி, ஸ்வாமியின் சொல்லை மதித்து விரைவில் சீடர்களுடன் புறப்பட்டு, பல நாடுகளைக் கடந்து, குறையற்ற அறிவுடைய அவர் கோதாவரிக் கரையை அடைந்தார்.",
        '0.14': "பண்டிதர்களுக்குரிய பரிசுகளைப் பெற வந்திருந்த, பதினெட்டு வேதஶாகைகளை அறிந்த சோதிக்கும் பண்டிதர்கள் முன்வைத்த ஶ்ருதிகளுக்கு அவர் பொருள் கூறினார்; அங்கே ஆறு மதங்களையும் மறுத்தார்.",
        '0.15': "அவர்கள் ஒவ்வொருவரும் தத்தம் ஶாகையிலும் தர்ஶனத்திலும் அவரைச் சோதித்துத் தோற்று, 'கவியே, நீர் உண்மையில் ஸர்வஜ்ஞர்; உமக்கு நிகரில்லை' என்றனர்.",
        '0.16': "மூன்று வேதங்களின் எல்லாப் பக்ஷங்களையும் கற்பிப்பவரும் அச்சபையில் சிறந்தவரென மதிக்கப்பட்டவருமான ஶோபன பட்டர் என்பவர் மகிழ்ச்சியுடன் பூர்ணப்ரஜ்ஞரை மீண்டும் மீண்டும் வணங்கினார்.",
        '0.17': "தார்க்கிகர்களின் சிகாமணியும், அக்காலத்து மதங்களை மறுத்தவரும், வேதம் பாரதம் புராணங்களில் நிலைத்தவருமான அந்த அறிஞர் மத்வரிடமிருந்து இந்த பாஷ்யத்தைக் கேட்டார்.",
        '0.18': "இந்த அற்புதமான பாஷ்யத்தைக் கேட்ட பின் அவருக்கு வேறு எதிலும் விருப்பம் உண்டாகவில்லை; தாமரைத் தேனைச் சுவைத்த வெண்சிறகு அன்னம் வேறெதையும் விரும்பாதது போல.",
        '0.19': "ஆங்காங்குள்ள சபைகளில் ஒளிர்ந்து, ஆனந்ததீர்த்தரின் ஸித்தாந்தத்தில் சொல்லப்பட்ட யுக்திகளால் வாதிகளைச் சிதறடித்து வென்று, அவர் இத்தகுந்த சொற்களைக் கூறினார்:",
        '0.20': "'ஐயோ! பலவகைச் சங்குகளை நீற்றுச் சுண்ணாம்பாக்குபவன் ஒருவன், விலைமதிப்பற்ற வலம்புரிச் சங்கைப் பலமுறை முயன்றும் பொடியாக்க முடியாமல், அது பயனற்றதென்று எறிந்துவிட்டான்.",
        '0.21': "இத்தகைய அளவற்ற ஞானமுடைய, மிக அரிதான ஶாஸ்த்ரம் கைக்கு வந்தபோது அதைக் கைவிடுபவன் அந்தச் சுண்ணாம்புக்காரனுக்கு ஒத்த அறிவுடைய தீயவன்; அல்லது அவனைப் போன்ற இழிந்த அறிவுடையவர் வேறு யாருமில்லை.",
        '0.22': "அதன் சிறப்பை அறிந்த இன்னொருவன் அதை விற்று நிறையச் செல்வம் பெற்றான்; ஆனால் அதன் விலைமதிப்பற்ற தன்மைக்குரிய முழு மதிப்பை அவன் பெறவில்லை; இங்கே பாக்கியம் தகுதியைப் பின்பற்றுகிறது.",
        '0.23': "அதுபோலவே இந்த ஶாஸ்த்ரத்தால் வெளிப்படையான உயர்வைப் பெற்றாலும் அதன் முழுப் பயனைப் பெறாதவன், சிறிய மனத்தால், ஐயோ, அந்த மனிதனைப் போன்றவனாகிறான்.",
        '0.24': "தாராள குணமுடைய ஒரு மன்னன் அதைப் பெரும் விலைக்கு வாங்கி, பக்தியுடன் இடையறாது பூஜித்து, சொல்லுக்கும் மனத்துக்கும் எட்டாத செல்வங்களைப் பெற்றான்.",
        '0.25': "இந்த ஶாஸ்த்ரமாகிய கற்பகமரத்தின் முழுப் பயனை, அந்த உத்தம மன்னனைப் பின்பற்றுபவனைத் தவிர வேறு யார் பெற முடியும்?' என்று கூறி அவர் மக்களை மகிழ்வித்தார்.",
        '0.26': "இத்தகைய கவிஞர்களால் மட்டுமல்ல, நல்ல ஸித்தாந்தம் உதித்த திருவிழாவில் ஶிவன், இந்திரன், ப்ருஹஸ்பதி முதலிய தேவர்களாலும் பூஜ்யபாதர் நன்கு பூஜிக்கப்பட்டார்.",
        '0.27': "அவர் பயணித்தபோது, மழைக்காலம் தாழ்ந்த நிலத்தை விரைவில் நிரப்புவது போல, பெரும் துயர் நீக்கும் தம் தர்ஶன (ஸித்தாந்த) நீரால் நல்லோரை நிரப்பினார்; உயர்ந்த நிலம் போன்ற தீயோரை அல்ல.",
        '0.28': "உலகம் முழுவதையும் வியப்பிலாழ்த்தும் செயல்களால் வழியில் திரண்ட மக்களால் போற்றப்பட்டு, ரஜதபீடபுரத்தில் (உடுப்பியில்) ஒளிரும், 'ஶிவ' (மங்கலமானவன்) என்ற பெயரால் புகழப்படும் அனந்தாஸனனை வணங்கினார்.",
        '0.29': "அச்யுதனுக்குப் பிரியமான தஶப்ரமதி (மத்வர்) வந்து வணங்குவதைக் கண்ட அச்யுதப்ரேக்ஷருக்கு உண்டான மகிழ்ச்சிக்கு எல்லையே இல்லை.",
        '0.30': "முன்பே அனுப்பப்பட்ட இணையற்ற பாஷ்யத்தைக் கண்டு அந்த ஆர்ய யதி உயர்ந்த மகிழ்ச்சி அடைந்திருந்தார்; நீண்ட காலமாகக் காண விரும்பிய தூய புன்னகையுடைய அவரைக் கண்டு அதைவிட மிகுந்த மகிழ்ச்சி அடைந்தார்.",
        '0.31': "பூர்ணப்ரஜ்ஞர் என்னும் கடலிலிருந்து இன்பமளிக்கும் பாஷ்யம் என்னும் அமுதத்தை அந்த யதிராஜர் பெற்றார்; வியப்பு! இந்த மேகம் மக்களுக்கு அதை வழங்கியும் தான் அதை இழக்கவில்லை.",
        '0.32': "பிறகு நீதிமானான மத்வர், இயல்பாகச் சிறந்தவராயினும் காலத்தின் வசத்தால் தவறான மதத்தில் புத்தி ஆழ்ந்திருந்த தம் குருவுக்குப் பணிவுடன் பாஷ்யத்தின் நற்குணங்களை வர்ணித்தார்.",
        '0.33': "சந்தர்ப்பத்துக்கேற்ப நல்ல யுக்திகளுடைய சொற்களால் மீண்டும் மீண்டும் போதித்து, மருத்துவரைப் போல அந்த மஹாமதி குருவின் இதயத்தில் நிலைத்திருந்த விருப்பமின்மையின் மூலக் குறையைச் சிந்தித்தார்.",
        '0.34': "அரச அன்னம் திறமையான சிறகடிப்பால் அடித்து, உரத்த குரலால் அச்சுறுத்தி மானஸ ஸரோவரத்திலிருந்து காகத்தை விரட்டுவது போல, பரமஹம்ஸரான மத்வர் வலிமையான யுக்திகளாலும் கம்பீரக் குரலாலும் குருவின் மனத்திலிருந்து கலியின் மாசை அகற்றினார்.",
        '0.35': "அப்போது அச்யுதப்ரேக்ஷரின் மனம் களங்கமற்ற சந்திர மண்டலம் போலவும், மலர்ந்த தாமரை போலவும், கூதிர்காலத் தண்ணீர் போலவும் மிகத் தெளிவுடன் ஒளிர்ந்தது.",
        '0.36': "முன்பு தவறான மதத்தைப் பற்றியிருந்த அவர், மத்வ ஶாஸ்த்ரத்தைக் கேட்டு மகிழ்ந்தார் — மயக்கத்தால் உப்புநீர் குடித்த தாகமுள்ளவன் இப்போது அமுதத்தை மீண்டும் மீண்டும் பருகுவது போல.",
        '0.37': "பரந்த இதய வானில் நிலைத்த அந்த இரு யதிகளும் நல்ல ஸித்தாந்தத்தை ஒளிரச் செய்து, சந்திர சூரியர் இரவும் பகலும் இருளை அகற்றுவது போல, மனிதரை மயக்கும் பேரிருளை அகற்றினர்.",
        '0.38': "மிகுந்த அன்புடன் அவர் நல்லோருக்கு இரண்டு ஸுதர்ஶனங்களை ஏற்கச் செய்தார் — நல்ல ஸித்தாந்தத்தையும் ஸுதர்ஶன முத்திரையையும் (தப்த முத்திரை); இவை இயல்பாகவே பாவிகளுக்குப் பிடிக்காதவை, கொடிய பாவக் கூட்டத்தைப் பிளப்பவை.",
        '0.39': "ஒருமுறை ரஜதபீடபுரத்தில் இருந்தபோது, கபடமற்ற கருணையால் அவர், இறைவனைத் தவிர வேறு புகலற்ற நல்லோருக்கு ஸித்திக்கு வரும் தடைகள் முதலிய குறைகளுக்கு மருந்தளிக்க விரும்பினார்.",
        '0.40': "கோபியரின் காதலனான ஸ்ரீபதியின் கல் விக்ரஹத்தை தஶமதி (மத்வர்) மூன்று நான்கு சீடர்களைக் கொண்டு குளத்தில் சுத்தம் செய்வித்து, பிறகு தாமே அதை நீரில் மூழ்க வைத்து நீராட்டினார்.",
        '0.41': "மிகப் புனிதமான பகவானின் தீண்டலால் ஹரியின் ஸந்நிதானத்துக்கு இடமான, முப்பது பேர் சேர்ந்து தூக்கினாலும் தூக்க முடியாத அந்த விக்ரஹத்தை அவர் விளையாட்டாக மடத்துக்குக் கொண்டு சென்றார்.",
        '0.42': "அங்கே அவர் தூய ப்ரதிஷ்டையால், புன்முறுவலால் மென்மையான அழகிய முகமுடைய, புலன்களுக்கு எட்டாத வடிவுடைய நந்தநந்தனனின் வணங்கத்தக்க அழகிய விக்ரஹத்தை நிறுவினார்.",
        '0.43': "(43–46 ஶ்லோகங்கள் ஒரே வாக்கியம்.) தெய்வ அருளால் கிடைத்த திறமையால் செருக்குடையோரையும் வசப்படுத்தியவனும், தானே யாகம் நடத்துபவன் என்று எண்ணியவனும், 'ஜரா' (முதுமை) என்ற பொருளுடைய சொல் பெயரிலுள்ளவன் எனப்படுபவனுமான (முன்னாளைய ஜராஸந்தனைப் போன்ற) ஒரு தீயவன் இருந்தான்.",
        '0.44': "தமக்கு மிகப் பிரியமான யாகத்தைக் கெடுக்க முனைந்த அந்தப் பாவியைக் கண்டு, அரசன் முதலிய வல்லவர்கள் முன்னிலையில் அவனையும் அவன் நிறுத்திய மக்களையும் வென்று,",
        '0.45': "தம் ஒளியால் உலகை வியக்க வைப்பவரும், மக்களால் மீண்டும் திருவடி வணங்கப்படுபவரும், அற்புதமான திக்விஜயப் புகழுடையவரும், நாள்தோறும் தம்மவரை மகிழ்விப்பவருமான அவர்,",
        '0.46': "வாஸுதேவனுக்குப் பிரியமான அந்த மஹாமதி, அறநெறியாளரான வாஸுதேவன் என்ற அந்தணரைக் கொண்டு (குருவின் மகன்) யாகத்தை முறையாக நடத்துவித்தார் — முன்பு பீமனாக (ஜராஸந்தனைக் கொன்று) தர்மபுத்திரரைக் கொண்டு நடத்துவித்தது போல.",
        '0.47': "இந்த யாகத்தில் ஸர்வஜ்ஞரின் தம்பி (பின்னாளைய விஷ்ணுதீர்த்தர்) ஹோதாவாக இருந்து, யாஜ்யா அனுவாக்யா மந்திரங்களாலும் ப்ரவர்க்ய வைபவத்துடன் கூடிய துதிகளாலும் தேவர் கூட்டத்தை மகிழ்வித்தார்.",
        '0.48': "கூரிய அறிவுடைய அவர் சிறந்த வைஶ்வதேவ ஶஸ்த்ரங்களின் (துதிகளின்) கூரிய வரிசையை ஓதி, ராக்ஷஸர்களையும் அஸுரர்களையும் விரட்டி, வீரர் தலைவன் போலத் தேவர்களுக்கு அவரவர் பங்கைச் சேர்ப்பித்தார்.",
        '0.49': "மூன்று முறையும் முதலில் ஸோமம் பருகியவரும், எல்லாத் தேவர்களையும் வென்றவருமான வலிமைமிக்க வாயுவே கண்கூடான உடலுடன் விரும்பிய அந்த மஹாயாகத்தை யார் வர்ணிக்க முடியும்?",
        '0.50': "ப்ரஹ்மஞானத்தில் மனம் செலுத்தியவர்களுக்குக் கர்மம் அதற்குத் துணையான ஸாதனமாகும் என்று காட்ட, பரமாத்மாவை அறிந்த அவர் கர்மத்தையும் தர்மத்தையும் நடத்துவித்தார்.",
        '0.51': "ஆஹா! விரிந்த மனமுடைய அவருடைய எந்தெந்தச் செயல்களும், எந்தெந்த இனிய சொற்களும் உண்டோ அவை அனைத்தும் உலகை வியக்க வைத்து ஒளிர்கின்றன.",
        '0.52': "குல மரபைக் கடந்த பேரறிவாளர், உடலுடையோருக்கு வாழ்வளிக்கும் பல நதிகளைக் கடந்து (ஶ்லேஷம்: உலகியல் பயனைக் கூறுவது போலத் தோன்றும் வேத வாக்குகளின் உண்மைப் பொருளை அடைந்து), முன்பு போலவே களைப்பின்றி க்ருஷ்ணனுக்குப் பிரியமான உத்தம ஆஶ்ரமத்தை (பதரியை) மீண்டும் அடைந்தார்.",
        '0.53': "முன்பு ஹனுமான் வடிவிலிருந்த இவருக்கு ஹரி வேறு யாருக்கும் கிடைக்காத ஸஹபோகத்தை அளித்திருந்தான்; தன் விருப்பத்தை நிறைவேற்றியவருக்குப் பதிலாக அளிக்க அதைவிடச் சிறந்ததைக் காணாமல் அதையே பெருக்கினான்.",
        '0.54': "பிறகு உலகுக்கு நன்மை செய்யும் குருவை (வ்யாஸரை) மரியாதையுடன் வணங்கி, அவருடைய தகுந்த ஆணைப்படி சீடர்களுடன் புறப்பட்டு, பெருமனமுடையவரும் மகிமைக் கடலுமான அவர், தம்மவர் மகிழ்வுடன் எதிர்கொள்ள, ரஜதபீடத்தில் உறையும் ஹரியை வணங்கினார்.",
        '0.55': "இவ்வாறு கவிகுலதிலகரான த்ரிவிக்ரம பண்டிதாசார்யரின் மகன் நாராயண பண்டிதாசார்யர் இயற்றிய, 'ஆனந்த' முத்திரையுடைய ஸ்ரீஸுமத்வவிஜய மஹாகாவ்யத்தின் ஒன்பதாம் ஸர்க்கம் நிறைவுற்றது.",
      },
    },
    'sumadhva-vijaya-10': {
      verses: {
        '0.0': "பிறகு மாதவனின் குணங்களை நிலைநாட்டுபவனும், பாவ வழிப் பயணிகளுக்கு வெம்மை தருபவனுமான மத்வ சூரியன், வஸந்தத்தில் சூரியன் சுக்கிரனின் இடமான ரிஷபத்தை அலங்கரிப்பது போல, ப்ருகுகுலதிலகனான பரஶுராமனின் க்ஷேத்ரத்தை (துளுநாட்டை) உடனே நன்கு அலங்கரித்தான்.",
        '0.1': "தஶமதியின் சீடர் ஒருவர், ஆர்வத்துடன் பணிந்து நின்ற நல்லோர் கூட்டத்துக்காக, நாயகனைப் புகழும், பலவகை அழகிய விருத்தங்களுடைய காவியம் போன்ற சொற்களைக் கூறினார்.",
        '0.2': "'உலகை வியக்க வைக்கும் மத்வரின் செயல்கள் அனைத்தையும் தேவர்களின் ஆயுள் இருந்தாலும் எங்களால் சொல்ல முடியாது; ஆயினும் கேட்க விரும்புவோருக்காகச் சிறிது வர்ணிக்கப்படுகிறது.",
        '0.3': "ஒருமுறை வழிப்போக்கர்களைக் கொண்டு நிலம் தோண்டுவித்த ஈஶ்வரதேவன் என்ற அரசன் இவரையும் தோண்டும்படி தூண்டியபோது, இவர் 'நாங்கள் திறமையற்றவர்கள், செய்து காட்டி எங்களுக்குப் புரியவையும்' என்றார்.",
        '0.4': "அந்தத் தீயவன் தோண்டும் முறையைக் காட்டத் தொடங்கி, மஹாமதியின் மகிமையால் தன்வசமிழந்து தோண்டிக்கொண்டே இருந்தான், நிறுத்தவில்லை.",
        '0.5': "('ந' எழுத்தால் மட்டுமே அமைந்த சித்திர ஶ்லோகம்.) குறையற்ற இந்த மத்வரால் தூண்டப்படாதவர் யாருமில்லை; ஆனால் இவரால் தூண்டப்படாதவனும் யாருக்கும் குறைவற்றவனும் ஒருவனே — தலைவர்களுக்கும் தலைவனான பகவான்.",
        '0.6': "இவரை நினைப்பவர்களின் எல்லாப் பிறவிகளாலும் உண்டான துயரக் கடல் விலகுகிறது; இது வியப்பல்ல; இத்தகைய வாயுவைத் துதிப்பதில் ஶேஷன், ஶிவன், ப்ரஹ்மா முதலியோர் மகிழ்கின்றனர். (யமக ஶ்லோகம்.)",
        '0.7': "ஒருமுறை சஞ்சரித்தபோது, வணங்கத்தக்கவரும் வைஷ்ணவர்களில் முதன்மையானவருமான அந்தப் பிரபு, தம் நம்பிக்கைக்குரிய சீடர்கள் சூழ, பகைவர் அச்சத்தால் எல்லாப் படகுகளும் கைவிடப்பட்ட கங்கைக் கரையை அடைந்தார்.",
        '0.8': "தடுத்தவர்களைப் பொருட்படுத்தாமல், மூல ஆதாரமான கருணையாளர், தம் சொற்படி ஒருவரை ஒருவர் பற்றிக்கொண்ட சீடர்களை, பிறர் கடக்க முடியாத அந்த நதியை — ஸம்ஸாரத்தைக் கடத்துவது போல — விளையாட்டாகக் கடக்கச் செய்தார்.",
        '0.9': "'இவர்களைத் தடுங்கள், தடுங்கள் — பகைவரின் நண்பர்கள்! கரை சேரும் முன் கொல்லுங்கள், கொல்லுங்கள்!' என்று கூவிக்கொண்டு ஓடி வந்த துருஷ்க அரசனின் படைவீரர்களிடம் அவர் அவர்களுடைய மொழியிலேயே உரக்கக் கூறினார்:",
        '0.10': "'மூடர்களே, துணிச்சலுடன் நீரில் குதிக்காதீர்கள்! நீங்கள் பலர், எங்களால் உங்களுக்கு அச்சமில்லை; உங்கள் தலைவனான அரசனைக் காணவே வருகிறோம்; ஏன் சண்டையிட விரும்புகிறீர்கள்?'",
        '0.11': "இந்தச் சொற்களால், மந்திர வலிமையால் விஷவைத்தியன் பாம்புகளைத் தடுப்பது போல, அவர் பகைவரைத் தடுத்து, தம் பரிவாரத்தை மரண அச்சம் என்னும் நதியிலிருந்தும் தேவநதியிலிருந்தும் ஒரே நேரத்தில் கரையேற்றினார்.",
        '0.12': "ஆயிரக்கணக்கான கொடிய படைவீரர்கள் சூழ்ந்திருந்தும் மாறாத நடத்தையுடைய அந்த ஜகதீஶர், நரிக் கூட்டத்தின் நடுவே சிங்க அரசன் போல ஒளிர்ந்து நடந்தார்.",
        '0.13': "தேவர்களாலும் அஸுரர்களாலும் அசைக்க முடியாத உடலும் சிங்கம் போன்ற உறுதியான உடற்கட்டும் உடைய உயர்ந்த அவர் தன் நகரின் அருகே வந்ததை மாளிகையின் உச்சியில் நின்ற அரசன் கண்டு கூறினான்:",
        '0.14': "'நல்முகத்தோனே, பகை அரசர்களின் ஒற்றர்கள் என்ற ஐயத்தால் வழிப்போக்கர்களை வெட்டும் பணியில் உறுதிபூண்ட, யமதூதர்களைப் போன்ற என் கொடிய ஆட்களால் நீ எப்படிக் கொல்லப்படவில்லை?",
        '0.15': "படகின்றி தேவநதியை எப்படிக் கடந்தாய்? நீ என்ன செய்ய விரும்புகிறாய்?' என்று இவ்வாறு கேட்ட அவனுக்குப் புருஷோத்தமனின் மஹாதாஸரான அவர் பதில் கூறினார்:",
        '0.16': "'உலகுக்கு விளக்கான அந்த ஒளிமிக்க இறைவனின் அருளால் நாங்கள் எல்லாவற்றையும் செய்கிறோம்; இப்போது விரைவாக வடதிசைக்குச் செல்கிறோம்' — இத்தகைய அற்புதச் சொற்களை அவனுடைய மொழியிலேயே கூறினார்.",
        '0.17': "அவருடைய ஆழம், உறுதி, பெருவீரம், உயர்பண்பு, சிறந்த ஒளி, இடத்துக்கும் காலத்துக்கும் ஏற்ற பேச்சு ஆகியவற்றைத் தெளிவாகக் கண்டு வியந்த அரசன் உடனே பாதி ராஜ்யத்தை அவருக்கு அர்ப்பணித்தான்.",
        '0.18': "இவ்வாறு அரசனின் ஆட்களால் தண்டனைக்குரியவர் எனக் கருதப்பட்டவர் ராஜ்யத்துக்குரியவர் எனக் கருதப்பட்டார். வலிமையால் கடந்து செல்லக் கூடியவராயினும், ஆபத்தில் பின்பற்ற வேண்டிய நீதியைக் காட்டவே பிரபு அப்படிச் செய்தார்.",
        '0.19': "ஒருமுறை பாய்ந்து வந்த கள்வர் கூட்டத்தைக் கண்டு, தம்மவரை ஒருபுறம் நிறுத்தி, கையிலிருந்த துணி மூட்டையைச் செல்வம் என்று மயங்கச் செய்து அவர்களிடையே நடமாடி, அவர்களை மயக்கி ஒருவரையொருவர் தாக்கிக்கொள்ளச் செய்தார் — முன்பு அர்ஜுனன் ஸம்ஶப்தகர்களைச் செய்தது போல.",
        '0.20': "வேறோரிடத்தில் தம்மைக் கொல்ல வந்த நூறு வீரக் கள்வர்களை, புண்ணியர்களில் சிறந்த அவர் ஒரே ஒரு சீடரைக் கொண்டு (உபேந்த்ரதீர்த்தர்) அவர்களுடைய கோடரியைப் பறித்து அக்கூட்டத்தை அடிக்கச் செய்து விரைவில் ஓட்டினார்.",
        '0.21': "ஓரிடத்தில் கள்வர்கள் அவரையும் அவர் குழுவையும் பாறைக் குவியல் என்று மயங்கி விட்டுச் சென்றனர்; பிறகு அவர்களைக் கண்டு வியப்புடன் வணங்கினர்.",
        '0.22': "இமயத்தின் அருகே ஸத்யதீர்த்தரைக் கொல்லத் தானாக வந்த புலி வடிவ அரக்கனை ப்ராஜ்ஞர் கையின் விளையாட்டான சிறு அடியால் வீழ்த்தினார்.",
        '0.23': "அவர் நாராயணனிடமிருந்து (வ்யாஸரிடமிருந்து) தூய கல்லாலான ப்ரதிமைகளை (ஸாளக்ராமங்களை) பெற்றார்; அவற்றில் தீயோர்க்குப் பகைவனான பகவான் பத்மா (லக்ஷ்மீ) உடன் ஸந்நிதியுடன் உறைகிறான்.",
        '0.24': "உலகில் இவரையே புண்ணியர் எனக் கருதிய பாராஶர்யர் (வ்யாஸர்), பரதத்துவத்தை நிலைநாட்ட மஹாபாரதத்தின் உயர்ந்த தாத்பர்யத்தைத் தெளிவாகக் கூறும்படி இவரை நேரடியாகப் பணித்தார்.",
        '0.25': "க்ஷேத்ரங்களை அறிந்தவர்களில் சிறந்த ஸௌக்யதீர்த்தர் (ஆனந்ததீர்த்தர்) தீர்த்தங்கள்தோறும் க்ஷேத்ரங்கள்தோறும் கோவிந்தனை வணங்கி, சீடர்களுடன் உயர்ந்த அலைவரிசைகளுடைய கங்கைக்கு மீண்டும் வந்தார்.",
        '0.26': "படகுகளற்ற நதியையும், கரையில் அமர்ந்து மிகவும் வருந்திய சீடர்களையும் கண்டு, தாமரையின் நண்பனான சூரியன் கடலை அடையும் (மறையும்) வேளையில் அவர் அந்த நதியைக் கடந்தார்.",
        '0.27': "கடலைத் தாண்டிய வானரேந்திரனாகவும், இதே நதியில் விளையாடிய நரேந்திரனாகவும் (பீமனாகவும்) இருந்த அவருடைய முந்தைய வடிவங்களைச் சீடர்கள் நினைக்கவில்லை; இல்லையெனில் வல்லமையுடைய அவருக்கு ஆபத்தை எப்படி ஐயுறுவர்?",
        '0.28': "உலகுக்கு விளக்கான கதிர்களுடைய (சொற்களுடைய) வானச் சூரியனும் மத்வச் சூரியனும் மறைந்தபோது, தாமரைகளுடன் சீடர்களின் கண்தாமரைகளும் உடனே ஒளியிழந்தன.",
        '0.29': "விநதையின் மகனான கருடன் பசுவின் குளம்படித் தடத்தைக் கடப்பது போல, அச்சமின்றி நதியைக் கடந்தவரும் ஆடை நனையாதவருமான அவரை, வியப்பால் உருகிய அரசர்கள், அந்தணர்கள் முதலியோர் வணங்கினர்.",
        '0.30': "பிறகு பகைவர் அச்சத்தால் படகு செலுத்தாதிருந்த, இப்போது அவருடைய ஒளியால் வியந்த அரசன் அனுப்பிய படகோட்டிகளைக் கொண்டு அவர் சீடர்களைப் படகில் நதியைக் கடக்கச் செய்தார்.",
        '0.31': "ஸ்வாமியைக் காண ஏங்கிய சீடர்கள், விளக்குகளால் ஒளிரும், மக்கள் நிறைந்த, கேள்வி கேட்கும் பண்டிதர் குழாம் நிறைந்த தேவநதியின் அகன்ற கரையைக் கண்டனர்.",
        '0.32': "அங்கே தேவசபையில் தாமரையில் பிறந்த ப்ரஹ்மாவைப் போல, வேதமறிந்தோருக்கு வேதத்தை அதன் கருத்து வேறுபாடுகளுடன் விளக்கிக்கொண்டிருந்த ஸுகதீர்த்தரை அவர்கள் நேரில் கண்டனர்.",
        '0.33': "பிறகு ஹஸ்தினாபுரத் தலைநகரை அடைந்து, எண்ணற்ற குணங்களுடைய அவர் அங்கே நதிக்குத் தொலைவிலுள்ள தனிமையான இடத்திலிருந்த வேறொரு மடத்தில் வசிக்கத் தகுந்த (சாதுர்மாஸ்ய) மாதங்களைக் கழித்தார்.",
        '0.34': "தேவநதி பூமியைப் பிளந்து ஒரு தனிக் கிளையாக அவருக்குச் சேவை செய்ய வந்தாள்; ஶிவன் முதலியோரால் வணங்கப்படும் வாணியும் (பாரதியும்) இவருக்குப் பணிவிடை செய்து நிறைவு பெறும்போது இதில் என்ன வியப்பு?",
        '0.35': "உடல் தாங்கிய அவள் அந்தக் குருசிரேஷ்டரின் தாமரைத் திருவடிகளை தொலைவிலிருந்தே வணங்கினாள்; வள்ளன்மையும் அழகும் உருவெடுத்த அவ்வடிவைக் கண்டு சீடர்கள் மிகவும் வியந்தனர்.",
        '0.36': "பிறகு ஒருமுறை வாராணஸிக்கு வந்த பாவம் போக்குபவர், விளையாட்டு நேரத்தில் செருக்குற்ற வலிமையான சீடர்களைக் கண்டு இவ்வாறு கூறினார்:",
        '0.37': "'வீரர்கள் என்று எண்ணும் நீங்கள் அனைவரும் மல்யுத்தத்துக்காக ஒரே நேரத்தில் இப்போதே என்மேல் பாயுங்கள்; தன் முழு வலிமையைப் பயன்படுத்தாதவன் என் ஆணையை மீறுகிறான்.'",
        '0.38': "இவ்வாறு கூறி, சண்டையிட்டுப் பாய்ந்த பதினைந்து இளைஞர்களையும் ஒரே நேரத்தில் வீழ்த்தி, 'வல்லமை உள்ளவன் எழுந்திருக்கட்டும்' என்று கூறி மெல்லச் சிரித்தார்.",
        '0.39': "அப்போது அவர்கள் 'கருணையுள்ள ஸ்வாமியே, எங்கள் உடல்மேல் உள்ள உங்கள் அங்கங்களும் விரல்களும் மேரு மலையளவு கனக்கின்றன; நாங்கள் விரைவில் அழிந்துவிடுவோம்; விட்டுவிடுங்கள்' என்றனர்.",
        '0.40': "அவரால் விடுவிக்கப்பட்ட சீடர்கள் மிகவும் வியந்தனர்; யாருடைய புருவ அசைவாலேயே ஶம்பு, ஶக்ரன் உட்பட உலகம் முழுவதும் முற்றிலும் நியமிக்கப்படுகிறதோ அந்த அவருடைய ஸ்வரூபத்தை அவர்கள் எண்ணிப் பார்க்கவில்லை.",
        '0.41': "எல்லாப் பக்ஷங்களையும் தள்ளிய, திறமையான அமராவதீ (இந்த்ரபுரி) என்ற பெயருடைய ஒரு யதி, பிரபுவை வெல்ல விரும்பி, 'ஞானத்தின் துணையுடைய கர்மமே ஸாதனம் என்பதை நிரூபியுங்கள்' என்றார்.",
        '0.42': "பகவானைப் பற்றி அது நிரூபிக்கப்பட்டபோது, யுக்தி தோன்றாத கடுமையான அறிவுடையவன் 'ஞானம்' என்ற சொல்லின் பொருள் என்ன என்று கேட்டான். 'நீ ஞானியானால் அது உனக்குத் தெரியும்; இல்லையெனில் இந்தக் கேள்வியே எழாது' என்று அவனை மறுத்தார்.",
        '0.43': "கூதிர்காலத்தில் சந்திரன் நிலவின் செல்வத்தால் தாமரைகளை மூடச் செய்து ஒளிர்வது போல, வ்யாஸரின் சீடர் பரந்த இருளை முற்றிலும் முடிக்கும் விளக்கவுரையால் சபைதோறும் ஒளிர்ந்தார்; எல்லா மதத்தினரும் கைகூப்பியதைக் கண்டு மகிழ்ந்தார்.",
        '0.44': "(யமக ஶ்லோகம்; கருத்து:) எல்லா ஶாஸ்த்ரங்களிலும் புகழ்பெற்ற பகவான் மாயையால் அல்ல, தன் சுதந்திர விருப்பத்தால் ஒவ்வொரு யுகத்திலும் உலகின் படைப்பு, காப்பு, அழிப்பைச் செய்கிறான்; தான் மாறாமல் ஞான வடிவாக இருக்கிறான் என்று அவர் போதித்தார்.",
        '0.45': "'சுதந்திரனான விஷ்ணு அனைத்துக்கும் மேலாகத் தலைமை தாங்கி இதில் இடையறாது விளையாடுகிறான்; தீயோரைக் கீழே தள்ளுகிறான், நல்லோரைச் செம்மைப்படுத்துகிறான்; குணங்கள் நிறைந்தவனாயினும் (ப்ராக்ருத) குணங்களற்றவன்.'",
        '0.46': "'ஸ்ரீபதிக்கு நிகரானவரும் மேலானவரும் இல்லை; அவன் உலகத்திலிருந்து முற்றிலும் வேறுபட்ட இயல்புடையவன்' — இவை முதலிய உயர்ந்த உண்மைகளை அவர் நன்கு வெளிப்படுத்தினார்.",
        '0.47': "(சில எழுத்துக்களால் மட்டுமே அமைந்த சித்திர ஶ்லோகம்; கருத்து:) ப்ரமாணங்களை அடிப்படையாகக் கொண்ட அவருடைய ஸித்தாந்தம் பரவிய மாயாவாதத்தால் ஒருபோதும் தோற்கவில்லை; அதை எதிர்ப்பவர்கள் வேதனை அடைகின்றனர்.",
        '0.48': "ப்ராஜ்ஞர் அரசர்களுக்கு ஸ்வர்க்க வழியான குருக்ஷேத்ரத்தை அடைந்து, (பீமனாக) தம் விளையாட்டிலேயே யானைகள் வீழ்ந்த போர்த் திருவிழாக்களை நினைவுகூர்ந்தார்; வியப்புற்றவர்களும், அவருடைய முந்தைய அரச உடலின் கதையைக் கண்டு மிக மகிழ்ந்தவர்களுமான ஸத்யதீர்த்தர் முதலியோர் அவரைச் சூழ்ந்திருந்தனர்.",
        '0.49': "ஹ்ருஷீகேஶத்தில் வெண்ணிற ஒளியுடைய ஈஶன் (ருத்ரன்) அந்தண வடிவில் ஒரு கணம் வணங்கி, தெளிவாகத் தெரிந்தும் உடனே மறைந்து மக்களை வியக்க வைத்தான்; கனவில் தூண்டிய வேற்றூர் அடியவனைக் கொண்டு வரவழைத்த ஏராளமான உணவுகளால் அனைவருக்கும் குருவான தன் குருவுக்கு விருந்தளித்து, அவர் வேதத்தின் உண்மை உறவினர் என்று அறிவித்தான்.",
        '0.50': "மீண்டும் இஷுபாதத்தை அடைந்து அவர் ரமாபதியான பரஶுராமனை மரியாதையுடன் நினைத்தார்; அங்கே அரசன் உணவுக்காக அளித்த ஆயிரம் சிறந்த பெரிய ராஜகேளி வாழைப்பழங்களை உண்டார்.",
        '0.51': "கோவா என்ற நாட்டுக்குச் சென்று, ஶங்கரன் என்ற அந்தணன் கொண்டு வந்த நாலாயிரம் பெரிய அழகிய வாழைப்பழங்களை உண்டு, முப்பது குடம் பாலைப் பருகினார்; (தடுக்க) முனைந்த அரசனின் ஆட்களுக்குத் தெரியாமல் முன்னே சென்றார்.",
        '0.52': "அதே கோவாப் பகுதியில் ஓரிடத்தில் சபையில் மக்களின் வேண்டுகோளின்படி, மக்களுக்கு உறக்கம் வரவழைக்கும் தம் இணையற்ற இசைச் செல்வத்தால் அவர் விரைவில் (மரங்களில்) பூவையும் பழத்தையும் தோற்றுவித்தார்.",
        '0.53': "புண்ணியரான மத்வர் போற்றப்பட்டார் — தேவர் பகைவரின் இதயத்துக்கு அம்பு போன்றவர், ப்ரஹ்மாவுக்குச் சமமானவர், தவறான ஆகமங்களை அழித்தவர், சிறந்த சந்திரனின் ஒளியுடையவர், காமத்தையும் மாயையையும் நீக்குபவர்; உலக வெற்றி அருளும், வழிபடத் தக்க, இன்பம் நிறைந்த ஸ்ரீதர விஷ்ணுவை மகிழ்வுடன் வணங்கும், நோய் முதலியவை அற்ற யோகி, எப்போதும் அனைவருக்கும் நண்பர்.",
        '0.54': "'இவ்வாறு உலகுக்கு அணிகலனான இவருடைய எண்ணற்ற இன்னும் பல செயல்கள் கேட்டல், சிந்தித்தல், பாடுதல் மூலம் விரும்பியதை அருள்கின்றன' என்று அமரர்கள் புகழ்கின்றனர்.",
        '0.55': "இவ்வாறு ஹரியின் திருவடியில் ஈடுபட்ட, கல்வி என்னும் மின்னலால் திசைகளை ஒளிரச் செய்த அந்த அறிஞர் மேகம் (சீடர்), பலவகைச் சொல்மழையால், ஸம்ஸார அச்சம் என்னும் வெயிலால் வாடிய நல்லோர் என்னும் மரக்கூட்டத்தைப் பழங்களும் மலர்களும் (நல்ல மனங்களும்) நிறைந்ததாகவும், அடர்ந்த இன்பமுடையதாகவும், ஆபத்தற்றதாகவும் ஆக்கியது.",
        '0.56': "இவ்வாறு கவிகுலதிலகரான த்ரிவிக்ரம பண்டிதாசார்யரின் மகன் நாராயண பண்டிதாசார்யர் இயற்றிய, 'ஆனந்த' முத்திரையுடைய ஸ்ரீஸுமத்வவிஜய மஹாகாவ்யத்தின் பத்தாம் ஸர்க்கம் நிறைவுற்றது.",
      },
    },
    'sumadhva-vijaya-11': {
      verses: {
        '0.0': "ஸனகாதி முனிவர்களுடன் நாகராஜனான ஶேஷன் ஆழ்ந்த பொருளுடைய அவருடைய ப்ரவசனத்தைக் கேட்டு, இங்குள்ள மக்களுக்கு வானில் சற்றே தென்பட்டு, விரைவில் தன் ஒளியை மறைத்துத் தன் இருப்பிடத்தை அடைந்தான்.",
        '0.1': "பணிவையே அணிகலனாகக் கொண்ட முனிவர்கள், மிக அற்புதமான தன் இருப்பிடத்தில் மகிழ்ந்திருந்த ஆயிரம் தலைகளுடைய அனந்தனை வணங்கி, அதைப் பற்றி இந்தச் சிறந்த கேள்வியைக் கேட்டனர்:",
        '0.2': "'உலகத் தலைவனே, மிகச் சிறந்த பகவத்பக்தரும் பேரறிவாளருமான அவருடைய ஸித்தாந்தம் உலகில் மிக இனியது, உங்களாலும் போற்றப்பட்டது; அதை மீண்டும் மீண்டும் கற்பவருக்கு என்ன பயன் உண்டாகும்?",
        '0.3': "தகுதியுடைய அறிஞர்களுக்குப் பயன் தெரிந்தால் அவர்களுடைய முயற்சி மிக வலிமையாகும்; ஆகவே பயனுள்ள சொற்களுடைய பெருங்கருணையாளரான தாங்கள் அப்பயனை விரிவாகக் கூறுங்கள்.'",
        '0.4': "அவர்கள் கூறிய இச்சொற்களைக் கேட்டு உயர்ந்த மனமுடைய ஶேஷன் கூறினான்: 'பூஜ்யபாதரின் ஸித்தாந்தத்தின் மிக மகிமை வாய்ந்த பயனை மரியாதையுடன் கேளுங்கள்.",
        '0.5': "ஸ்வர்க்கம் முதலியவை இதனால் கிடைத்தாலும், உழவுக்கு வைக்கோல் பயனாகாதது போல, அவை இதன் பயன் எனப்படுவதில்லை; ஶுகர், ஶாரதை முதலிய பரமார்த்த ஞானிகளின் சொற்படி இதன் உண்மைப் பயன் மோக்ஷ நிலை.",
        '0.6': "மனிதருக்கு அப்பாற்பட்ட கலையால் இயற்றப்பட்ட, உயர்ந்த ஆகமங்களின் பொருளுடைய இந்தச் சிறந்த ஶாஸ்த்ரத்தைப் பயின்று பரம வைஷ்ணவர்களாகுபவர்களுக்கு வெல்லப்படாத ஹரி மகிழ்ச்சிக்காகத் தன் உலகை அளிக்கிறான்.",
        '0.7': "அங்கே உலகின் எல்லாச் சிறப்புக்கும் ஒரே இருப்பிடமான பூர்ண புருஷனின் நகரம் ஒளிர்கிறது; அதற்கு உவமை அதன் ரத்தின மதில்களில் தெரியும் அதன் சொந்தப் பிரதிபிம்பம் மட்டுமே.",
        '0.8': "சுற்றிலும் வெண்மாளிகைகளின் ஒளியால் மின்னும் மாணிக்க வீடுகளின் வரிசை, என் வெண்ணுடல் சுருளில் ஒளிரும் அஸுரரை அழிக்கும் ஹரியின் திருவுருவைப் போலத் தோன்றுகிறது.",
        '0.9': "ஒவ்வொரு வீட்டிலும் பலவகை வரிசைகளில் பதித்த பளிங்கின் ஒளியுடைய மரகதக் கூரைகள், கங்கையின் வெண்ணீருடன் கலந்த யமுனை போலத் தோன்றுகின்றன.",
        '0.10': "வீட்டு வரிசைகளின் சாய்வுகளில் செதுக்கிய பறவைகள் அவ்வளவு உயிரோட்டமுள்ளவை; அங்குள்ள மக்கள் அவ்வுலக நியதிப்படி மயக்கமற்றவர்களாக இல்லையெனில் அவை செயற்கை என்று ஒருபோதும் அறிந்திருக்க மாட்டார்கள்.",
        '0.11': "உத்தரங்களில் கட்டிய சித்திரத் துணி விதானங்களிலிருந்து தொங்கும் ரத்தின மாலைக் கொத்துகள் வீடுகளுக்குள் நிறைந்து வழிந்து, செல்வமே பொங்கி வழிவது போல ஒளிர்கின்றன.",
        '0.12': "அங்கே தூய வடிவுடைய ப்ரக்ருதியே மாமணிகளும் பொன்னுமான எல்லாப் பொருள்களும் ஆகிறாள்; ஆகவே அனைத்து அழகுச் சாரமும் இங்கே உண்மையில் சாத்தியம்; கவிஞர்கள் வேறிடத்தில் மிகைப்படுத்திக் கூறுவது இங்கே உண்மை.",
        '0.13': "தொடக்கமற்ற காலம் முதல் முக்தரான ஶம்பு முதலியோரின் எண்ணற்ற கூட்டங்கள் அங்கு இருந்தும், நகரங்கள் நிறைந்த அந்த மாநகரம் நெரிசலாவதில்லை; ஆஹா, இது பிரபுவின் மகிமை!",
        '0.14': "மூவுலகின் அற்புதக் குணங்களையும் விஞ்சும், உலகங்களின் ஒரே தலைவனின் மாளிகை, சிறந்த மாளிகைகளின் நடுவே நட்சத்திர மண்டலத்தின் நடுவிலுள்ள சந்திர மண்டலம் போல ஒளிர்கிறது.",
        '0.15': "ஆயிரம் பணிப்பெண்கள் பணிந்தாலும் இந்திரையே கணவனைப் போற்றி வீட்டுப் பணியை நன்கு செய்யும் அந்த மாளிகையின் சிறப்பை யார் வர்ணிக்க முடியும்?",
        '0.16': "அங்கே தன்னிலே மகிழ்பவனாயினும் பரமனான கமலாபதி அழிவற்ற நாகராஜனின் மென்மையான உடலில் சாய்ந்து, தூயவளும் அழகியும் தாமரைக் கண்ணியுமான கமலையுடன் விளையாடுகிறான்.",
        '0.17': "ஆயிரம் உதய சூரியர்களின் ஒளியுடைய, பொன்னாடை அணிந்த, ரத்தின அணிகள் பூண்ட, சிரிக்கும் சந்திர முகமுடைய, தாமரைக் கண்ணனான, சக்கரராஜனைத் தாங்கிய அவனை நினையுங்கள்.",
        '0.18': "அவனுடைய எல்லாக் குணங்களையும் ரமையும் எண்ண முடியாது, சொல்வன்மையுடைய நான்முகனும் எண்ண முடியாது; ஆயிரம் வாய்களுடைய நாங்களும் பிறர் கூறியதற்கு மேல் கூற முடியாது.",
        '0.19': "எண்ணற்ற ப்ரஹ்மாக்கள், கருடர்கள், ஶேஷர்கள், இந்திரர்கள் முதலியோர் தம் துணைவியருடன் பரமனோடு கூடிய பேரின்பத்தைப் பெற்று அவனைக் கண்டு ஆனந்தச் சாரத்தை அனுபவிக்கின்றனர்.",
        '0.20': "இங்கே தலைவனைப் போன்ற ஒளியுடைய புருஷர்கள் உலவுகின்றனர் — நான்கு கைகளுடையவர், தாமரைக் கண்ணர், மஞ்சள் ஆடை அணிந்த அழகிய வேடத்தினர், சிலர் விடியல் ஒளியினர், சிலர் இளம் மேக நிறத்தினர்.",
        '0.21': "பகவானின் அருகே சேர்ந்தவர்களுக்கு மட்டும் இணையற்ற இன்பம் என்பதில்லை; உலகுக்கு அப்பாற்பட்ட குணமுடைய அவனுடைய உலகில் வாழ்வோருக்கும் சிறு புண்ணியர்க்கு அரிதான இன்பம் உண்டு.",
        '0.22': "அங்கே மரணம், பிறப்பு, முதுமை இல்லை; மூவகை அச்சம் இல்லை, துயரக் கூட்டத்தைப் பற்றிச் சொல்வானேன்; வேறு எந்த அமங்கலமும் இல்லை, அதன் மூலமான (ப்ராக்ருத) குணங்களும் இல்லை.",
        '0.23': "அனந்தனின் தோழர்களான அவர்கள் அனைவரும் நிறைவு தரும் அளவு இன்பத்தை இடையறாது அனுபவிக்கின்றனர்; தாரதம்யம் உள்ளவர்களாயினும் தம் பெரியோரிடம் பக்தியும் ஒருவருக்கொருவர் ஆழ்ந்த அன்பும் உடையவர்கள்.",
        '0.24': "இங்கே என்றும் இளமையுடைய, மிக அழகிய, இளம்பிறை ஒளியுடைய ஹரிசந்தனத்தால் மணக்கும் அந்தப் புருஷர்கள் அழகிய சாமரம் வீசும் பணியாளர்களுடன் உலவுகின்றனர்.",
        '0.25': "ஒயிலான நடனங்களால் நிறைவுற்ற கண்களும், இனிய பாடல் இசைக்கருவிகளால் மகிழ்ந்த செவிகளும், புதுத் தாமரைக் கண்களும் உடைய இக்காதலர்கள் தம் இளம் துணைவியரை மகிழ்விக்கின்றனர்.",
        '0.26': "மான்விழி மங்கையர், சோலை நோக்கிச் செல்லும் கணவர்களைப் பின்தொடர்ந்து, சந்திர மண்டலத்திலிருந்து அழகிய கதிர்கள் வெளிப்படுவது போல, தூய விமானக் கூட்டத்திலிருந்து மெல்ல வெளியே வருகின்றனர்.",
        '0.27': "அவர்களுள் சிலர் மாணிக்க நிறமுடைய மெல்லிய உடலினர், சிலர் சிறந்த முத்துமாலை போன்ற ஒளியினர், மற்றும் சிலர் இந்திரநீலம் போன்ற நீல ஒளியினர் — பலவகை அணிகலன்களுடன் தோன்றுகின்றனர்.",
        '0.28': "நிலையான ஒளியுடைய, மிக நுண்ணிய ஆடை அணிந்த, கிளி போன்ற இனிய குரலுடைய, அழகிய கொங்கைகளுடைய இவர்கள் உண்மையில் இன்னொரு மேக வரிசை போலத் தோன்றுகின்றனர் (ஆனால் கணநேர மின்னலுடைய மேகங்களிலிருந்து வேறானவர்).",
        '0.29': "இந்த அழகிய கண்ணியரின் தளிர் போன்ற பாதங்களின் நகங்களின் செவ்வொளி, பவளத் தரையைக் கடக்கும்போது தெரியாதது, பளிங்குத் தரையில் மாறுபாட்டால் வெளிப்படுகிறது.",
        '0.30': "மான்விழியாரின் அழகிய ஆடைகள், அவர்களுடைய அகன்ற இடை தொடைகளின் ஒளியால் பல நிறமுடையனவாகி, மன்மதனின் உலக வெற்றிக் கொடிகள் என்று நாம் உறுதி செய்கிறோம்.",
        '0.31': "(31–33 ஶ்லோகங்கள் சேர்ந்து வர்ணிக்கின்றன.) மீண்டும் மீண்டும் ஒலிக்கும் பொன் வளையல்களுடன் அசையும் அழகிய தளிர்க் கைகளாலும், புது மயிர் ஒழுங்கும் மடிப்புகளும் அழகூட்டும், சிறிதே அசையும் மென்மையான மெல்லிய வயிறுகளாலும்;",
        '0.32': "ஒவ்வோர் அடியிலும் மார்பில் மெல்ல அசையும், கொங்கைக் குடங்களிலிருந்து வழியும் ஒளியமுதின் சிதறிய துளிகள் போல மின்னும் சிறந்த மாலைகளாலும்;",
        '0.33': "விளையாட்டாகக் குவளை மலர்களைப் பிடித்த அல்லது தோழியர் மேல் வைத்த மற்றக் கைகளாலும், தூய புன்னகையும் ஓரக்கண் பார்வையும் நிறைந்த, அசையும் குண்டலங்களால் ஒளிரும் கன்னங்களுடைய முகங்களாலும் (அவர்கள் விளங்குகின்றனர்).",
        '0.34': "அவர்கள் முன்னே செல்லும்போது, ரத்தின ஒட்டியாணம் சிலம்புகளின் ஒலியால் அழைக்கப்பட்டது போல, இளம் கணவர்கள் அவர்களுடைய உடல் ஒயிலைக் காண முகம் திருப்புகின்றனர்.",
        '0.35': "தம் காதலர்களால் காத்திருக்கப்பட்ட அக்காதலியர் கொங்கைச் சுமையால் வளைந்து எப்படியோ அவர்களை அடைந்து, அவர்களுடைய துணையின் வலிமையால் மெல்லச் சிறந்த சோலைக்குள் நுழைகின்றனர்.",
        '0.36': "சிரிக்கும் மலர்க் குவியலின் சுமையால் வளைந்த பொன், ரத்தின மரங்கள் அனைத்தையும் தழுவும், அமுதக் கடலின் நண்பனான காற்று யாருடைய இன்பத்தைப் பெருக்காது?",
        '0.37': "இந்திரனின் தெய்வச் சோலை எல்லோரையும் நியதியாக மகிழ்விப்பதில்லை, ஆகவே அது உபசாரமாக மட்டுமே 'நந்தனம்'; எல்லோரையும் எப்போதும் மகிழ்விக்கும் உபேந்திரனின் சோலையே உண்மையான நந்தனம்.",
        '0.38': "வியப்பு! சிறந்த பாரிபத்ரகம், கற்பகம், பாரிஜாதம், ஹரிசந்தனம் முதலிய மரக் கூட்டங்கள் நிறைந்த அச்சோலையை எல்லாப் பருவங்களும் ஒருசேர அலங்கரிக்கின்றன.",
        '0.39': "சிரிக்கும் மாதவீ மலர்களால் அழகிய, புதுச் செண்பகம் முதலிய மலர்களால் ஒளிரும், வண்டுகளின் ரீங்காரத்தால் இனிய மது, மாதவ (வஸந்த) மாதங்கள் மதுவைக் கொன்றவனின் அன்பர்களுக்கு மகிழ்ச்சி தருகின்றன.",
        '0.40': "அன்புக் கணவன் ஶுசி (கோடை) மாதத்தில் மலர்ந்த புது மல்லிகை மாலையைத் தானே காதலியின் தலையில் சூட்டி, 'உனக்குச் சரியாக வராது' என்று சாக்குச் சொல்லி அவளுடைய பருத்த மார்பகங்களைத் தன் மார்போடு அணைக்கிறான்.",
        '0.41': "மழைக்காலத்தில் இனிய குரலுடைய மயில்கள் விரித்த தோகை வரிசையில் தெளிவாகத் தெரியும் கண் குறிகளுடன், தம் நடனத் திருவிழாவில் மழைப்பருவத்தின் அடையாளமான ஆயிரம் கண்ணுடைய இந்திரனைப் பின்பற்றுகின்றன.",
        '0.42': "கூதிர்காலத்தில் மலர்ந்த குவளை போன்ற கண்களும், மலர்ந்த தாமரை போன்ற அழகிய முகமும், கிளி போன்ற இனிய குரலும், அன்னம் போல ஒலிக்கும் சிலம்பும் உடைய காதலியுடன் மக்கள் மகிழ்கின்றனர்.",
        '0.43': "பளிங்கு மலை போலப் பனியைப் பரப்பிய முன்பனிப் பருவத்தை அதன் தோழனான பின்பனிப் பருவம் வரவேற்று, கொடிகளை மலரச் செய்து, மலர்ந்த புது முல்லை மலர்களின் ஒளியால் சிரிப்பது போலத் தோன்றுகிறது.",
        '0.44': "வியப்பு! வேறிடத்தில் பனி, குளிர், மழை, வெயில் முதலிய குறைகளுக்கு மூலமான பருவக் குணங்கள் இங்கே முக்தர்களுக்கு எப்போதும் இனிமையையே தருகின்றன — பருவங்களும் முக்தி பெற்றது போல.",
        '0.45': "அங்கே மக்கள் அமுத வடிவான ஹரிக்கு அமுத மாலைகளையும் சிறந்த பழங்களையும் மலர்களையும் அர்ப்பணிக்கின்றனர்; விதியின் கட்டு இல்லாவிடினும் அனுபவிக்க விரும்பி அனைவரும் எப்போதும் தம் இயல்பையே (பக்தியையே) பின்பற்றுகின்றனர்.",
        '0.46': "மிகுந்த மகிழ்ச்சியுடன் கணவர்களுடன் சோலையில் உலவும் மகளிர் கூட்டம் மதுவைக் கொன்றவனின் சரிதத்தை இடையறாது இனிமையாகப் பாடுகிறது.",
        '0.47': "சில அழகியர் கணவனருகே விளையாடுகின்றனர், சில நளினியர் மலர் கொய்கின்றனர், மற்றவர் மாலை தொடுக்கின்றனர்; கணவரை மகிழ்விக்காதவர் யாருமில்லை.",
        '0.48': "பலவகைச் சோலை விளையாட்டுகளால் மகிழ்ந்த இளைஞர்கள் கொடிப்பந்தல்களில் பருத்த மார்பகச் சுமையால் வளைந்த இளம் மனைவியரைத் தழுவி, அவர்களுடைய முகத்தாமரைகளின் வண்டுகள் போலக் காதல் இன்பம் கொள்கின்றனர்.",
        '0.49': "பிறகு இன்பம் விரும்பும் மங்கையர் — அவர்களுடைய சிலம்பொலியை நாரைகள் பின்பற்ற — அமுத நீர்க் குளங்களில் கணவர்களுடன் மூழ்கி, நீர் விளையாட்டுத் திருவிழாவில் சிரிக்கும் முகங்களுடன் விளையாடுகின்றனர்.",
        '0.50': "நீரில் பலவகை விளையாட்டுகள் ஆடி, அகன்ற பவளக் கரைகளுக்கு வந்து அம்மகளிர் தோழியரின் கையிலிருந்த மணமுள்ள பொன்னிறப் பூச்சைப் பெற்றுக்கொள்கின்றனர்.",
        '0.51': "தாமரைக் கண்ணியர் ஒருவருக்கொருவர் இடைக்கு ஆடை, அங்கங்களுக்கு அணிகள், கொங்கைகளுக்குக் குங்குமம், கூந்தலுக்குச் சிறந்த மாலை, கண்களுக்கு மை அணிவித்து முழுமையாக அலங்கரிக்கின்றனர்.",
        '0.52': "மெல்லிடையார் தம் வீடுகளுக்குச் சென்று, உயிருக்கு நிகரானவராயினும் ஒப்பற்றவருமான கணவர்களுடன் பொன், ரத்தினக் கிண்ணங்களில் உலகியலாருக்கு அரிதான அமுதத்தைப் பருகுகின்றனர்.",
        '0.53': "அலங்கரித்த கண்களுடைய மங்கையர் தக்க நேரத்தில், தூண்டப்பட்டாலும், அன்புக் கணவர்களின் ரத்தினக் கட்டிலின் மென்மையான அழகிய படுக்கையில் மெல்ல ஏறுகின்றனர்; பணிவே எல்லாச் சுவைகளையும் அழகுபடுத்துகிறது.",
        '0.54': "பூச்சூடிய கூந்தலைக் கட்டியவாறு கணவன் முன் நின்ற, மார்பை உயர்த்திய, தோள் அடி மடிப்புகள் தெளிவாகத் தெரியும் அழகியை அன்புக் கணவன் மிகுந்த காதலுடன் தழுவுகிறான்.",
        '0.55': "இங்கே எந்த இன்புற்ற காதலன், காதலியின் பருத்த உயர்ந்த திண்ணிய மார்பகங்கள் இருவரின் நெருக்கத்தைத் தடுத்தாலும், தன் இரு கைகளாலும் அவளைத் தழுவி மகிழ்விக்க மாட்டான்?",
        '0.56': "புன்னகையால் மலர்ந்த, மின்னும் ரத்தினக் குண்டலங்களால் விளங்கும், மென்மையான ஓரப்பார்வையில் தேர்ந்த அழகியின் முகத்தை அன்புக் கணவன் அமைதியாக நெடுநேரம் நோக்கி முத்தமிடுகிறான்.",
        '0.57': "நாணத்தால் தாழ்ந்த அழகிய கண்ணியின் முகச் சந்திரனை உயர்த்தி, தழுவலின் இன்பம் நிறைந்த இளைஞன் இனிய இதழமுதைப் பருகியவாறு விரைவில் நிறுத்துவதில்லை.",
        '0.58': "காதல் திருவிழாவின் ஆர்வத்தால் ஆடையைப் பற்றக் கையை விரைவுபடுத்தும் அன்புக் கணவன், அகன்ற கண்ணியின் கை தடுத்தபோது இருமடங்கு விரைகிறான்.",
        '0.59': "இயல்பில் நாணமுடையவராயினும் அக்கணமே துணிவு பெற்ற, பலவகைக் காதல் கலைகளில் தேர்ந்த இளம் மங்கையர் ஆர்வத்துடன் கணவர்களைத் தழுவி மகிழ்விக்கின்றனர்.",
        '0.60': "உலகியல் மீறிய குணமுடைய மங்கையர் தம்மை மகிழ்விக்கும் உலகியல் மீறிய கணவர்களை மகிழ்விக்கின்றனர்; பொருத்தமான அழகுடைய, உலகைக் கடந்த இன்பமுடைய அந்தத் தெய்வீகக் கூடல் அங்கே ஒளிர்கிறது.",
        '0.61': "அங்கே தம்பதியருக்குக் காதல் களைப்பு முதலியவற்றால் கெடுவதில்லை, பிரிவுத் துயரும் இல்லை, சக்களத்தியர் மீதான அன்பால் சண்டையும் இல்லை; ஏனெனில் அவ்வுலகம் எல்லாக் குறைகளும் அற்றது.",
        '0.62': "அவர்களுடைய உடல்கள் இன்பமும் ஞானமும் ஆன வடிவுடையவை என்பதால் உள்ளும் புறமும் நறுமணமே; ஆகவே ஹரியின் இருப்பிடத்தில் தம்பதியரின் காதல் முனிவர்களாலும் ஏற்கப்படுகிறது.",
        '0.63': "உலகுக்கு அப்பாற்பட்டதும், எல்லா முக்தர்களின் கண்களுக்கும் இலக்கானதுமானதையும் கேளுங்கள்: இந்திரையின் கணவன் பேரின்பம் நிறைந்த தன் அழகிய வடிவை இடையறாது வெளிப்படுத்துகிறான்.",
        '0.64': "(64–73 ஶ்லோகங்கள் அவ்வடிவை வர்ணிக்கின்றன.) ரத்தின வரிசைகளால் ஒளிரும் பெருமகுடம், ஆயிரக்கணக்கான கருமையான பளபளக்கும் சுருள்முடி, பிறை போன்ற நெற்றியில் ஒளிரும் திலகம், காதுகளில் ஒளிரும் மகர குண்டலங்கள் உடையது;",
        '0.65': "முழுநிலவை ஏளனம் செய்யும் முகம், தாமரை போன்ற நீண்ட கண்கள், சிவந்த இதழ்கள்; இணையற்ற அழகிய சிரிப்புப் பார்வைகளால் வணங்கும் தம்மவரை மகிழ்விப்பது;",
        '0.66': "புதிய சங்கு போன்ற கழுத்து, சூரியன் போல ஒளிரும் மணிராஜம் (கௌஸ்துபம்), சிறந்த மாலை, அழகிய ரத்தினம் பதித்த வளைகள், மோதிரங்கள், தோள்வளைகள் உடையது;",
        '0.67': "சூரியக் கூட்டத்தின் ஒளியுடைய சக்கரம், சந்திர பிம்பம் போன்ற சங்கு, இனிய தாமரை, தீயென எரியும் கதை, சிறந்த வில் ஆகியவற்றைத் தாங்கிய, நீண்ட உருண்ட சிவந்த உள்ளங்கைகளுடைய கைகள் உடையது;",
        '0.68': "சிறந்த திரண்ட தோள்கள், ரத்தின மண்டபம் போன்ற மார்பில் ஒளிரும் கமலை, பதினான்கு உலகங்களையும் தாங்கிய மெல்லிய வயிறு, வண்டு போன்ற ப்ரஹ்மா துதிக்கும் மங்கலமான நாபித் தாமரை உடையது;",
        '0.69': "மிக அழகிய ஒட்டியாணத்தின் ஒளியுடைய இடை, பொன் இழைகளால் மின்னும் மஞ்சள் ஆடை, சிறந்த யானையின் துதிக்கை போன்ற தொடைகள், படிப்படியாக உருண்ட அழகிய கணைக்கால்கள் உடையது;",
        '0.70': "சிறந்த சிலம்புகள், பேரொளியுடைய முன்பாதங்கள், புதுப் பவள ஒளியுடைய நகங்களுடைய விரல்கள், சக்கரம் தாமரை கொடி குறிகளால் ஒளிர்ந்து தம் தூசியால் மூவுலகையும் புனிதமாக்கும் பாதங்கள் உடையது;",
        '0.71': "எல்லா ஆகமங்களாலும் அறியப்படும் அளவற்ற ஆனந்தம், ஞானம் முதலிய எல்லையற்ற குணங்களே பாதம் முதல் முடி வரையிலான எல்லா அங்கங்களாகவும் அவற்றோடு என்றும் ஒன்றாகவும் உள்ள, குறையின் சிறுதுளியும் இல்லாத வடிவம்;",
        '0.72': "தகுதியுடையோரின் குணச் சிறப்புக்கேற்ப இரு பாதங்கள் முதல் எல்லையற்ற பாதங்கள் வரை, அந்தந்த வடிவுக்கேற்ற அடர்ந்த குணமயமான பிற அழகிய அங்கங்களுடனும் தோன்றுவது;",
        '0.73': "ஒருமுறை உதய சூரியனின் ஒளி, ஒருமுறை பொன்னையும் விஞ்சும் ஒளி, ஒருமுறை முத்துமாலை போல இனிமை, ஒருமுறை இந்திரநீலம் போல நீலம், ஒருமுறை கலந்த பல நிறம் — இன்பம், ஞானம், நறுமணமே குணங்களான அழகிய வடிவம்.",
        '0.74': "மூவுலகின் அதிசய ரத்தினங்களையும் விஞ்சியதும், மீண்டும் மீண்டும் காணக் காண மேலும் வியப்பூட்டுவதும், அழகின் சாரத்தின் ஒரே சுவையுமான ரமாபதியின் வடிவம் இங்கே முக்தர்களை எப்போதும் மகிழ்விக்கிறது.",
        '0.75': "யாகத்தில் ஈடுபட்டோர் யாக வடிவான அவனை வழிபடுகின்றனர்; அறிஞர்களிடையே மற்றவர் அவனைப் பரமன் என்கின்றனர்; விதியின் கட்டற்ற, எப்போதும் அடர்ந்த ஆனந்தமுடைய இசைவாணர் பாடத்தக்க புகழுடைய அவனைப் பாடுகின்றனர்.",
        '0.76': "(யமக ஶ்லோகம்.) வைகுண்டத்தில் மக்களின் அந்தச் சிறப்புச் செல்வங்கள் மிக வியப்பானவை, மனத்துக்கும் சொல்லுக்கும் எட்டாதவை; ஸ்ரீ, அஜன் (ப்ரஹ்மா), கருடன், ஶேஷன், முக்தர்களால் புகழப்படும் அவ்வுலகுக்கு இத்தகைய சிறப்பு தகுந்ததே.",
        '0.77': "இங்கே இன்புறுபவன் எந்தெந்தப் பொருளை விரும்புகிறானோ அவை அனைத்தும் விருப்பம் மாத்திரத்தாலேயே உண்டாகின்றன; வேதங்களும் முக்தியை இவ்வாறே அறிவிக்கின்றன; இதைவிடப் பெரிய சிறப்பு எது?",
        '0.78': "தேவர் முதல் மனிதர் வரை எவர் மஹா ஆனந்ததீர்த்தரின் பாஷ்யக் கருத்தைத் தம் திறனுக்கேற்ப மனத்தாலும் சொல்லாலும் மீண்டும் மீண்டும் சிந்திக்கின்றனரோ அவர்கள் முகுந்தனின் அருளால் இந்த மோக்ஷத்தை என்றும் அடைகின்றனர்.' (என்று ஶேஷன் கூறினான்.)",
        '0.79': "இவ்வாறு கவிகுலதிலகரான த்ரிவிக்ரம பண்டிதாசார்யரின் மகன் நாராயண பண்டிதாசார்யர் இயற்றிய, 'ஆனந்த' முத்திரையுடைய ஸ்ரீஸுமத்வவிஜய மஹாகாவ்யத்தின் பதினொன்றாம் ஸர்க்கம் நிறைவுற்றது.",
      },
    },
    'sumadhva-vijaya-12': {
      verses: {
        '0.0': "அனந்தனில் மனம் வைத்த அந்த வேதாந்திச் சிங்கம் முக்கிய வியாக்யானம் என்னும் கர்ஜனையுடன் எழுச்சியுற்று, மதம் கொண்ட வாதி யானைகளுக்கு உடனே அச்சமூட்டியபோது, மாயாவாதிகள் என்னும் நரிக் கூட்டங்கள் கலக்கமுற்றன.",
        '0.1': "கொடிய இந்தப் பாவிகள் சோழநாட்டவன், புண்டரீகபுரத்தவன் ஆகியோரிடம் கூடி, பூமிக்கு அணியான வாயுதேவர் மீது பொறாமையுடன், முன்பு த்ருதராஷ்ட்ரரின் மைந்தர்களிடம் மூடர்கள் கூடியது போல, ஆலோசனை செய்தனர்.",
        '0.2': "அவர்களிடையே இழிந்த நீதியில் காந்தாரனின் மகனுக்கு (ஶகுனிக்கு) நிகரான வாயாடி ஒருவன், நல்லோர் மீதான பொறாமையை உறுதிப்படுத்தத் தீயோரின் புரவலனிடம் நிலையற்ற சொற்களைப் பேசினான். (யமக ஶ்லோகம்.)",
        '0.3': "'இந்த மாயாமதம் தத்துவம் ஒன்றே என்கிறது, அதைப் பழைய வேதவாக்கியங்களாலும் சொல்ல இயலாததாக்குகிறது; பழமையானதாயினும் புதியது, பொருந்தாமையே அதன் அணி; நம் தர்ஶனாசார்யரின் நெறி எவ்வளவு அதிசயம்!",
        '0.4': "அதைப் பெறாமல், தேவர், மனிதர், அசுரர், அந்தணர், சண்டாளர் முதலியோர் கொண்டதும் வேற்றுமையைக் காட்டும் ப்ரமாணங்களால் அறியப்படுவதுமான இக்காணும் உலகம் வேற்றுமையற்றது என்று யார் நிறுவ முடியும்?",
        '0.5': "அறியாமையில் அது அனைத்தையும் வியவஹார உண்மையாக்கி எல்லாவற்றையும் நடத்துகிறது; ஞானம் உதித்தால் உலகம் எரிந்த துணி போலத் தோன்றுகிறது; ஞானம் முதிர்ந்தால் பழுக்கக் காய்ச்சிய இரும்பில் விழுந்த நீர் போல மறைகிறது.",
        '0.6': "ஞானிகளில் சிறந்தோரும் சிறந்த விஞ்ஞானிகளும் இப்போது நிர்குணத்தில் கலந்துவிட்ட நிலையில், எங்கள் தலைவர்களான நீங்கள் என் கதறலைக் கேளுங்கள்: ஐயோ! ஐயோ! இந்த மாயாவாதம் அழிகிறது!",
        '0.7': "பாட்டர்கள் வழி தவறிய, ப்ரபாகரனின் ஒளி மங்கிய, மஹாயானிகள் முதலியோர் அஞ்சிய மாயாவாதம் என்னும் அரண் போன்ற காட்டை எரிக்க முனையும் தத்துவவாதம் என்னும் தீயின் சுடரை நாம் புறக்கணிக்கக் கூடாது.",
        '0.8': "அந்த மஹாமதி சென்ற ஒவ்வொரு பகுதியிலிருந்தும் அவருடைய வருகையைத் தடுப்பேன் என்று எங்கள் ஆர்யர் வெளிப்படையாகச் சபதம் செய்திருந்தார்; அவரும் அவர் பக்கம் சேர்ந்துவிட்டார்! ஐயோ, நாம் பாக்கியமற்றவர்கள்!",
        '0.9': "கேட்ட கேள்வியை அவர் உறுதியாக மறுக்கிறார், மறுக்க முடியாத பொருத்தமான யுக்தியைக் கூறுகிறார், மறுப்பாளராக வாதிக் கூட்டத்தை — சிறப்பாக நம்மை — வெட்கப்படுத்துகிறார் என்று கேள்விப்படுகிறோம்; நாம் என்ன செய்வது?",
        '0.10': "ஒரு லட்சத்து இருபத்தைந்தாயிரம் (க்ரந்தம்) விரிவுடைய பழைய ஶாஸ்த்ரத்தை ஹர்ஷதீர்த்தர் (ஆனந்ததீர்த்தர்) ஒரே வாக்கியத்தால் மறுத்தார் என்று வழிப்போக்கர் வர்ணிப்பதைக் கேட்டு, வருந்திய மனத்துடன் உங்களிடம் வந்தேன்.",
        '0.11': "புன்முறுவலுடைய தெய்வ வடிவினரான அவரைக் காண்போர் 'இவர் வேதவ்யாஸரா, அல்லது உருவெடுத்த வேதமா?' என்கின்றனர்; அச்சொல்லே மாயைப் பக்ஷத்தின் வேரை வெட்டும் வாள்.",
        '0.12': "நம்மவரே சிலர் 'அவருடைய ஸூத்ர பாஷ்யம் சிக்கலற்றது, வலிமையானது, ப்ரமாணம் உடையது; அப்படியானால் நமக்கு என்ன இழப்பு?' என்று வெட்கமின்றிக் கூறி நம்மைத் தாங்க முடியாத வெட்கக் கடலில் மூழ்கடித்தனர்.",
        '0.13': "எங்கும் பரவிய, குணமுடைய, சங்கு சக்கர முத்திரைகள் தரித்த அவருடைய சீடர் வலைகள் சபை என்னும் கடலில் மக்களின் இதயங்கள் என்னும் மீன்களைப் பிடிக்காதபடி நம் நலனுக்கு ஓர் உபாயம் வகுங்கள்.",
        '0.14': "குணம் சார்ந்த வாக்கியங்களால் காக்கப்பட்ட குணம் சார்ந்த தர்க்கங்களால் அவர்கள் மக்களிடம் ஸகுண எண்ணத்தை வளர்க்கின்றனர்; மேகங்கள் அன்னங்களின் குரலை அடக்கி மழையால் கடலைப் பெருக்குவது போல, பரமஹம்ஸர்களான நம் பேச்சை அடக்குவதில் அவர்கள் தேர்ந்தவர்கள்.",
        '0.15': "அதிகம் சொல்வானேன்: உலக அழிவுக் காலத்தில் ப்ரளய நீர் பரவுவது போல, நம் தர்ஶனம் அழியும் இக்காலத்தில் அவர்கள் விரைவில் உலகெங்கும் தடையின்றிப் பரவுகின்றனர்.'",
        '0.16': "அவனுடைய இச்சொற்களைக் கேட்டு, அச்செருக்குடையோரின் மனம் அறிந்த மற்றொரு செருக்குடைய மந்தபுத்தித் தீயவன் தம்மவர் மனத்தை மகிழ்வித்தவாறு உரக்கத் துணிச்சலான சொற்களைப் பேசினான்:",
        '0.17': "'பகைவனின் ஒளியின் ஐயம் மாத்திரத்தாலேயே உருகும் கோழைகளின் தன்மானமற்ற மனத்துக்குச் சீ! உண்மையில் தீயின் அருகே சேர்ந்தால் மட்டுமே உருகும் வெண்ணெயே அதைவிட உறுதியானது.",
        '0.18': "தேவர் முதலியோருக்கும் பாதிப்பை நிறுவும், நமக்கு மங்கலமான ஶாங்கர வித்தையுடைய, ஶுக்ரனின் வித்தை போலத் தேவர் வணங்கும் ப்ருஹஸ்பதியையும் வெட்கப்படுத்தக் கூடிய இவர்கள் இருக்கையில் வருத்தம் ஏன்?",
        '0.19': "கடுமையான குணம் சார்ந்த தர்க்கங்களால் தடுக்கப்பட்ட அத்வைதம் நிறுவக்கூடியதாகத் தோன்றாவிட்டாலும் இருக்கட்டும்; ஷட்கர்மங்களை அறிந்த, தெய்வ மந்திரங்களும் மூலிகைகளும் உடைய இவர்களால் காக்கப்படும் நம்மை யாரும் வெல்ல முடியாது.",
        '0.20': "இருப்பினும் எதிர்த்தரப்பைப் புறக்கணிக்கக் கூடாது; ஆனால் இப்போது அழும் நேரமல்ல; இருமையற்ற ஆத்மபோதத்தில் புகழ்பெற்ற ஶங்கரர் முதலிய ஆசார்யர்களும் இதைப் பற்றி ஐயுற்றனர்.",
        '0.21': "'மரபாக வந்த தத்துவ ஶாஸ்த்ரம் புதியதால் அழிகிறது' என்று அறிவித்து, நம் சாமர்த்தியசாலிகள் நடுநிலை மக்களிடையே அவர்களுடைய குறைகளை — உள்ளவையோ இல்லாதவையோ — வர்ணிக்க வேண்டும்.",
        '0.22': "நம் கருத்து ப்ரஹ்மம் போலச் சொல்ல இயலாததாக இருக்கட்டும்; மாயா ஶக்தியால் எல்லாவற்றையும் நடத்தலாம்; இந்த நெறியால், நம் ஶாஸ்த்ர நெறி போலவே, நமக்கு எதிரான உலகம் முழுவதையும் பாதிக்க வேண்டும்.",
        '0.23': "ஊர்தோறும் அவர்களுக்குக் கிடைக்கும் மரியாதையை முன்கூட்டியே ஸாமம் முதலிய உபாயங்களால் தடுக்க வேண்டும்; அவர்கள் வந்தால், நூல்களைப் பறிப்பது முதலியவற்றுக்குத் தயாரான நம்மவர் அவர்களை அவமானப்படுத்த முயல வேண்டும்.'",
        '0.24': "இவ்வாறு செய்ய வேண்டியதை ஆலோசித்து அந்த வஞ்சகர்கள் காலப்போக்கில் சக்கரதாரியின் பக்தருக்கு எதிராகச் செயல்பட்டனர்; இல்லையெனில் துயரமே கொடிய நீராக உள்ள அந்ததாமிஸ்ரம் என்னும் கடலில் மூழ்க அவர்கள் எப்படித் தகுதி பெறுவர்?",
        '0.25': "வாதம் என்ற சாக்கில் அவரை அவமதிக்க விரும்பி, தீய ஆலோசனையால் அவர்கள் ரஜதபீடபுரத்தில் துறவி வேடமணிந்த, தன்னை அறிஞன் என்று எண்ணிய, வாஸுதேவனைப் பகைக்கும் புண்டரீக(புரி) என்பவனை முன்னிறுத்தி முயன்றனர்.",
        '0.26': "அசுத்தத்தை விரும்பும் ஊர் நாய் சிங்கத்தையும், ஒற்றைக்கண் காகம் அன்னத்தையும், சூழ்ச்சி நரி கழுதைப்புலியையும் அழைப்பது போல, அந்த மூடன் அறிஞர்களில் சிறந்தவரை வாதத்துக்கு அழைத்தான்.",
        '0.27': "அவன் அற்பனாயினும், இயல்பாகவே வெல்ல அரிய மத்வர் — ஒளிக்குவியலான எரியும் தீ வலுவற்ற சிறகுடைய நிலையற்ற விட்டிலைப் புறக்கணிக்காதது போல — அவனைப் புறக்கணிக்கவில்லை.",
        '0.28': "மதிக்கத்தக்க இணையற்ற ப்ரமாணங்களால் ஒளிரும் வேதமறிந்த ப்ரீதிதீர்த்தர் (ஆனந்ததீர்த்தர்) அவனை மறுத்து, தம் மதத்தை நிலைநாட்டி, விஷ்ணுவின் ப்ரீதிக்காக வேத வியாக்யானம் செய்தார்.",
        '0.29': "மரபுப்படி வேதம் கற்ற பல அந்தணர்கள் ஆர்வத்துடன் அங்கே வந்து சுற்றிலும் அமர்ந்து, காணத்தக்க ஆசார்ய சிரேஷ்டரைக் கண்டனர்.",
        '0.30': "க முதலிய மெய்யெழுத்துக்களை அவற்றின் இடங்களிலிருந்து தெளிவாக உச்சரித்து, மாத்திரை, உச்சரிப்பு முதலியவற்றில் தேர்ந்து, மூன்று ஸ்வர நிலைகளை அவற்றின் குணங்களுடன் வெளிப்படுத்திய அவரைக் கண்டு தேவர்கள் தேவதேவனையும் மறந்தனர்.",
        '0.31': "முதலில் குறிலாக 'வத்ஸானுவ்ருத்தி' என்ற ஓதுமுறையில் மாத்திரைகளையும் பாதங்களையும் நடத்தி, பின் மற்றச் சிறந்த விவ்ருத்திகளைச் செய்து கோவிந்தனின் பக்தர் கோவிந்தனின் அழகையே பெற்றார் (ஶ்லேஷம்: கன்றுகளின் பின் சிற்றடி வைக்கும் பாலக்ருஷ்ணனைப் போல).",
        '0.32': "மங்கலமான அங்கங்களால் (வேதாங்கங்களால்) கருத்தை வெளிப்படுத்தும், அரங்கேறி மூவுலகையும் வியக்க வைக்கும், மதிக்கத்தக்க பாத அமைப்புடைய மத்வரின் இனிய குரல் வேதவாணி, ஸ்வயம்வரத்தில் இன்னொரு க்ருஷ்ணையைப் (த்ரௌபதியைப்) போல ஒளிர்ந்தது.",
        '0.33': "ஆழம் முதலியவற்றாலும் வள்ளன்மையின் விளைவுகளாலும் நிறைந்த, பலவகை நாதங்களால் புகழத்தக்க அப்புண்ணிய அறிவாளரின் உச்சரிப்பே ஶிக்ஷா ஶாஸ்த்ரத்தின் இலக்கணங்களுக்கு மதிக்கத்தக்க இணையற்ற இலக்கு என்று நான் கருதுகிறேன்.",
        '0.34': "கல்பம், சந்தஸ் ஆகியவற்றின் விதிகளை வெளிப்படுத்தி, வ்யாகரண ஶாஸ்த்ரத்தை மீண்டும் மீண்டும் தெளிவாகக் காட்டி, நிருக்த நெறியைப் பின்பற்றி, ஜ்யோதிஷம் அறிந்தோரில் சிறந்த அவர் இவ்வாறு வேதத்தை விளக்கினார்.",
        '0.35': "வாக் (பாரதி), பறவையரசன் (கருடன்), ஜீவன் (ப்ருஹஸ்பதி) ஆகிய சொல்லின் தலைவர்கள் வணங்கி மிகுந்த வியப்புடன் வர்ணித்த அவருடைய அழகிய வேத விளக்கத்தையும் உச்சரிப்பையும் என் போன்ற உடலுடையோர் யார் வர்ணிக்க முடியும்?",
        '0.36': "ப்ரஹ்மாவே போல அவர் இவ்வாறு பொருளுடன் கூறிய வேதத்தைக் கேட்டு, சாந்தமான அந்த அந்தணர்கள் அனைவரும் யார் வெல்வார் என்று அறிய விரும்பி 'சித்ரகாயன்' (சிறுத்தை — புண்டரீகன்) என்ற பெயருடையவனிடம் சென்று கூறினர்:",
        '0.37': "'பேரறிவாளர் பேரறிவுடன் மந்திர எழுத்துக்களின் பொருளைக் கூறினார்; அறிஞனே, அவருடைய எதிர்வாதியான நீயும் இதைக் கூறவேண்டும் என்று கேட்க விரும்பும் நாங்கள் வேண்டுகிறோம்.'",
        '0.38': "அவர்கள் இவ்வாறு கூற, அந்தத் தீயவன் பேரறிவாளருக்குச் சமமாக முயன்று, முன்பு வாஸுதேவனின் ஒளியை விரும்பிய பௌண்ட்ரக வாஸுதேவனைப் போல நகைப்புக்கு உள்ளானான்.",
        '0.39': "ஐதரேயம் முதலிய ஸூக்தங்களை விளக்கும் ஆவலில் ('அக்னினா ரயிம்' என்ற இடத்தில்) 'ர' என்று தொடங்கும் சொல்லை 'நார' என்று ஓதியதைக் கேட்டு, அந்தணர்கள் பழிக்கத்தக்க அவனைப் பழித்தனர்.",
        '0.40': "முன்பு உலகில் 'ஶார்தூலம்' (புலி) என்ற பட்டத்துடன் போற்றப்பட்ட இந்தத் தந்திரமான மாயாவாதி நரி, வாதிகள் என்னும் சிறுத்தைகளை அழிக்கும் மத்வ சிங்கத்தை எதிர்கொண்டு பெயரளவில் மட்டுமே புலியானான்.",
        '0.41': "க்ருஷ்ணருக்கு (வ்யாஸருக்கு) பிரியமான, 'ஶாஸ்த்ரம்' என்ற தெளிவான பெயருடைய, நல்ல அந்தணரால் காக்கப்பட்ட தம் செல்வமான நூலகத்தை 'பத்ம' என்ற ஸைந்தவன் (பத்மதீர்த்தன்) கவர்ந்தான் என்று ஆனந்ததீர்த்தர் என்னும் பார்த்தர் கேட்டார் — அர்ஜுனன் க்ருஷ்ணையை ஜயத்ரதன் கவர்ந்ததைக் கேட்டது போல.",
        '0.42': "நீண்ட வழியை விரைவில் கடந்து, ஆர்யருடன் (மூத்த குருவுடன்) வந்து, சொற்கூட்டங்களால் (அர்ஜுனனின் அம்புக் கூட்டங்கள் போல) அவனை அச்சுறுத்தி, அந்தர்யாமி பற்றிய கேள்வியில் சிக்கி நகைப்புக்குள்ளான அந்தத் தோற்றவனை வெற்றித் திருவுடன் கண்டு சிரித்தார்.",
        '0.43': "'ஸௌக்யத' (ஶங்கர) என்ற பெயருடைய தனித்திருந்த நல்லவருக்கு அவமதிப்பு நேரக் காரணமான அந்தத் தீயவனை, குட்டிக்குத் தீங்கு நேர்ந்தபோது சிங்கம் பன்றியை மன்னிக்காதது போல, ஹரியின் அம்சமான (மத்வர்) மீண்டும் மன்னிக்கவில்லை.",
        '0.44': "முன்பு தோற்றிருந்தும் அச்சத்தால் பாதுகாப்பை நாடி அவன் பின்னே நின்றவனை (புண்டரீகனை), மற்றவர்களிடையே அவன் ஏவிய சொற்கூட்டங்களை ஐந்தாறு சிறப்புச் சொற்களால் வெட்டி வெற்றியாளர் வென்றார்.",
        '0.45': "விஷ்ணுவின் திருவடிகளையே அழகுபடுத்தும், வரிசையாக ஏவப்பட்ட தடுக்க முடியாத சொற்கூட்டங்களால் (அம்புகளால்) மத்வர் என்னும் பார்த்தர் 'கஞ்ஜ' (பத்ம) என்ற ஸிந்துராஜனைப் பிளந்து அடக்கினார் — அர்ஜுனன் ஜயத்ரதனை அடக்கியது போல.",
        '0.46': "(நல்லோர் அறிவித்தனர்:) 'போதும், போதும் இந்த உலகத் திருட்டு! அடே மாயாவாதித் திருடர்களே, ஓடுங்கள்! காண்பவர், காண்பவர் வந்துவிட்டார், உங்களை நிச்சயம் பிடிப்பார்; விரைவில் குகைகளுக்குள் புகும் நேரம் வந்துவிட்டது.",
        '0.47': "அறிஞர் மண்டலத்தின் சந்திரனின் ஒளி மறைந்துவிட்டது; வாதி நட்சத்திரங்களின் ஒளி முற்றிலும் அழிந்துவிட்டது; அவற்றின் ஒளிக்கு மூலமான, உலகைப் பரவிய, உங்களுக்குப் பிரியமான இருளும் நீங்கிவிட்டது.",
        '0.48': "கிழக்குத் திசையை நிரப்பிக் கதிர்கள்/சொற்கள் என்னும் கூட்டங்களால் உலகை ஒளிரச் செய்யும், ஏழு வித்தைகளே ஏழு குதிரைகளான, நேரடித் தேவனும் ஸர்வஜ்ஞனும் அனைத்துக்கும் விளக்குமான இந்தச் சூரியன் ஒளிர்வதை நீங்கள் காணவில்லையா?",
        '0.49': "அனைத்துக்கும் ஆதாரமான, அழகிய வடிவுடைய, கூதிர்கால நீலோத்பல ஒளியுடைய, வேறுவேறு சொற்களால் குணம் நிறைந்தது என நிர்ணயிக்கப்பட்ட 'ப்ரஹ்மம்' என்னும் வானைச் சார்ந்த மத்வ சூரியனை யார் மறைக்க முடியும்?",
        '0.50': "ஓடுங்கள், ஓடுங்கள், விரைவில், பொய்வாத அஸுரர்களே! 'அதப்ரதிஷணர்' (பூர்ணப்ரஜ்ஞர்) என்ற நரஹரி இங்கே சுடர்விடுகிறார்; வாயாடி மூடர்களுக்குத் துயர முளைகளான கூரிய யுக்தி நகங்களாலும் கொடிய ப்ரவசன கர்ஜனையாலும் அவர் எதிரிகளைக் கிழிக்கிறார்.",
        '0.51': "இவர் இன்னொரு பறவையரசன் (கருடன்): உலகத் தலைவனின் எல்லையற்ற வடிவங்களை இதயத்தில் தாங்கியவர், ஒருமுகப் பக்தர், திறமையாளர், இங்கே தாய்க்கு மட்டுமல்லாமல் எல்லா நல்லோருக்கும் அமுதம் அளித்தவர்; ஞானிகள் வணங்கும் திருவடியினர்; இவர் உங்கள் அழிவுக்குக் காரணமாவார். இரட்டை நாக்குடைய மாயாவாதிப் பாம்புகளே, செருக்கடையாதீர்கள்; விரைவில் உங்கள் வளைகளில் புகுங்கள்!",
        '0.52': "வேதக் கூட்டமே ஸுதர்ஶனமாகவும், ஒளிரும் தர்க்கமே சங்கொலியாகவும், ஒளிரும் புராணக் கூட்டமே கதையாகவும், ஶ்லோகக் கூட்டமே (பஞ்சராத்ரமே) ஶார்ங்க வில்லாகவும், நல்ல ஸூத்ரங்கள் குறித்த இதிகாசமே நந்தக வாளாகவும் உடைய மத்வர் என்னும் நாராயணன் உங்களை அடக்க வந்துவிட்டான்; மாயாவாதி தேவபகைவர்களே, ஓடுங்கள்!'",
        '0.53': "மாயாவாதிகளை எதிர்க்கும் நல்லோர் கூட்டம் இவ்வாறு கூறிக்கொண்டிருக்க, குருபக்தியுடைய அவர் தம் அந்த ஆராமத்திலிருந்து புறப்பட்டு 'ப்ராக்ர்யவாடம்' என்ற கோயிலில் ஆனந்த வடிவான இறைவனைப் போற்றியவாறு தங்கினார்.",
        '0.54': "இவ்வாறு கவிகுலதிலகரான த்ரிவிக்ரம பண்டிதாசார்யரின் மகன் நாராயண பண்டிதாசார்யர் இயற்றிய, 'ஆனந்த' முத்திரையுடைய ஸ்ரீஸுமத்வவிஜய மஹாகாவ்யத்தின் பன்னிரண்டாம் ஸர்க்கம் நிறைவுற்றது.",
      },
    },
    'sumadhva-vijaya-13': {
      verses: {
        '0.0': "ஒருமுறை காரியம் நிறைவேறி அரசனின் வணக்கத்தை ஏற்று, தம் சீடர்களின் மகிழ்ச்சிக்காக ஸஹ்ய மலைக்கு வந்திருந்த அந்தத் தொலைநோக்கரிடம் ஒருவன் வந்தான்.",
        '0.1': "அவரை வணங்கி அவன் கூறினான்: ''பகவான் தம் பணியாளர்களான எங்களுக்கு அருள விரைவில் இங்கே வரவேண்டும்' என்று ஒரு காரியம் செய்ய விரும்பி அரசர் உங்களை வேண்டுகிறார்.'",
        '0.2': "பிறகு இந்திரனின் கிழக்குத் திசையை விட்டு மேற்கு நோக்கிச் சென்ற, ஒளி பெருகிய, தம் பாதத் தீண்டலால் பூமியைத் தூய்மைப்படுத்திய அறிஞர் சூரியனால் அது ஒளிர்ந்தது.",
        '0.3': "(3–7 ஶ்லோகங்கள் அவருடைய பயணத்தைக் கங்கைக்கு ஒப்பிடுகின்றன.) கங்கை தாழ்ந்த குன்றுகளைத் தவிர்த்து ஓடுவது போல மாயாவாதிகள் சார்ந்த தீயோரைத் தவிர்த்து, மலை நதிகள் கங்கையில் கலப்பது போல நற்குலத்து நல்லோர் படிப்படியாக மகிழ்ந்து பேரன்புடன் அவரை விரைவில் அடைந்தனர்.",
        '0.4': "கங்கை தன் நீரால் மலர்களும் பழங்களும் நிறைந்த உயர்ந்த மரங்களை வளைத்து வளையாதவற்றை முறிப்பது போல, தடுக்க முடியாத வீரமுடைய அவர் தம் சொற்களால் நல்ல மனமும் புண்ணியப் பயனும் உடையோரைப் பணிய வைத்து, பிடிவாதமுள்ள மற்றவரை முறியடித்தார்.",
        '0.5': "அவருடைய பயணத் திருவிழாவால் வியந்த பலவகை நாட்டு மக்களால் இடையறாது பணியப்பட்டு, விரைந்து பரவும் புகழுடைய அவரைத் தொலைதேச மக்களும் துயர் நீங்கத் தேடி வந்தனர்.",
        '0.6': "தேவர்களாலும் அவர்களுடைய பணியாளர்களாலும் பிறருக்குத் தெரியாத முனிவர் தலைவர்களாலும் பணியப்பட்டு, ஹரியின் திருவடித் தாமரைத் தொடர்பே சாரமான அவர் — விஷ்ணுவின் பாதத்திலிருந்து பெருகும் கங்கையைப் போல — உலகில் புனிதர்களுக்கும் புனிதர்.",
        '0.7': "பயணத்தில் யாராலும் தடுக்கப்படாத, தூய வடிவுடைய, அறிஞர் அரசரான பரமானந்ததீர்த்தர், தேவநதியின் இடையறாத ஓட்டம் போல மிகவும் ஒளிர்ந்தார்.",
        '0.8': "காலப்போக்கில் அவர் 'ஸ்தம்ப' என்ற சொல்லுடைய பெயருள்ள நாட்டை (கபெநாடு) அடைந்து, எல்லா உலகும் வணங்கும் மதனேஶ்வரனின் ஒளிமிக்க ஆலயத்தில் நுழைந்தார்.",
        '0.9': "அங்கே இரவைக் கழித்து விடியலுக்கேற்ற அனுஷ்டானங்களைச் செய்த அவரை, புறப்பாட்டின் அறிகுறிகளால் சீடர்கள் விரைவில் பயணத்துக்குத் தயார் என அறிந்தனர்.",
        '0.10': "ஸமாதித் தூய்மைக்காக முன்னே விரித்திருந்த காவித் துணிகளை அங்கிருந்த யதிகள், தமக்குரிய முத்திரைகளுடைய தண்டம் முதலியவற்றை ஏந்தும் ஆர்வத்துடன் உடனே எடுத்துக்கொண்டனர்.",
        '0.11': "சிறப்பான சங்கு முதலிய முத்திரைகள் உலர்ந்திருப்பதைக் கவனித்து, அறிவுள்ள சீடர் ஒருவர் ஹரியின் நிர்மால்யமாகத் தகுந்த ஒளிரும் துளசி மாலையை அவருடைய கழுத்தில் அணிவித்தார்.",
        '0.12': "அடக்கமுள்ள சீடர் ஒருவர் கைகளைத் தூய்மைப்படுத்தி, மூச்சையும் பேச்சையும் அடக்கி, குருவின் சக்கரதாரி மூர்த்திகள் நிறைந்த, கயிற்று வளையங்களால் அழகுபடுத்திய, கயிற்றால் கட்டிய, துணியால் மூடிய பெட்டியைச் சுமந்தார்.",
        '0.13': "வரிசையாகத் தொங்கும் கமண்டலங்களையும் கனமான நூல்கள் முதலியவற்றின் சுமையையும் இளம் சீடர்கள் தாமே சிரமமின்றிச் சுமந்தனர்; திறமைக்கு நிகரான வேறு குணமில்லை.",
        '0.14': "மிகுந்த பதற்றத்துடன் அங்குமிங்கும் ஓடி, சுமை கட்டும் கயிறுகளை நெடுநேரம் தேடி, மீண்டும் மீண்டும் கவனமின்றிக் கேள்வி கேட்ட புதிய சீடனைக் கண்டு சிலர் சிரித்தனர்.",
        '0.15': "அப்போது அக்கணமே அடிக்கப்பட்ட பெரிய மணியின் ஆழ்ந்த ஒலியைப் பரமனின் தூண்டுதலின் அறிகுறியாகக் கொண்டு, அளவற்ற அறிவுடையவர் தம்மவர் புறப்பட, புறப்பட்டார்.",
        '0.16': "மேலே உயர்த்திப் பிடித்த சிறந்த குடையால் அந்த உயர்ந்த விரதியரசர், முன்பு கண்டிராத, உதய சூரியனின் மேல் முழுநிலவு இருப்பது போன்ற அழகைப் பெற்றார்.",
        '0.17': "மூவுலகையும் தாங்கும் முகுந்தனை உள்ளே தாங்கிய குருவை ஒருவன் சுமந்தான்; இது வியப்பல்ல, ஏனெனில் ப்ராணபதியான அவரே அவனையும் தாங்கிக்கொண்டிருந்தார்.",
        '0.18': "விலக்கப்பட்ட, ஆசைக்குரிய செயல்களைக் கைவிட்ட வேதநெறியாளரான யதிகள், இல்லறத்தார், சிறந்த ப்ரஹ்மசாரிகள் நூற்றுக்கணக்கில், உருவெடுத்த ஸ்வதர்மங்கள் போல அவரைப் பின்தொடர்ந்தனர்.",
        '0.19': "அந்த மனித ரத்தினத்தைக் கண்டவாறு பரிவாரத்தாருக்கு வழிக் களைப்பு உண்டாகவில்லை; இது வியப்பல்ல, இவரை நினைத்த மாத்திரத்தாலேயே உலகியலார் பிறவி விடுதலை பெறுகின்றனர்.",
        '0.20': "பிறகு மதனேஶ்வரனுக்குப் பிரியமான பகுதியில் வந்துகொண்டிருந்த பிரபுவை, நல்லெண்ணமுடைய அரசர்களில் சிறந்த, 'ஸ்தம்ப' என்ற அடைமொழியுடன் 'ஸிம்ஹ' என்ற பெயருடைய ஜயஸிம்ஹன் விரைவில் எதிர்கொண்டான்.",
        '0.21': "முன்கூட்டியே தன் வாகனத்திலிருந்து இறங்கி, படைவீரர்களை வழியிலிருந்து விலக்கி, சில அந்தணர்களுடன் வந்து அவன் மூவுலகும் வணங்குபவரின் திருவடியருகே வணங்கினான்.",
        '0.22': "பக்திச் சுவையால் நனைந்த மனமுடைய அரசன் பணிவுடன் பின்தொடர, அவர் விரைவில் விஷ்ணுமங்கலத்தின் சிறந்த கோயிலின் அருகே சென்றார்.",
        '0.23': "அரசனைக் காண விரும்பிக் கூடிய இரு கிராமத்து மக்களும் மற்றவர்களும் வியப்புக் கடலில் மூழ்கி, வந்துகொண்டிருந்த எல்லையற்ற மனமுடைய அவரை மீண்டும் மீண்டும் நோக்கினர்.",
        '0.24': "(24–36 ஶ்லோகங்கள் அவர்கள் கண்டதை வர்ணிக்கின்றன.) முன்னே இனிய குரலில் தாமே இயற்றிய செவிக்கினிய முகுந்தப் பாடல்களைப் பாடி, தாமரை மணி மாலையும் சக்கர முத்திரையும் அணிந்து ஆடும் திறமையாளர்களால் பணியப்பட்ட;",
        '0.25': "கைகூப்பி, மக்கள் நெரிசலைப் பொறுத்து, தன்னை அவருடைய கருணைக்கு உரியவனாக்க விரும்பி கபடமின்றிப் பணிவிடையை ஏற்ற அரசனால் வெளிப்படையாகப் பின்தொடரப்பட்ட;",
        '0.26': "'இது, இப்படி' என்று மனிதக் கண்களால் வரையறுக்க முடியாத மிகப்பெரும் ஒளி வடிவுடைய, பூமியை மேலும் அழகுபடுத்தத் தெளிவாக உதிக்கும் இன்னொரு சூரியனைப் போன்ற;",
        '0.27': "விரைந்து நடந்தாலும் மெல்ல நடப்பது போலத் தோன்றும், சிறந்த இளம் சிங்கத்தின் கம்பீர நடையுடைய, மிகச் சிவந்த தளிர்ப் பாதங்களால் பூமியை முழுமையாகப் புனிதமாக்கிய;",
        '0.28': "நகங்களால் பத்மராகத்தின் செம்மையை வென்ற, சிறந்த ஆமை போன்ற முன்பாதங்களுடைய, மறைந்த கணுக்கால்களுடைய, தேவர் தலைவர்களின் கைகளால் பணியத்தக்க கணைக்கால்களுடைய, யானைத் துதிக்கை போன்ற தொடைகளுடைய;",
        '0.29': "மங்கலமும் தூய்மையுமான இடுப்பில் ஒளிரும் புதுப் பட்டாடையுடைய, மெல்லிய வயிறு, கழுத்து, நெற்றி ஆகியவற்றில் தெளிவான மூன்று கோடுகளால் விளங்கிய;",
        '0.30': "மென்மையான, நுண்ணிய, அடர்த்தியான, தெளிவான செந்நிறக் கம்பளிப் போர்வையால் ஒளிர்ந்து, புதிதாக உதித்த சூரியனின் கதிர்க் குவியலில் மேருவின் பொற்சிகரம் போன்ற;",
        '0.31': "அகன்ற மார்பு, உயர்ந்த சுவர் போன்ற தோள்கள், திரண்ட உருண்ட நீண்ட அழகிய கைகள், மிகச் சிவந்த தளிர் உள்ளங்கைகளில் மேல்நோக்கிய ரேகை, கொடி முதலிய குறிகள் உடைய;",
        '0.32': "முதல் பார்வையில் முழுநிலவு வட்டம் என்ற ஐயத்தை எழுப்பும், ஆனால் களங்கமற்றதால் அதிலிருந்து தெளிவாக வேறுபட்ட, தூய ஒயிலின் கடலான முகமுடைய;",
        '0.33': "மிக அழகிய புன்முறுவலில் ஒளிரும் புது முல்லை போன்ற பற்களுடைய, மங்கலச் சிவந்த இதழ்களுடைய, தாமரை போன்ற நீண்ட கண்களின் பார்வைகளால் எல்லா மக்களையும் மகிழ்வித்த;",
        '0.34': "மிக ஒளிரும் காதில் விளங்கும் ஸ்ரீதுளசிக் கொத்துடைய, மிகுந்த ஒளியுடைய கன்னங்களுடைய, மூவுலகுக்கும் செல்வம் அளிப்பதில் திறமையான புருவ அசைவுடைய, அழகிய தலையுடைய;",
        '0.35': "ப்ரதிமை இலக்கணங்களைக் காட்டத் திறமையாளர்கள் எல்லா அங்கங்களையும் துல்லியமாக அளந்து எவருடைய உடலை மாதிரியாக்கினரோ அவர்; ஆகவே அவரை இப்போது வெறுமனே 'நல்லிலக்கணமுடையவர்' என்று மட்டும் கூறுவதில்லை;",
        '0.36': "பெரும் கூட்டத்தின் நடுவே இருந்தும், நெரிசலுக்கு அஞ்சித் தொலைவில் நின்று தம்மைக் காண ஏங்கியவர்களுக்கு அவர் கருணையுடன் மார்புக்கு மேல் வரை தம்மைக் காட்டினார்.",
        '0.37': "மலர்ந்த கண்களும் கூப்பிய கைகளும் உடைய, பேராதரவுடன் பணிந்த மக்கள் வளையத்தால் சூழப்பட்ட சிறந்த ஞானி, முராரிக்குப் பிரியமான கோயிலில் நுழைந்தார்.",
        '0.38': "பலவகைத் தலைவர்களிடையே அரசனுடன் அமர்ந்த மறைந்த தேவரான அவர், நட்சத்திரங்களிடையே பூமியின் மகனான (செவ்வாய்) கிரகத்துடன் இருக்கும் முழுநிலவு போல ஒளிர்ந்தார்.",
        '0.39': "தகுந்த குணம், குரல் முதலியவை உடைய அவருடைய சிறந்த சீடர் (ஹ்ருஷீகேஶதீர்த்தர்) பாகவதத்தை வாசிக்க, பகவான் பிறவிப் பிணியை அழிக்கும் சக்கரபாணியின் கதையை விளக்கினார்.",
        '0.40': "உயர்ந்த உறுதியே சாரமான, இனிய, நிறைந்த கருத்துடைய, தெளிவான அந்த ப்ரவசனம் கேட்ட அறிஞர்களையும் அறிவற்றவர்களையும் ஆனந்தச் சுவைக் கடலில் மூழ்கடித்தது.",
        '0.41': "நினைத்த மாத்திரத்தில் பிறவி விடுதலை தரும் மத்வரின் நடத்தல், அமர்தல், பேசுதல் முதலிய லீலைகளைத் தேவர்களே எப்படியோ விவரிக்க முடியும்; என் போன்ற சிற்றறிவாளர் அல்லர்.",
        '0.42': "தவம், கவிதை முதலிய நற்குணங்களால் புகழ்பெற்ற ஆங்கிரஸ கோத்திரத்து லிகுச குலத்தில் குஹன் (ஸுப்ரஹ்மண்யன்) என்ற பெயருடைய, எல்லா வாதிகளும் வணங்கும் கவிஞர் சிறந்த அறிஞர் ஒருவர் இருந்தார்.",
        '0.43': "அவருடைய குணங்களுக்கு ஏற்ற, வஸுதேவனின் மகனிடம் பக்தியுடைய கற்புடைய மனைவி, விதியின் வலிமையால் மீண்டும் மீண்டும் குழந்தைகளை இழந்திருந்தும், மகனை விரும்பி உலகத் தலைவர்களான ஹரியையும் ஹரனையும் வழிபட்டாள்.",
        '0.44': "அந்த இரு பரமேஶ்வரர்களின் அருளால் அறிஞரின் மனைவி ஒரு மகன் ரத்தினத்தைப் பெற்றாள்; சபைகள் என்னும் நகரங்களின் சிறந்த சோதனையாளர்களும் அவன் மதிப்புக்கு இணையானதைக் காணவில்லை.",
        '0.45': "தன் குலத்தை உயர்த்தும் ஆற்றலின் அடையாளங்களுடைய மகனின் முகச் சந்திரனைக் கண்டு, நிறைவுற்ற கவிஞர் சடங்குகளைச் செய்து அவனுக்குத் தகுந்த 'த்ரிவிக்ரம' என்ற பெயரைச் சூட்டினார்.",
        '0.46': "மழலை பேசும் குழந்தையாக இருந்தபோதே அந்த அறிஞர் மகன் குறையற்ற செய்யுள்கள் சொல்லும் கவிஞனாக இருந்தான்; ஒளிமிக்க சூரியன் இளங்கதிராக இருக்கும்போதும் ஒளிர்கிறான் அல்லவா?",
        '0.47': "காலப்போக்கில் எல்லா அங்கங்களுடனும் (வேதாங்கங்களுடனும்) ஒளிரும் கிளைகளுடைய, சிறந்த பறவைகளால் (அறிஞர்களால்) பணியப்பட்ட அந்த லிகுச மரம், நல்ல பயணிகளுக்கு உதவ ரசத்தால் இனிய காவியப் பழத்தைத் தோற்றுவித்தது.",
        '0.48': "பரந்த மாயாமதத்தின் பொருந்தாமையைத் தானே உண்மையாகக் காட்டியிருந்தும், தன் குருவால் அதைத் தீர்க்க முடியாவிட்டாலும், தோழர்களின் தூண்டுதலால் அவன் அதை முழுமையாகக் கற்றான்.",
        '0.49': "பகவான் வாமனனிலிருந்து த்ரிவிக்ரமனாக வளர்ந்தது போல, ஆர்ய த்ரிவிக்ரமர் சிறுவயதை விட்டுச் சொல்வன்மையுடன் உதித்தபோது, பானு முதலிய எல்லா அறிஞர்களும் விரைவில் மின்மினிப் பூச்சிகளின் ஒளியுடையவர்களாயினர்.",
        '0.50': "ஒன்றேகால் லட்சம் (க்ரந்தம்) கொண்ட மாயாவாதிகளின் ஸித்தாந்தத்தில் யுக்தி வீரனும், மிகக் கூர்மையான அறிவுடையவனும், மகிமையால் பூமியில் போற்றப்பட்டவனுமான மகனிடம் தந்தை தனிமையில் கூறினார்:",
        '0.51': "'சிந்தித்த இந்தச் சொல்லைக் கேள்: கலியுகத்தில் நிர்குண பாவனை இன்பம் தராது; ஆகவே மகனே, குணக் கட்டிலிருந்து விடுபட, குணங்கள் நிறைந்த இறைவனான வாஸுதேவனையே நினை.'",
        '0.52': "தந்தையின் இச்சொற்களைக் கேட்டுச் சற்றே மனம் தடுமாறினாலும் ஶாஸ்த்ரச் சாரத்தை ஆராய்ந்து, அக்கரை சேர விரும்பி அவன் பிறரிடமிருந்து நிர்குண உபாஸனையையே கேட்டு வந்தான்.",
        '0.53': "ஸ்வதர்மத்தில் ஈடுபட்ட அந்தச் சிறந்த இல்லறத்தான், கலிகாலத்தால் மனம் கலங்கியிருந்தும் இயல்பாகவே மிகக் கூர்மையான அறிவுடையவனாய், ஒருமுறை இவ்வாறு தெளிவாகச் சிந்தித்தான்:",
        '0.54': "'ஸத்யவதியின் மகனே நேரடியாக இயற்றிய ஸூத்ரங்களே இங்கு அறிஞர்களுக்கு ப்ரமாணம்; ஒன்றுக்கொன்று பொருந்தாத எல்லா பாஷ்யங்களும் ப்ரமாணமாக முடியாது.",
        '0.55': "அவற்றை முன்முடிவின்றி நோக்கினால் எதுவும் பொருத்தமாகத் தெரியவில்லை; ஆயினும் மரபாக வந்தது என்பதற்காகவே ஶாங்கர பாஷ்யத்தை அன்புடன் கற்கிறோம்.",
        '0.56': "உபநிஷத்துகளை ஒருங்கிணைப்பது சிற்றறிவாளருக்கு எளிதல்ல என்று ஒப்புக்கொண்டு சிந்திப்போம்: ஶாஸ்த்ரம் கூறும் இந்த உபாஸனையை விட்டு யாரும் முக்தி அடைவதில்லை.",
        '0.57': "தத்துவம் அறிந்தோர் எங்கும் நிறைந்த, இன்பம்-சத்-சித்-இரண்டற்ற ஆத்மாவை உபாஸிக்கத் தக்கதாக விதித்துள்ளனர்; அதற்கு எந்த வடிவும் நிர்ணயிக்கப்படாவிட்டால் அது வெறும் ஒளி கூட அல்ல — இதுவே புதிர்.",
        '0.58': "அதன் வடிவை அப்படி உபாஸித்தால் எஞ்சியதால் அது இருளாகவே தோன்றும்; அப்போது பயனான முக்தியும் அத்தகையதாகவே இருக்கும்; ஆகவே இந்த உபாஸனை எனக்குச் சற்றும் திருப்தி தரவில்லை.",
        '0.59': "ஆகவே வேதம், புராணம், பாரதம் முதலியவற்றை என் புரிதலுக்கேற்ப நானே ஆராய்ந்து, ஸ்ம்ருதி தர்மங்களை நன்கு கடைப்பிடித்து, குணமுடைய முகுந்தனை உபாஸிப்போம்.'",
        '0.60': "இவ்வாறு செய்ய வேண்டியதை உறுதிசெய்து அந்த ஆர்யன் விவேகத்துடன் அதைத் தொடங்கியபோது, உலகங்களில் பரவிய பூர்ணமதியின் (மத்வரின்) முழுமையான தூய புகழைக் கேட்டான்.",
        '0.61': "(மாயாவாதிகள் அவனைத் தூண்டினர்:) 'மிகச் சொல்வன்மையுடைய யாரோ ஒருவன் மரபாக வந்த நம் ஸித்தாந்தத்தை அழிக்கிறான்; எல்லையற்ற யுக்தி வீரனான நீ அவனை மறு; மற்றவர் அதற்குத் திறனற்றவர்.",
        '0.62': "வேத நதிகளில் மூழ்கி, ஸித்தாந்தக் கடல்களில் விளையாடும், புதுக் காவியச் சுவையை விரும்பும், வாதி யானைகளின் அரசனான உன்னை எதிர்க்கும் யானை இன்னும் பிறக்கவில்லை.",
        '0.63': "விதி இப்போது முன்கொணர்ந்த எதிர்வாதி என்னும் எதிர் யானையைத் தடுத்து, நிலவு போன்ற வெண்புகழைப் பெற்று, உன் கூட்டத்தின் அச்சத்தைப் போக்கு.'",
        '0.64': "இவ்வாறு ஆங்காங்கே மாயாவாதிகளால் தம்மவன் என்று வேண்டப்பட்டு, ஐயம் போக்குபவனும் பெரும் தன்மானமுடையவனுமான அவன் இணக்கமாகப் பேசினாலும் மனத்தில் ஐயம் கொண்டான்.",
        '0.65': "மத்வரின் தூய சொல் என்னும் அங்குசத்தை ஏவிய மனிதர்களை வருத்தி, இந்தக் கவி யானை பலவகை எதிர்விடைகள் என்னும் புழுதியை வீசி எதிர்ப்பால் அவர்களை மேலும் குருடாக்கியது.",
        '0.66': "இரவுகளில் பிறருக்குத் தெரியாமல் அந்த விவேகி பேரறிவாளரின் இனிய ஶாஸ்த்ரச் சாரத்தை ஆராய்ந்து, மகிழ்ச்சி நிறைந்த பெரும் உள் வியப்பை அடைந்தான்.",
        '0.67': "அவருடன் விவாதித்து, பேரறிவாளரின் நல்ல தர்ஶனத்தைக் கண்டு அவன் உறுதியாக அறிந்தான்; ஆயினும் அவருடைய மதத்தை உடனே ஏற்கவில்லை; அறிஞர்கள் ஆராய்ந்த பிறகே எல்லாவற்றையும் செய்கின்றனர்.",
        '0.68': "பிறகு ஆர்ய த்ரிவிக்ரமர் (அயுகவிக்ரமர்) விஷ்ணுமங்கலத்தில் இருந்த பேரறிவாளரை அடைந்து, தத்துவத்தை அறியத் தேவேந்திரன் நான்கு முகப் புன்னகையின் ஒளியுடைய தாமரையில் பிறந்த ப்ரஹ்மாவை அடைவது போல, ஆனந்தம் அளிப்பவரை வணங்கினார்.",
        '0.69': "இவ்வாறு கவிகுலதிலகரான த்ரிவிக்ரம பண்டிதாசார்யரின் மகன் நாராயண பண்டிதாசார்யர் இயற்றிய, 'ஆனந்த' முத்திரையுடைய ஸ்ரீஸுமத்வவிஜய மஹாகாவ்யத்தின் பதின்மூன்றாம் ஸர்க்கம் நிறைவுற்றது.",
      },
    },
    'sumadhva-vijaya-14': {
      verses: {
        '0.0': "நீர் வற்றியதும் மேகக் கூட்டம் கருமையை இழப்பது போல, அரசர் சிங்கத்தின் ஆற்றலால் கூடியிருந்த தலைவர்கள் பகைமையைக் கைவிட்டனர்; ஒளிமிக்க மத்வ சூரியன் தெளிவாக உதித்தபோது நல்லோர் என்னும் தாமரைகள் மலர்ந்து உலகம் இனிமையாயிற்று.",
        '0.1': "'பொறுமையை அணிகலனாகக் கொண்ட ஆர்யர்களே, செய்த தீங்கை மன்னியுங்கள்' என்று மென்மையாகக் கூறிய தலைவர்களின் வேண்டுகோளின்படி, தஶஹ்ருதயரின் (மத்வரின்) ஆணையால், பிறர் சூழ்ச்சியால் கவர்ந்த நூல் தொகுப்பை ஶங்கரார்யர் (ஶங்கர பண்டிதர்) திரும்பப் பெற்றார்.",
        '0.2': "தம் சகோதரனின் வெற்றியால் மகிழ்ந்த கவிகுலதிலகரான ஆர்ய த்ரிவிக்ரமர், பணிந்த ஊர்த் தலைவர்களும் ஊர் மக்களும் சூழப் பிரபுவின் திருவடியருகே வணங்கி அமர்ந்திருந்த பெருமனமுடைய மனிதர் சிங்கத்தை (ஜயஸிம்ஹனை) ஆசீர்வாதத்தால் மகிழ்வித்தார்.",
        '0.3': "'அரசே, சிறு பாக்கியமுடையோருக்கு அரிதான, வழிபடுவோருக்குத் தேவசபையில் இந்திர பதவியையே தரும் பரமானந்ததீர்த்தரின் பாதத் தூசி உனக்கு என்றும் உள்ளார்ந்த இன்பம் அருளட்டும்.'",
        '0.4': "அதிகப் பழக்கமில்லாவிட்டாலும் இந்தக் கவியரசர் அவருடைய மிக மறைவான குணச் சாரத்தை அறிந்தது வியப்பல்ல; மலர்த் தேனைப் பெறப் பறக்கும் வண்டரசன் பழக்கமில்லாத காட்டிலும் வல்லவனே அல்லவா?",
        '0.5': "எல்லாத் தீயோரிடமும் பகைமைக் குறையைப் பெருக்கி, நடுத்தரத்தோரிடம் வியப்பை எழுப்பி, நல்லோருக்கு அவரவர் கதிக்கேற்ற செல்வம் அளித்து, அந்தப் பெருமனத்தார் அங்கே சில இரவுகளைக் கழித்தார்.",
        '0.6': "(ஸர்க்கத்தின் மீதி அவருடைய தினசரியை வர்ணிக்கிறது.) சிறந்த நேரத்தில் விநதையின் மகனான அருணன் உதித்தபோது, கடமை அறிந்தோரில் சிறந்த அவர் எல்லாச் செயல்களையும் முடித்து, சிவப்புத் திரைக்குள் தகுந்த யோகாஸனத்தில் அமர்ந்து, பெருங்குணமுடைய நாராயணன் என்னும் ப்ரஹ்மத்தை தியானித்தார்.",
        '0.7': "சிறந்த பல்குச்சிகளால் பற்களை மிக வெண்மையாக்கிய பல முதன்மை யதிகள் அங்கே ஒன்றாக நீராடி, செயல்களின் சிறப்பால் குரு உரைத்த ஆசார முறைகளில் தங்கள் உறுதியைத் தெளிவாகக் காட்டினர்.",
        '0.8': "கடைசியில் உறங்கி முதலில் எழுந்த சீடர்கள் அப்போது முதல் நள்ளிரவு வரை பெரும் மரியாதையுடனும் மகிழ்ச்சியுடனும் குருமார்களுக்குக் கடினமான பணிவிடை செய்தனர்; இல்லையெனில் அவர்கள் விரும்பிய நற்கதி எப்படிக் கிடைக்கும்?",
        '0.9': "கேட்டல், சிந்தித்தலுக்காக நெடுநேரம் உறக்கமின்றியிருந்த ஒரு சீடன் திடீரென உறக்கத்துக்கு ஆட்பட்டான்; பூஜ்யர் தாமே அங்கவஸ்திரம் முதலியவற்றை விரைவில் எடுப்பதைக் கண்டு சட்டென விழித்து வருந்தினான்.",
        '0.10': "'விழித்திருந்தும் இதை முன்பே ஏன் செய்யவில்லை?' என்ற குருமார்களின் கண்டிப்புக்கு அஞ்சி, வளைந்த உடலுடைய சீடர்கள் வழியை விட்டு, குருமார்கள் நீரருகே இருக்கையில் நெடுநேரம் இறங்காமல் மௌனமாக நின்றனர்.",
        '0.11': "விளக்கொளியில் ஒளிரும் பெருமனத்தாரின் அருகே, மிக அடங்கிய மனமுடைய யதி ஒருவர் சிறந்த சங்கில் நிரப்பிய நீரால் அர்க்யம் முதலியவற்றை அளித்து, சக்கரதாரியின் மூர்த்திகளிலிருந்து சிறந்த மலர்க்குவியலை மரியாதையுடன் அகற்றினார்.",
        '0.12': "நிர்மால்ய மலர்களிலிருந்து அமுதம் வழிவதைக் கண்டு சீடர்கள் முதலில் 'இது நெய்' என்று மயங்கினர்; பின்னர் மேலும் சொற்களால் அதை அமுதமே என நம்பினர் — அந்த வழிபடத்தக்கவரின் ஆற்றலால் இறைவன் நாள்தோறும் அமுத உணவால் வழிபடப்பட்டான்.",
        '0.13': "அப்போது பஞ்சாங்கம் அறிந்தோர் தகுந்த மந்திரங்களால் ஸந்த்யா கர்மங்களைச் செய்ய, மூன்று ஆற்றல்களுடைய கதிர்ச் சக்கரவர்த்தியான சூரியன் தன் பெரிய வட்டத்துக்குள் ஆறு குணங்கள் நிறைந்த அந்தராத்மாவின் ஒளியைத் தாங்கி உதித்தான்.",
        '0.14': "சிங்கம் நகங்களால் யானைக் கூட்டத்தை விரட்டுவது போல, சூரியன் தன் முதல் கதிர் வலைகளால், எல்லா உயிர்களின் வழியையும் அடைத்திருந்த, உலகம் என்னும் வீட்டை நிரப்பியிருந்த, மை போன்ற கருமையான மிகக் கடுமையான இருள் குவியலை அகற்றினான்.",
        '0.15': "பறவைகளின் இன்னொலியே இனிய குரலாக, இரவுப் பனி என்னும் கண்ணீர் உலர்ந்து, அவன் வருகையால் காதலால் சிவந்து மகிழ்ந்த, தெளிந்த வானமே ஆடையான, சிரிக்கும் தாமரை முகமுடைய திசைகள் என்னும் மங்கையரைச் செஞ்சூரியன் தன் கதிர்கள் என்னும் கைகளால் தழுவினான்.",
        '0.16': "ஆர்வமுள்ள வணக்கங்களால் எழுந்த தூசியால் தனி அழகு பெற்ற, சாளர வலைகள் வழியே உள்ளே வந்த ஆயிரம் கதிரோனின் கதிர்கள், நேரம் வந்துவிட்டது என்று அறிவிக்கும் நண்பர்கள் போலச் சீடர்களுக்கு உதவின.",
        '0.17': "ஸாத்விகரான அவர்கள் விரைவில் சபையில் உரைப்பவருக்குத் தகுந்த உயர்ந்த யோகபீடத்தை வைத்து, விரைவில் கடமைகளை முடித்த புண்ணிய ஸந்ந்யாசிக் குழுவுடன் கேட்டல் என்னும் உயர்ந்த கடமைக்காகச் சுற்றிலும் கூடினர்.",
        '0.18': "தூய கயிறுகளும் அழகிய உறைகளும் உடைய, முராரியின் இருப்பிடமான, பலவகை அட்டைகளுடைய வேதாந்த ஓலைச்சுவடிக் கட்டுகள் விரைவில் திறக்கப்பட்டபோது, அறிவுகளின் உள்ளார்ந்த பொருள்கள் போல ஒளிர்ந்தன.",
        '0.19': "அவற்றில் திறமையாளர்கள் எழுதிய எழுத்துக்கள் ஒளிர்ந்தன — மிக இடைவெளி இல்லாத, ஒன்றையொன்று தொடாத, நேரான நீண்ட வரிசைகளின் சமநிலையால் அழகான, யானை குதிரை வடிவங்களை ஒத்த, ஓரங்களைத் தொலைவில் விட்ட எழுத்துக்கள்.",
        '0.20': "சிலர் பழக்கத்தாலும் திறமையாலும் படிக்க வேண்டிய பகுதியை உடனே கண்டனர்; மற்றும் சிலர் சிறிது நேரம் கழித்து; இவர்கள் விரைவில் ஹரியையும் குருவையும் வணங்கி முயற்சியால் மற்றவர்களுக்குச் சமமாயினர்; முயற்சியே வெற்றிக்கு வழி.",
        '0.21': "மக்கள் வணங்கி மௌனமானதும், சூரியனாலும் பூஜிக்கப்படும் திருவடியுடைய அவர் மாலை மேகம் போலச் சிவந்த அந்தத் துணித் திரையை விலக்கி, சபை என்னும் வானில் சூரியனைப் போல — அவனையும் விஞ்சி — ஆயிரம் ஒளியுடன் ஒளிர்ந்தார்.",
        '0.22': "பிறகு மூவுலகின் சிறந்த ஒளியான, வேதப் பொருளை வெளிப்படுத்தும் மூன்று சாரங்கள் என வர்ணிக்கப்பட்ட சிறந்த எழுத்துக்களை (அ, உ, ம) நன்கு ஒன்றிணைத்து, திறமையான பேரறிவாளர் ப்ரவசனத் தூய்மைக்காகப் ப்ரணவத்தை உச்சரித்தார்.",
        '0.23': "வாசிப்பவர்கள் தொடக்கத்தில் மந்த்ர ஸ்வரத்தை விடாமல் உபநிஷத்தைத் தெளிவாக வாசிக்க, அவர் உயிர்களுக்கு அமுதம் போன்ற, அமரத்துவத்துக்கு (மோக்ஷத்துக்கு) காரணமான மிக அற்புதமான ப்ரவசனம் செய்தார்.",
        '0.24': "ஏழைகளுக்குச் செல்வம் அளிக்கும் மகிழ்ந்த சூரியன் மகன் (கர்ணன்) போலவும், போர் வேண்டுவோருக்கு நூறு அம்புகள் அளிக்கும் கடுமையான பார்த்தன் போலவும், சோர்வற்ற அவர் கேள்வி கேட்ட அனைவருக்கும் இடையறாது உறுதியான பதில்களை அளித்தார்.",
        '0.25': "பிறகு ஆயிரம் கதிரோன் மேற்கே சாயும் முன்பே ப்ரவசனத்தை முடித்து நீராடக் குளத்துக்கு வந்தார்; அங்கே சிறந்தோரின் தொடர்பை விரும்பும் தேவநதி முதலிய புண்ணிய தீர்த்தங்கள் உடனே பேரறிவாளரை அடைந்தன.",
        '0.26': "உள்ளே மிகத் தூய்மையான அந்த நீர்த்திரள், அன்பு நிறைந்த முனிவர் கூட்டம் போல முதலில் அந்த ஸர்வஜ்ஞரின் பிரதிபிம்பத்தைத் தாங்கி, நீராடலில் நல்லோருக்குப் பிரியமான அவருடைய உண்மை வடிவத்தையே நேரடியாகத் தெளிவாகப் பெற்றது.",
        '0.27': "ஒளிரும் சங்கைப் பிடித்த கையுடைய அளவற்ற அறிவாளர் சக்கரக் குறியுடைய கற்களுக்கு (ஸாளக்ராமங்களுக்கு) அபிஷேகம் செய்யும்போது, அவற்றில் தெரிந்த அவருடைய உயர்ந்த பிரதிபிம்பங்கள் அவற்றில் உறையும் பாஞ்சஜன்யப் பிரியனின் (விஷ்ணுவின்) உடல்கள் போல ஒளிர்ந்தன.",
        '0.28': "பக்தியுடன் உட்கொண்டால் பன்னிரண்டு ஆண்டு உண்ணாநோன்பின் பயனுக்குச் சமம் என்றும், தேவநதி முதலியவற்றில் நீராடுவதைவிடப் புண்ணியம் மிக்கது என்றும் முனிவர் தலைவர்கள் கூறும் விஷ்ணு பாதோதகத்தைக் குறையற்ற ஞானி பருகினார்.",
        '0.29': "பன்னிரண்டு சூரியர்கள் போன்ற பன்னிரண்டு வெண்ணிற ஊர்த்வபுண்ட்ரங்களாலும், சங்கு சக்கர முத்திரைகளிலிருந்து எழும் ஒளியாலும் விளங்கிய, ஹரியின் அன்பரான, முராரியை விலக்குவோருக்குத் தாங்க முடியாத மதிப்புக்குரிய அறிவாளர், ப்ரளய காலத்தின் இன்னொரு சூரியன் போல ஒளிர்ந்தார்.",
        '0.30': "மிகுந்த அறிவாளரின் இயல்பாகவே இனிய, முகம் என்ற வேடத்தில் இருந்த முழுநிலவு வட்டத்தை நோக்கிக்கொண்டிருந்த கூட்டம், அவர் நகர்ந்தபோது, சீடர்கள் 'வழிவிடுங்கள்' என்று சொல்வதற்கு முன்பே கைகூப்பி விரைவில் வழிவிட்டது.",
        '0.31': "குருவின் இரு தாமரைத் திருவடிகளைக் கழுவிய நீர் முழுவதையும் — தரையில் விழுந்ததையும் சேர்த்து — மக்கள் எடுத்துக்கொண்டபோது, பூமி அதிருப்தியடைந்தும் எப்படியோ பொறுத்தாள்; இல்லையெனில் அவளுக்கு 'க்ஷமா' (பொறுமையுடையவள்) என்ற பெயர் எப்படி வரும்?",
        '0.32': "அடக்கமுள்ள ஒருவர் தூய கைகளுடன், சுவைக்கப்படாத, குளிர்ந்த, லேசான, மணமற்ற, தெளிந்த, நகம் படாத சிறந்த நீர் நிறைந்த கலசத்தை வாய் மூச்சுக்கு அஞ்சி ஒருபுறமாகப் பிடித்துக் கொண்டு வந்தார்.",
        '0.33': "உடைந்த தாமரைத் தண்டின் வெண்மையையும் ஏளனம் செய்யும் அழகிய சங்கை நறுமண மலர்களுடன் அமுதம் போன்ற நீர்த் தாரைகளால் நிரப்பினார் — ஸித்தாந்தங்களின் சிறப்புகளை ஆராய்வோரால் போற்றப்படும், தெளிவாகத் தூய பக்ஷத்தைச் சேர்ந்த அவர்.",
        '0.34': "தூய சந்தன நீர்த் துளிகளால் விக்ரஹங்களுக்குப் பூசி, நிலத்திலும் நீரிலும் பிறந்த கொடி, மரம், புதர்களின் எல்லா மலர்கள் மீதான வெற்றித் திருவே உருவெடுத்தது போன்ற புது இளம் துளசி, மலர் வரிசைகளால் இந்திரையின் கணவனை அர்ச்சித்தார்.",
        '0.35': "மேலான அறிவுடைய அவர் அபராதம் முதலிய முப்பத்திரண்டு குறைகளைத் தவிர்த்துப் பதினாறு உபசாரங்களை அளித்து, எண்ணற்ற குணமுடைய ஶார்ங்கபாணியை மிகவும் மகிழ்வித்து, பரம பக்தியுடன் ஆறு அனுபசாரங்களையும் அர்ப்பணித்தார்.",
        '0.36': "தெய்வ உடல் என்னும் வீட்டில், இதயத் தாமரை ஆசனத்தில் அமர்ந்த, பெரும் ஶ்ரத்தை என்னும் நதியின் மன நீரால் நீராட்டப்பட்ட அந்த மாணிக்க நிற இறைவனை அவர் ஒருமுறை மட்டுமல்ல, எப்போதும் எட்டு பாவ மலர்களால் பூஜிக்கிறார்.",
        '0.37': "பரம பூஜையை முடித்து, அடர்த்தியான சந்தன நீரால் மணக்கும் கைகளும் மார்பும் தோள்களும், புன்னகையால் அழகிய முகச் சந்திரனும், மென்மையான பட்டாடையும் உடைய அந்த மனீஷி, தேவர், முனிவர், மனிதர் கண்களுக்கு விருந்தானார்.",
        '0.38': "பிறகு வேத விவாதத்தில் தேர்ந்தவரும் வெல்லப்படாதவனின் பரம பக்தருமான பிரபு, 'எல்லா உலகின் தலைவனான ஶௌரி இதனால் மகிழட்டும்' என்று இடையறாது எண்ணியவாறு, முயற்சியின்றிக் கிடைத்த சிறந்த உணவை உண்டார்.",
        '0.39': "தோழர்கள் தயாரித்த, நுண்ணிய துணியால் மூடிய கம்பளி வெட்டிவேர் சிறந்த ஆசனத்தில் அமர்ந்து, சிறந்த மண்டபத்தை அழகுபடுத்தி, பலவகை இனிய கல்வி விளையாட்டுகளால் கவிஞர் குழாத்தை மகிழ்வித்தார்.",
        '0.40': "தக்க நேரத்தில் புருவ அசைவால் அழைத்த, வாயின் முன் தளிர்க்கையை வைத்த அன்புச் சீடனிடம், சிரிக்கும் கண்களின் மலர்ச்சியால் கருத்தை அறிந்த அவனுடைய காதில் அவர் விரைவில் ஏதோ ஒரு பணியைக் கூறினார்.",
        '0.41': "வணக்கமே உயர்ந்த கடமையாகக் கொண்டு அருகிலேயே கூடி நின்ற நல்லோர் கூட்டங்களைக் கடந்து, பல இல்லறத்தார் 'நான் முதலில், நான் முதலில்' என்று போட்டியிட்டு விரைவில் அவரருகே வந்து முதலில் பணிவிடை செய்ய வணங்கினர்.",
        '0.42': "பல நாடுகளிலிருந்து வந்த மற்றவர்கள், கேள்விப்பட்டதைவிட நூறு மடங்கு குணமுடையவராக அவரைக் கண்டு வியந்து, தாமரைக் கைகளைக் கூப்பி வந்தனர்; அவர் பெருமனத்துடன் 'அமருங்கள்' என்று அவர்களைக் கௌரவித்தார்.",
        '0.43': "'போதும், போதும் மீள்பார்வை; அதைப் பிறகு செய்யலாம்; இப்போது குருமார்கள் ப்ரவசனத்துக்குத் தயாராக இருக்கின்றனர்; இது சிந்தனைக்கான நேரமல்ல; விரைவில் வாருங்கள்' என்று சீடர் தலைவன் கேட்டதைச் சிந்தித்துக்கொண்டிருந்த சீடர்களை அழைத்தான்.",
        '0.44': "விளக்கவுரையால் ஒளிர்ந்த, ஸத்யவதியின் மகனான கவிஞர் சிறந்த ஹரியை (வ்யாஸரை) ஒத்த மேலான அறிவாளரை இமைக்காமல் இடையறாது நோக்கி மகிழ்ந்த மனமுடைய மக்கள் நேரம் கடந்ததையும் உணரவில்லை.",
        '0.45': "சூரியன் உதயத்தில் போலவே மறையும்போதும் தெளிவாகக் களங்கமற்றவனாய், காணத்தக்கவனாய், அன்பின் சிவப்புடன் ஒளிர்ந்தான்; ஹரியின் தூய திருவடிகளைச் சார்ந்த, தம் ஒளியால் உயர்ந்தோருக்கு ஆபத்துக்கும் செல்வத்துக்கும் வேறுபாடில்லை.",
        '0.46': "மரகத நிறமும் கடலே ஆடையுமான பூமி என்னும் மங்கையில் கணநேரம் பாதி மூழ்கிய செஞ்சூரிய வட்டம், பொன்னிறக் கதிர்க் கூட்டத்தால் ஒளிரும் பத்மராகம் போலக் காணத்தக்கதாயிற்று.",
        '0.47': "அந்தப் பெருமனத்தார் ஸமாதியில் நிலம், நீர், தீ, காற்று, ஆகாயம், அகங்காரம், மஹத், ப்ரக்ருதியின் குணங்களுடன் கூடிய அவ்யாக்ருத ஆகாயம் ஆகியவற்றில் பரவிய, அஸுரர், தேவர், மனிதர்களிலிருந்து வேறான, நற்குணம் நிறைந்த ஒரே தலைவனை தியானித்தார்.",
        '0.48': "தர்மஶாஸ்த்ரத்தில் தேர்ந்த, விதித்ததைப் பின்பற்றும் அந்தணர்கள் நட்சத்திரங்களைக் கண்டபின், சூரியனில் மூவுலகின் ஸவிதாவை தியானித்து, மாலை ஸந்த்யா நியமத்தை முறையாகச் செய்தனர்.",
        '0.49': "அக்னியின் கலைப் பிரிவுகளின்படி ஹரன் முதல் இந்திரன் வரை கூறப்பட்ட பதினாறு தேவதைகளை நன்கறிந்த ஆஹிதாக்னிகள், காயத்ர லோகத்தை அளிக்கும் அக்னிஹோத்ரத்தை முறையாக ஹோமம் செய்து நடத்தினர்.",
        '0.50': "'இந்தச் சந்திரன் களங்கமற்றவனாக இருந்தால் நிச்சயமாகத் தன் சகோதரியின் (லக்ஷ்மியின்) அழகிய முகச் சந்திரனைப் போல இருப்பான்' என்று வானில் உலவும் தேவ மங்கையரால் கொஞ்சப்பட்டு, மிகுந்த இனிமையுடன் முழுநிலவு அப்போது உதித்தது.",
        '0.51': "சூரியனின் தாங்க முடியாத பிரிவை அடைந்த தாமரைகளும் சக்ரவாகப் பறவைகளும் நெடுநேரம் வருந்தின; முன்பு வெந்த மென்மையான குமுதங்களும் சகோரங்களும் அரசனின் (சந்திரனின்) கதிர் தீண்டலால் மகிழ்ந்தன; விதி எல்லோர் இதயத்துக்கும் இனியதாக எதையும் செய்வதில்லை.",
        '0.52': "(52–53 ஶ்லோகங்கள் நிலவொளி இரவையும், மத்வர் அப்போது விளக்கிய க்ருஷ்ணனையும் ஒருசேர வர்ணிக்கின்றன.) உடைந்த இந்திரநீல மணியின் நீல ஒளியுடைய, புது முல்லை மொட்டுகள் போல வெண்மையான பல்வரிசையுடைய, புன்னகைக்கும், சிறந்த மலை உச்சியில் வளர்ந்த நறுமண வனமாலை அணிந்த;",
        '0.53': "மென்மையாக நடக்கும், விமானச் செல்வம் போன்ற, புன்னகைக்கும் ஆயர் அழகியரை மகிழ்வித்த, துயரற்ற, ஒளிமிக்க, எங்கும் நிறைந்த, மிக நுண்ணிய சிறந்த ஆடை அணிந்த (க்ருஷ்ணனை).",
        '0.54': "சந்திரன் கதிர்களால் இருளை அகற்றுவது போல, பகவான் (மத்வர்) தம் சொற்களால் அறியாமையை அகற்றி, இந்த ஶ்லோகங்களின் மற்றொரு பொருளை — உயிர்களுக்குக் கதி அருளும், ஆனந்தம் ஞானம் முதலிய குணங்கள் நிறைந்த க்ருஷ்ணனை — வெளிப்படுத்தினார்; சந்திரனுக்கு அக்குணங்கள் சொல்லளவில் மட்டுமே — இதுவே வேறுபாடு.",
        '0.55': "இவ்வாறு கவிகுலதிலகரான த்ரிவிக்ரம பண்டிதாசார்யரின் மகன் நாராயண பண்டிதாசார்யர் இயற்றிய, 'ஆனந்த' முத்திரையுடைய ஸ்ரீஸுமத்வவிஜய மஹாகாவ்யத்தின் பதினான்காம் ஸர்க்கம் நிறைவுற்றது.",
      },
    },
    'sumadhva-vijaya-15': {
      verses: {
        '0.0': "பிறகு பேரறிவாளர் அந்தக் கிராமத்தின் மக்களுக்குப் பொதுவான கோயிலில் தங்கி மீண்டும் தம் அற்புத பாஷ்யத்தை விளக்கினார்.",
        '0.1': "எதிர்த்தரப்பு என்னும் தேரில் ஏறி, கூரிய தர்க்கங்கள் என்னும் பெரும் ஆயுதங்களை ஏந்திய ஆர்ய த்ரிவிக்ரமரை அவர் எதிரே நிற்கும் எதிர்வீரன் போலக் கண்டார்.",
        '0.2': "அப்போது அவருடைய முகத் தாமரையிலிருந்து ஸித்தாந்தத்தை நிறுவும் சொல், பாசறையிலிருந்து படைத்தலைவனுடன் புறப்படும் தெய்வப் படை போல வெளிப்பட்டது.",
        '0.3': "அது மிக அவசரமோ மிக வேகமோ இல்லை, தடுமாறாதது, இடையறாதது; தொலைவில் இருந்தோர் அதைத் தனித்தனி உறுப்புகளே இல்லாதது போல வர்ணித்தனர்.",
        '0.4': "அந்தச் சொல் படை ஸூத்ரங்கள் என்னும் தேர்க் கூட்டங்களாலும், தடுக்க முடியாத ஶ்ருதிகள் என்னும் யானைகளாலும், நல்ல யுக்திகள் என்னும் பெரும் காலாட்படையாலும், பலவகை ஸ்ம்ருதிகள் என்னும் குதிரைகளாலும் நிறைந்திருந்தது.",
        '0.5': "கடலின் இன்னொரு திருவைப் (லக்ஷ்மியைப்) போல அது ஹரிக்குப் பிரியமானது, பொருள் அலைகளால் பொங்குவது, நல்ல மழைமேகம் போல ஆழ்ந்த குரலுடையது, விரிவாகப் பொருளை ஒளிரச் செய்வது.",
        '0.6': "பத்மேஶனின் திருவடித் தாமரைகளைச் சார்ந்த, தகுதியுடையோருக்குத் தாமரையில் பிறந்தவனின் (ப்ரஹ்மாவின்) பதவியை அளிக்கும், ஈஶனால் தலையில் போற்றப்பட்ட அந்தச் சொல், கங்கையைப் போல அனைத்தையும் புனிதமாக்கியது.",
        '0.7': "(7–63 ஶ்லோகங்கள் வாதத்தின் சாரத்தைக் கூறுகின்றன.) எல்லையற்ற குணமுடைய, 'ப்ரஹ்மம்' எனப்படும், வேதங்களால் அறியப்படும் நாராயணனே ஸர்வஜ்ஞனான உலகப் படைப்பாளன் என்று அவர் ஶ்ருதியாலும் யுக்தியாலும் நிறுவினார்.",
        '0.8': "பால் போல மாறுவதால் ப்ரதானமே (ப்ரக்ருதியே) சுதந்திரக் காரணம் என்றால், உதாரணத்தில் ஸாத்ய வைகல்யக் குறை உண்டாகும் (பாலின் மாற்றமும் செய்பவனைச் சார்ந்ததே).",
        '0.9': "'விவாதத்துக்குரிய படைப்பு உணர்வுள்ளவனின் விருப்பத்தைப் பின்பற்றுகிறது, ஏனெனில் அது படைப்பு, துணியின் படைப்பைப் போல' என்ற அனுமானம் நம் தரப்பை நிறுவுகிறது.",
        '0.10': "படைப்பில் ஈஶ்வரனைச் சாராமல் உணர்வுள்ளதற்கும் உணர்வற்றதற்கும் அங்க-அங்கி உறவு முதலியவற்றை ஏற்போரின் கருத்து பொருந்தாது.",
        '0.11': "ஈஶ்வர அனுமானம்: 'அனைத்தும் ஸர்வஜ்ஞனால் படைக்கப்பட்டது, ஏனெனில் அது சில காலம் மட்டுமே உள்ளது; அப்படி (படைக்கப்பட்டது) அல்லாதது அப்படி (நிலையற்றது) அல்ல, ஆத்மாவைப் போல.'",
        '0.12': "எல்லா அனுமானங்களுக்கும் வலிமைக்கு வேதங்கள் தேவை; அவற்றால் காக்கப்படாத அனுமானங்கள் கணவர்களால் கட்டுப்படுத்தப்படாத மனைவியர் போல விருப்பப்படி செல்கின்றன.",
        '0.13': "'ப்ரஹ்மம் உணர்வுள்ளதாதலால் மாறும் காரணம் அல்ல; அப்படி (உணர்வுள்ளது) அல்லாதது அப்படி (மாறாதது) அல்ல, பால் முதலியவை போல.' (ப்ரஹ்ம பரிணாம வாத மறுப்பு.)",
        '0.14': "ஶ்ருதியில் (பரம) குணங்கள் இல்லாதவர் எனக் கூறப்படுவதால் சைத்ரனைப் போலப் பஶுபதி உலகப் படைப்பாளர் அல்லர்; சிறுபிள்ளை அறிவினர் ஐயுறும் விக்னேஶன், சூரியன் முதலியோரைப் பற்றிச் சொல்வானேன்?",
        '0.15': "(மறுப்பு:) 'ஈஶ்வரன் துன்பம் முதலியவை அற்றவன் ஆதலால் இன்பம் முதலியவை உடையவன் அல்லன்; அப்படி அல்லாதது அப்படி அல்ல, ஸம்ஸாரியைப் போல.'",
        '0.16': "(பதில்:) இதே முறையில் 'விவாதத்துக்குரிய ஈஶ்வரன் மயக்கம் அற்றவன் ஆதலால் ஞானி அல்லன்; அப்படி அல்லாதவன் அப்படி அல்லன், ஸம்ஸாரியைப் போல' என்றும் அனுமானிக்கலாமே.",
        '0.17': "நம்பத்தக்க வேதம் ஸர்வஜ்ஞனுக்கு அறியாமையை மறுக்கிறது என்றால், அவனை 'ஆனந்தம்' என்று கூறும் அதே வேதம் உனக்கு எப்படிக் கேட்கத் தகாததாயிற்று?",
        '0.18': "ஈஶ்வரனிடமிருந்து துன்பத்தை நீக்க விரும்பி இன்பத்தை ஏற்காத மந்தன், (அவனுடைய சொந்தத் தர்க்கத்தாலேயே) ஈஶ்வரன் மீது துன்பம் வந்து விழுவதை மறந்துவிட்டான்.",
        '0.19': "சைத்ரனிடமுள்ள துன்ப ஸமவாயம் ஈஶ்வரனிடமுள்ள ஸமவாயத்திலிருந்து வேறானதல்ல (ஸமவாயம் ஒன்றே என ஏற்கப்பட்டதால்); இல்லையெனில் ஸமவாயம் பலவாகிவிடும்.",
        '0.20': "அதன் வேறுபாடு உபாதியால் என்றால், அது உண்மையா பொய்யா என்று சொல்; இரண்டிலும் முன்பு கூறிய குறைகள் உள்ளன; மாயாவாதியைப் போலப் பேசாதே.",
        '0.21': "ஆத்மாவின் ஞானம் முதலியவற்றுக்கு உபாதியால் வேறுபாடு என்று சொன்னால், அதுவும் இதே நெறியால் மறுக்கப்படுகிறது; ஆகவே பகவான் எல்லையற்ற தர்மங்கள் உடையவன்.",
        '0.22': "குணம் முதலியவை வேறானவை என்றால் தொடர்பைச் சார்ந்து முடிவிலாத் தொடர்ச்சி (அனவஸ்தை) உண்டாகும்; ஆகவே 'விஶேஷம்' மாத்திரத்தாலேயே பகவானின் குணங்களின் எல்லையின்மை பொருத்தமானது.",
        '0.23': "ஆகம எதிரிகளான வேறு சிலர் ஶூன்யமே தத்துவம் என்று கருதுகின்றனர்; அவர்கள் மாத்யமிகர்கள், வெளிப்படையானவர், மறைந்தவர் என்று இருவகையினர்.",
        '0.24': "இரண்டாம் வகைத் தீயோர் ஶூன்யத்தை 'ப்ரஹ்மம்' என்ற பெயரால் அழைத்து, தம்மை வேதாந்திகள் என்று கூறி, வேதம் உண்மையை அறிவிப்பதில்லை (அதத்துவாவேதகம்) என்கின்றனர்.",
        '0.25': "இருவருக்கும் முழு அபர தத்துவமும் பர தத்துவத்தின் விவர்த்தம், அதுவும் விஶேஷமற்றது — ஆகவே இவ்விருவருக்கும் இடையே உள் வேறுபாடு இல்லை.",
        '0.26': "பிளவற்ற ஞானமுடையவர் 'அகண்ட கண்டன' நியாயத்தின் கூறுகளையும் மறுத்து, தேவர்களைப் பகைக்கும் அவ்விரு வகையினரையும் மறுத்தார்.",
        '0.27': "இங்கே இவ்வாறு அனுமானிக்கப்படுகிறது: 'விவாதத்துக்குரிய (ஶூன்யம்) இல்லாதது ஆதலால் காரணமாக முடியாது; அப்படி அல்லாதது அப்படி அல்ல, குயவனைப் போல.'",
        '0.28': "(பௌத்தர்:) 'தவசியே, ஶூன்யம் குயவனைப் போலக் காரணம் அல்ல; ஸம்வ்ருதியால் உலகம் அதிலிருந்து எழுகிறது என்ற பொருளில் அது காரணம் எனப்படுகிறது.'",
        '0.29': "'அப்படியானால் ஶூன்யத்தை எவ்விதத்திலும் காரணம் என்று சொல்லாதே; நீடூழி வாழ்பவனே, அதிஷ்டானம் என்பதன் பொருளை குருவின் வீட்டில் கற்றுக்கொள்.'",
        '0.30': "'விவாதத்துக்குரியது இல்லாதது ஆதலால் அதிஷ்டானமாக முடியாது' — இது வேற்றுமை உதாரணத்தால் கூறப்படுகிறது: (அதிஷ்டானம் உள்ளது) வெள்ளி என மயங்கப்படும் சிப்பி முதலியவை போல.",
        '0.31': "'உண்மையை அறிவிக்காத ப்ரமாணம்' என்பது தனக்குத்தானே முரணானது; ஆகவே வேதத்தை அப்படிச் சொல்பவன் வேதம் ப்ரமாணமே அல்ல என்றுதான் கருதுகிறான்.",
        '0.32': "வேதத்தைப் பழிப்பவனான அவன் எந்த வேதாந்தப் பகுதியை உண்மையை அறிவிப்பதாகக் கருதுகிறானோ, அவன் கருத்துப்படி உண்மை வர்ணிக்க இயலாதது ஆதலால் அது உண்மையை எப்படி அறிவிக்கும்?",
        '0.33': "வாக்கியங்கள் மூவகை லக்ஷணைகளால் செயல்படுகின்றன என்றால், ப்ரஹ்மம் லக்ஷணைகளின் விஷயமாகிறது — அது அவனுக்கே விரும்பத்தகாதது.",
        '0.34': "மேலும் இந்தப் பிளவற்றதைப் பற்றி வாக்கியங்கள் எதையும் கூறுவதில்லை; அவை ஜடத்தன்மை முதலியவற்றின் இல்லாமையைக் கூறுகின்றன என்றால் அதுவும் பொருந்தாது,",
        '0.35': "ஏனெனில் உள்ளதான அதற்கு இல்லாமையின் இயல்பு இருக்க முடியாது; விஶேஷமற்றதாதலால் உள்ளது இல்லாதது ஆகியவற்றின் அடைமொழிகளும் அதற்கு இருக்க முடியாது.",
        '0.36': "வேதம் அறிவித்த பொருள்களை என்றும் கைவிடும் சபதமுடையவனை அறிஞர்கள் வேதத்துக்குப் புறம்பானவன் என்று உறுதி செய்ய வேண்டும்.",
        '0.37': "மூத்தவனின் (பௌத்தனின்) மறுப்பாலேயே தன்னைச் சாமர்த்தியசாலி என்று கருதுபவனும் மறுக்கப்பட்டான்; நல்லோருக்கு எதிரான இவ்விரு தரப்புகளுக்கும் வேறுபாடில்லை.",
        '0.38': "'இல்லாததாதலால் என்ற ஹேது எனக்குப் பொருந்தாது' என்று ப்ரஹ்மவாதி சொல்லக் கூடாது; ப்ரஹ்மம், ஶூன்யம் என்ற இரு தத்துவங்களுக்கும் கூறத்தக்க வேறுபாடில்லை.",
        '0.39': "அவன் ப்ரஹ்மத்தின் உள்ளதன்மையை ஏற்றால் ப்ரஹ்மம் அடைமொழி உடையதாகிறது; ஏற்காவிட்டால் எஞ்சியதால் இல்லாமையே வருகிறது, அதை அவனால் மறுக்க முடியாது.",
        '0.40': "விவாதத்துக்குரிய அத்வைத ப்ரஹ்மம் விதிக்கும் அறிவுக்கும் விஷயம் அல்லாததால், ஶூன்யத்தைப் போல, ஆராயத்தக்கதும் அல்ல, தியானிக்கத்தக்கதும் அல்ல, பயன் தருவதும் அல்ல;",
        '0.41': "ஏனெனில் அது வான் மலரைப் போலப் பிளவற்றது; வேற்றுமை உதாரணம் ப்ரமாணம் முதலியவை (அவை ஆராயத்தக்கவை); இவ்வாறு விரும்பிய அளவு யூகிக்கலாம்.",
        '0.42': "வேதங்கள் ப்ரமாணம் அல்லவென்றால் தர்மம் முதலியவற்றுக்கு ப்ரமாணம் இல்லை; ப்ரத்யக்ஷம் ஒன்றையே ப்ரமாணம் என்பவனுக்கு (சார்வாகனுக்கு) தர்மம் முதலியவற்றை அறிய எந்த ப்ரமாணமும் இல்லை.",
        '0.43': "மனிதன் இயற்றிய சொல் (புலன் கடந்த விஷயங்களில்) ப்ரமாணம் என உறுதிப்படவில்லை, ஏனெனில் அது மனிதனுடையது — பித்தனின் உளறல் போல.",
        '0.44': "'விவாதத்துக்குரிய மனிதன் அறியாதவனாகவோ ஏமாற்றுபவனாகவோ இருக்கலாம், ஏனெனில் அவன் மனிதன், சைத்ரனைப் போல' — இத்தகைய அனுமானங்களால் (மனிதனின்) ஸர்வஜ்ஞத்துக்கான வெறும் அனுமானங்கள் மறுக்கப்படுகின்றன.",
        '0.45': "தவறான ஶாஸ்த்ரங்களில் கடும் பிடிவாதம் இறைவனை அதிருப்தியடையச் செய்கிறது; ஆகவே அதை உடையோருக்குத் துயர் தரும் கொடிய உலகம் உறுதி.",
        '0.46': "நாம் ஏற்கும் தரப்பில் அதோக்ஷஜன் மோக்ஷம் அருள்கிறான்; அதில் நல்லோர் தம் இயல்பான ஆனந்தத்துடன் பல இன்பப் பொருள்களை அனுபவிக்கின்றனர்.",
        '0.47': "விஶேஷமின்மை என்னும் முக்தி தனக்குத்தானே முரண்பாடு முதலியவற்றால் புறக்கணிக்கத்தக்கது; 'எப்போது?' முதலிய கேள்விகளுக்குப் பதில் சொன்னால் அதற்கு விஶேஷம் வந்துவிடும்; பதில் சொல்லாவிட்டால் அது இல்லவே இல்லை.",
        '0.48': "அறிவு முதலியவை அற்றவன் எவ்விதத்திலும் புருஷார்த்தம் நாடுபவனாக முடியாது, ஏனெனில் அவனுக்கு எந்த அனுபவமும் இல்லை — பொம்மை முதலியவை போல.",
        '0.49': "ஞானம், முயற்சி, விருப்பம் உடைய ஈஶ்வரன் அமங்கலத்தை அடைவதில்லை; அதே தன் ஆற்றலால் அவன் முக்தனையும் அப்படியே ஆக்க முடியும்.",
        '0.50': "கட்டுண்டவனிடம் இன்பம் துன்பத்துடன் கலந்திருப்பதைக் கண்டு முக்தனுக்கு இன்பத்தை மறுப்பவன், அதே தர்க்கத்தால் அவனுடைய ஸ்வரூபத்தையும் மறுக்க வேண்டும்; அப்போது அவன் ஶூன்யவாதி ஆகிவிடுவான்.",
        '0.51': "(மறுப்பு:) 'விவாதத்துக்குரிய முக்தன் உடலுடையவன் ஆதலால் சைத்ரனைப் போலப் பசி தாகம் முதலிய அலைகள் உடையவன்.' (பதில்:) இங்கே 'தூய்மையற்ற உடல் உடைமை'யே உபாதி.",
        '0.52': "'உடல் உடைமை' என்ற ஹேது ஈஶ்வரனிடம் பொருந்தாமையால் உறுதியற்றது; அவன் உடலற்றவன் என்றால் முயல் கொம்பைப் போல விருப்பம் முதலியவை அற்றவனாவான்.",
        '0.53': "அதிலிருந்து வேறுபடுத்த அவனுக்கு அறிபவன் முதலிய வடிவை ஏற்றால், அதையே 'உடல்' என்ற சொல்லால் கூறுகிறோம்; அது ப்ராக்ருத வடிவம் அல்ல.",
        '0.54': "அதுபோலவே முக்தனுக்கும் ஸ்வரூப உடல் ஏற்கப்பட்டுள்ளது; ஆகவே ப்ராக்ருத உடலால் உண்டாகும் விரும்பத்தகாத அனுபவம் அவனுக்கு இல்லை.",
        '0.55': "(மறுப்பு:) 'விவாதத்துக்குரிய முக்தன் உறுப்புகள் அற்றவன், இல்லையெனில் துணியைப் போல அழியக் கூடியவனாவான்.' (பதில்:) இங்கே எத்தகைய உறுப்புகள் மறுக்கப்படுகின்றன?",
        '0.56': "அவை வேறானவையும் உணர்வற்றவையுமானால் உன் ஹேது ஏற்கனவே ஏற்கப்பட்டதையே நிறுவுகிறது; ஆத்மாவிலிருந்து வேறுபடாத உறுப்புகளை வாதிகளும் ஏற்கவே வேண்டும்.",
        '0.57': "பரவலுக்காக அணு முதலிய இடங்களிலும் வ்யாமம் (கைவிரிப்பு அளவு) முதலியவற்றிலும் ஆத்மாவுக்குப் பகுதிகள் உண்டென நீங்கள் ஏற்பது போல, நமக்கு அவையே உறுப்புகள்.",
        '0.58': "'முக்தன் ஜடத்திலிருந்து வேறாக உள்ளவனாதலால் ஈஶ்வரனைப் போல வடிவம் முதலியவற்றை அறிபவன்' — ஈஶ்வரனின் ஸர்வஜ்ஞம் ஏற்கப்பட்டதால் உதாரணத்தில் ஸாத்ய வைகல்யம் இல்லை.",
        '0.59': "'ஈஶ்வரன் வடிவம் முதலியவற்றை அனுபவித்தாலும் துன்பம் வருமாதலால் இன்புறுபவன் அல்லன்' என்று சொல்லாதே; அந்த வ்யாப்தியே குறையுடையது.",
        '0.60': "இந்த உதாரணத்தை (ஈஶ்வரனை) ஏற்காதவனுக்கு 'கல்லைப் போல' என்ற வேற்றுமை உதாரணம் உள்ளது; ஆகவே முக்தன் தூய உணர்வு வடிவான உடலாலும் புலன்களாலும் அனுபவிக்கிறான்.",
        '0.61': "வேதம் கூறியதும் யுக்தியால் நிறுவப்பட்டதும் இயல்பான ஆனந்தம் நிறைந்ததுமான மோக்ஷத்தின் மீது வாதிகளுக்கு ஏன் இந்தப் பகைமை? அல்லது அதற்கு எதிரானதில் ஏன் பிடிவாதம்?",
        '0.62': "ஆகவே தானே ப்ரமாணமான வேதத்தால் விஷ்ணு தேவனே மோக்ஷம் முதலியவற்றை அருள்பவன் என்று அறியப்பட்டால் உலகம் முழுவதும் மங்கலமாகிறது.",
        '0.63': "இவ்வாறு விளக்கவுரைகளுடனும் வாதங்களுடனும் ஸர்வஜ்ஞர் காட்டிய இவை முதலிய பொருள்களை ஆர்ய த்ரிவிக்ரமர் அப்போது கேட்டார்.",
        '0.64': "பிறகு அவர் (த்ரிவிக்ரமர்) ஞானம் என்னும் வில்லின் நாணிலிருந்து விடப்பட்ட, எதிர்த்தரப்பை நோக்கிய பலவகைக் கூரிய தர்க்க அம்புகளை வீரத்துடன் ஏவினார்.",
        '0.65': "சிறிதல்லாத அறிவுடைய அவர் சிரித்தவாறு, அவை ஏவப்பட்ட உடனே தம் மேலான தர்க்க அம்புகளால் விளையாட்டாக அவற்றை வெட்டினார்.",
        '0.66': "வெல்ல விரும்பிய அந்த அந்தணர் சிறந்தோர் அப்போது பிறரால் தாங்க முடியாத, மனிதர்களால் திருப்ப முடியாத வேத அஸ்திரங்களை ஏவினார்.",
        '0.67': "மிக வலிமையான வைதிக வாக்கியங்கள் என்னும் எதிர் அஸ்திரங்களால் அவற்றின் வேறான (உண்மைப்) பொருளை வெளிப்படுத்தி அவர் அந்த அஸ்திரங்களைத் திருப்பினார்.",
        '0.68': "இவ்வாறு பதினைந்து (ஏழும் எட்டும்) நாட்கள் அவருடன் வாதிட்டுச் சக்கராயுதனின் அன்பர் அவரைப் பதிலற்றவராகவும் கேள்வியற்றவராகவும் ஆக்கினார்.",
        '0.69': "அந்தப் பண்புடையவர் வணங்கிக் கூறினார்: 'நாதா, என் துடுக்கை மன்னியுங்கள்; உங்கள் திருவடித் தாமரைத் தூசிக்குப் பணிவிடையை எனக்கு என்றும் அருளுங்கள்.'",
        '0.70': "பிறகு ஒருசேரத் தொடங்கின — பேரறிவாளரின் பாஷ்ய விளக்கம், அறிஞர் மகனின் (த்ரிவிக்ரமரின்) கேட்டல், நல்லோரின் மகிழ்ச்சி, தீயோரின் வேறான உணர்வு.",
        '0.71': "குருவின் ஆணையின் மதிப்பால் பாஷ்யத்துக்குக் கடினமான உரையை (தத்துவப்ரதீபத்தை) இயற்றியவாறு ஆர்ய த்ரிவிக்ரமர் (ஆறில் பாதி விக்ரமர்) மஹாசார்யரிடம் கூறினார்:",
        '0.72': "'கவியரசர்கள் இடையறாது சேகரித்தாலும் இந்த பாஷ்யக் கடலின் நியாய ரத்தினங்கள் தீர்வதில்லை; இதன் ஆழம் அற்புதம்!",
        '0.73': "உங்களுடைய இந்த உபநிஷத் பாஷ்யங்கள் என்னும் மாளிகைகளில், தேவர்கள் விரும்பும் தேவியர் போல, பத்து உபநிஷத்துகளும் தம் பொருள்களுடன் இணைந்து நன்கு அருள்புரிகின்றன.",
        '0.74': "கீதா பாஷ்யம், கீதா தாத்பர்யம் ஆகிய இவ்விரண்டாலும், சூரிய சந்திரரைவிட மேலாக, தடுக்க முடியாத கதிர் (சொல்) கூட்டங்களால் உலகம் ஒளிர்கிறது.",
        '0.75': "உங்கள் மனம் என்னும் மலையால் கடையப்பட்ட இதிகாச புராணக் கடலிலிருந்து பிறந்த பாரத தாத்பர்ய (நிர்ணய) அமுதத்தை எந்த நல்லவன் பருகாமலிருப்பான்?",
        '0.76': "மூவகை மொழிகளை அறியாத புராண வழிப் பயணிகளுக்கு நீங்கள் ஸ்ரீபாகவத (தாத்பர்ய) நிர்ணயத்தைச் சிறந்த தோழனாக்கினீர்கள்.",
        '0.77': "தேவர்கள் சார்ந்திருக்கும் நிழலுடைய சிறந்த கற்பக மரம் போன்ற தந்திரஸாரத்தைப் பெற்று யார் விருப்பங்கள் நிறைவேறாதவராவார்?",
        '0.78': "மக்கள் இந்த வழியைக் காண நீங்கள் கருணை நிறைந்த கண்கள் போன்ற ப்ரமாண லக்ஷணம், கதா லக்ஷணம் ஆகியவற்றை இயற்றினீர்கள்.",
        '0.79': "தனியாகவே பகைவர்களின் தலைமேல் கால் வைத்த பார்த்தனைப் போன்ற இந்த தத்துவ நிர்ணயம் யாரால் போற்றப்படாது?",
        '0.80': "வாதம் முதலிய ப்ரகரணங்கள் தீப்பொறிகள் போலச் சிறியவையாயினும், காற்றான உங்களால் தூண்டப்பட்டு எதிர்த்தரப்பு என்னும் உலர்ந்த புதரை எரிக்கப் போதுமானவை.",
        '0.81': "அணு அளவான பாஷ்ய ஸங்க்ரஹத்தில் (அணுபாஷ்யத்தில்) நீங்கள் எல்லையற்ற பொருளை வெளிப்படுத்தினீர்கள்; ஆஹா! தன்னை அறிவிக்க க்ருஷ்ணன் வாய்க்குள் (உலகைக்) காட்டியது போல.",
        '0.82': "பகவானே, உலகியல் சித்திரக் கவிதையைக் காட்டியவாறு நீங்கள் மறைபொருள் கொண்ட பாரத ஸங்க்ஷேபத்தை (யமக பாரதத்தை) உலக வியப்பாக இயற்றினீர்கள்.",
        '0.83': "ரத்னாகரமான உங்களிடமுள்ள ரத்தின வரிசைகள் போன்ற பலவகை நல்மொழிகள், துதிகள், பாடல்கள் முதலிய சிறந்த படைப்புகளை யார் எண்ண முடியும்?",
        '0.84': "இவற்றைச் சிறியவையாயினும் அளவற்ற பொருள் தரும் சிந்தாமணிகளாகக் கருதி, நல்லோர் சபை இவற்றைச் சிறியவை என்னும் சிற்றறிவாளரைக் கண்டு உரக்கச் சிரிக்கிறது.",
        '0.85': "இந்த நூல்கள் இருந்தும் நாங்கள் இன்னொன்றை விரும்புகிறோம் — முன்பு இந்திரன் முதலியோர் இருந்தும் தேவர்கள் தாரகனைக் கொன்றவனை (ஸ்கந்தனை) விரும்பியது போல.",
        '0.86': "ஆழம் காண முடியாத இந்த நூல்களிலிருந்து யுக்திகளை எடுப்பது எங்கள் மந்த அறிவால் கடினம்; ஆகவே தர்க்க வரிசையைத் தெளிவாகக் காட்டும் நூலை இயற்றுங்கள்.'",
        '0.87': "இவ்வாறு வேண்டப்பட்ட மத்வர், நல்லோருக்கு அமுதமும், தீய வாதிகளின் செருக்கு மலைக்கு வஜ்ராயுதமும், மாயாவாதிகளின் இருளுக்குச் சூரிய ஒளியுமான அனுவ்யாக்யானத்தை இயற்றினார்.",
        '0.88': "ஒருமுறை அதை ஒரே நேரத்தில் இடையறாது இயற்றியவாறு அவர் நான்கு திறமையான சீடர்களைக் கொண்டு விளையாட்டாக (நான்கு அத்தியாயங்களையும்) ஒருசேர எழுதுவித்தார்.",
        '0.89': "அங்கே தாமே கூறிய யுக்திமாலைக்கு அவர் கவியரசர்களுக்கும் கடினமான தெளிவான விளக்கத்தை (ந்யாயவிவரணத்தை) இயற்றினார்.",
        '0.90': "மத்வச் சந்திரனின் நிலையான தொடர்பால் அறியாமையும் துயரமும் அற்ற மனமுடைய பெற்றோர் வைகுண்டம் சென்ற பின், அவருடைய தம்பி வீட்டில் வசித்து வந்தார்.",
        '0.91': "விதியின் புருவ அசைவு மாத்திரத்தால் செல்வம், பசு, தானியச் செல்வம் அழிய, பற்றற்ற அந்த வேதமறிந்தவர் வேதவாதிகளின் அரசரை அடைந்தார்.",
        '0.92': "திருவடிகளில் மீண்டும் மீண்டும் பணிந்து ஸந்ந்யாஸம் வேண்டியவரை, தக்க நேரத்தை எதிர்நோக்கி அந்தத் தொலைநோக்கர் வீட்டுக்கு அனுப்பினார்.",
        '0.93': "உறுதியான அறிவுடைய அவர் நேரத்தை எதிர்பார்த்து, அண்ணனை நினைத்தவாறு, ராமனை நினைத்த ராமனின் தம்பியைப் (பரதனைப்) போல உண்ணவில்லை, உறங்கவில்லை, சிரிக்கவில்லை.",
        '0.94': "பிரிவால் வருந்திய அரசனை எப்படியோ அரசாட்சியில் நிறுத்தி, பகவான் கூதிர்காலத்தின் இறுதியில் தம் அவதார பூமிக்குச் சென்றார்.",
        '0.95': "இரு குலங்களிலும் தூய்மையானவரும், ஶ்ரௌதரும், சுத்தமானவரும், பித்ரு கர்மங்களைச் செய்தவரும், உலக இன்பங்களை அனுபவித்துப் பற்றற்றவருமான தம்பியை மத்வர் யதியாக்கினார்.",
        '0.96': "ப்ரஹ்மாவுக்கு நிகரான அவர், ஐந்தீ தவம் செய்யும் தவசிகளும் அறியாத, ரகசியங்களுக்கெல்லாம் ரகசியமான அந்த ப்ரஹ்மத்தை அவருக்கு உபதேசித்தார்.",
        '0.97': "அன்பு அமுதத்தால் மலர்ந்த முகத்துடன், புன்னகையும் ஓரப்பார்வையும் கொண்டு ப்ரீதிதீர்த்தர் அவருக்கு 'ஸ்ரீவிஷ்ணுதீர்த்தர்' என்ற பெயரை அளித்தார்.",
        '0.98': "வேதாந்த குருவின் சகோதரர் வேதாந்த ஶாஸ்த்ரத்தைக் கேட்டல், மீண்டும் உரைத்தல், சிந்தித்தல் மூலம் தம் காலத்தைப் பயனுள்ளதாக்கினார்.",
        '0.99': "புலனடக்கம், பக்தி, இனிமை, பணிவிடை முதலிய வளமான ஊட்டங்களால் அவர் தம்மிடம் குருவருளின் முளையை நலமான பெருமரமாக வளர்த்தார்.",
        '0.100': "அனந்தமதியின் (மத்வரின்) கருணை என்னும் கற்பக மரத்தை உடைய அவருடைய மகிமை மனிதர்களால் வர்ணிக்க இயலாதது; ஆவலால் சிறிது வர்ணிக்கப்படுகிறது.",
        '0.101': "ப்ரவசனத்தில் திறமையும் மந்திர ஸித்தியும் உடைய அவர், 'மத்வரின் அடியார் எண்ணிக்கை என்னைக் கடைசியாகக் கொண்டு முடியக்கூடாது' (அதாவது முதன்மையானவராக வேண்டும்) என்று மனத்தில் உறுதி கொண்டார்.",
        '0.102': "வடதிசை நோக்கிச் சென்று பூமியில் சஞ்சரித்த விஷ்ணுதீர்த்தரைத் தீர்த்தங்கள் புனிதமாக்கின; விஷ்ணுதீர்த்தர் தீர்த்தங்களைப் புனிதமாக்கினார்.",
        '0.103': "தம்மை மறைத்துக்கொண்டு அவர் பல ஆசையற்ற தவசிகளின் ஸித்தி பூமியான ஹரிஶ்சந்த்ர மலையை அடைந்தார்.",
        '0.104': "பொறாமையற்ற அந்த வீரர் பொறாமையாலோ என்பது போல, உணவு முதலியவற்றை இருமைத் துயரத் தீக்கு விறகு என்று கருதிக் கைவிட்டார்.",
        '0.105': "பக்தர்களின் வேண்டுகோளின்படி அந்த யதிகளின் முடிமணி மலைமேல் கொண்டுவரப்பட்ட பஞ்சகவ்யத்தை ஐந்து நாளுக்கு ஒருமுறை சிறிது பருகினார்.",
        '0.106': "அதையும் கைவிட்டு அந்தத் துணிச்சலாளர் தரையில் விழுந்த வில்வ இலைகளாலும் நீராலுமே நிறைவுற்று, தவசிகளையும் விஞ்சிய தவம் செய்தார்.",
        '0.107': "விதியால் கைவிடப்பட்ட தவசிகள் ஒரு நாளும் அமர முடியாத அந்தப் பாறையின் மேல் அந்த அடக்கமும் நல்லொழுக்கமும் உடையவர் விரும்பியவரை அமர்ந்தார்.",
        '0.108': "வாயுவின் அம்சத்தின் தம்பி ரேசகம் முதலியவற்றால் ப்ராணனை வென்று, மனம் என்னும் சாரதியால் புலன்கள் என்னும் குதிரைகளை விஷயங்களிலிருந்து இழுத்தார்.",
        '0.109': "முராரியின் வடிவை நினைத்தவாறு அந்த ஆத்ம ஞானி தியானித்து, யோகத்தால் அடையத்தக்க, மனத்துயரைத் தணிக்கும் ஸமாதியை அடைந்தார்.",
        '0.110': "இயல்பான ஆனந்தம் முதலிய குணங்களின் கடலும் அதிசய ரத்தினமுமான முகுந்தனின் அழகிய வடிவில் ஆழ்ந்த மனமுடைய அவர் வேறெதையும் அறியவில்லை.",
        '0.111': "ஆசையும் அச்சமும் அற்ற, நல்ல ஞானக் கண்ணுடைய அவருடைய யோக மணிக்கு மோக்ஷ சாம்ராஜ்யத்தைத் தவிர வேறு விலை இல்லை.",
        '0.112': "மத்வரின் நாதன் அப்போது மத்வரின் தம்பிக்கு அருளிய அருள், மனத்துக்கு எட்டாததாலோ ரகசியமானதாலோ வர்ணிக்கப்படுவதில்லை.",
        '0.113': "'ஆஹா, மஹாபோதரின் பணிவிடையின் மகிமை! இந்த யுகத்திலும் இந்தப் புண்ணியர் இந்த ஸித்தியை அடைந்தார்' என்று தேவர்கள் அவரைப் போற்றினர்.",
        '0.114': "கடும் விரதமுடையவரும், புலன் கடந்ததை அறிபவரும், கல்விக் கடலும், தர்க்க பண்டிதருமான அனிருத்த(தீர்த்தர்) என்ற அன்புச் சீடர் அவரிடம் வந்தார்.",
        '0.115': "அவருடைய வேண்டுகோளின்படி மீண்டும் ரஜதபீடத்துக்கு வந்த அவரைக் கண்டு, ஸர்வஜ்ஞரே கருணையால் தம்மவரிடையே திரும்பி வந்தார் என்று மக்கள் கருதினர்.",
        '0.116': "கவியரசர்களின் திலகமும், அறிஞர்களின் முடியும், தவசிகளில் முதன்மையானவரும், மத்வரின் விளையாட்டுக் கிளியும், வ்யாஸரின் திருவடியைச் சார்ந்தவருமான வ்யாஸதீர்த்தர் அவருடைய சீடரானார்.",
        '0.117': "அவருக்கு அருள்புரிந்து, பெரியோரிடையேயும் பெரிதான நிலையான அடிமைத்தனத்தை (இறைவனுக்கு) அவர் அடையச் செய்து, தம் ஆற்றல்களால் மக்களை வியக்க வைத்தார்.",
        '0.118': "ஹரிக்கு இனியவரான அவர் பிறருக்கு ஏற அரிதான பெரும் மகிமையையும் குஹனுக்குப் பிரியமான (குமார) மலையையும் ஏறினார்.",
        '0.119': "எங்கும் பரவிய அவருடைய குணங்களால் ஈர்க்கப்பட்டுக் கோதாவரியிலிருந்து வந்தவர் அந்த நல்லுள்ளத்தாரின் மற்றொரு சீடரானார் — அவர் பத்மநாபதீர்த்தர்.",
        '0.120': "அவருடைய கேட்டல், சிந்தித்தல், நிலையான பக்தி, பற்றின்மை, நாள்தோறும் பணிவிடை ஆகியவற்றால் மகிழ்ந்த தொலைநோக்கர் உடனே அவருக்கு மங்கலமான வித்தையை அளித்தார்.",
        '0.121': "அந்த அறிஞர் திமிங்கிலம் யுக்தி ஓட்டத்தின் வேகத்தால் பிற ஶாஸ்த்ரங்கள் என்னும் நதிகளில் சஞ்சரித்தாலும் வேதாந்தக் கடலை ஒருபோதும் விடவில்லை.",
        '0.122': "அந்த வாதி சிங்கம் விளக்கவுரையின் கர்ஜனை மாத்திரத்தால் தம் வட்டாரத்தில் தம்மை வீரர்கள் என்று கருதிய மாயாவாதி ஊர் நாய்களை விரட்டியது.",
        '0.123': "மதம் கொண்ட தீய வாதி யானைகளின் தர்க்கம் என்னும் மத்தகங்களைப் பிளப்பதில் அவர் நான்முகரே (ப்ரஹ்மா போன்ற அறிஞரே) ஆயினும் தெளிவாக ஐம்முகரானார் (சிங்கமானார்).",
        '0.124': "அந்த ஞானக் கடலிலிருந்து சிறந்த அனுவ்யாக்யானத்துக்கு மங்கலமும் விலைமதிப்பற்றதுமான ஸந்ந்யாய ரத்னாவளி என்ற உரையும் தோன்றியது.",
        '0.125': "'வேத ப்ரவசன ஆசார்யரின் சீடர்' என்று போற்றப்பட்ட, பண்புடைய, வேதச் சாரம் அறிந்த அவர் சபையில் வேதத்தை விளக்கினார்.",
        '0.126': "இவ்விருவருக்கு முன்னும் பின்னும் பல நாடுகளில் பிறந்த பல யதீந்திரர்கள் அனந்தபோதரின் (மத்வரின்) சீடர்களாயினர்.",
        '0.127': "(127–128 ஶ்லோகங்கள் அவர்களுடைய பெயர்களைக் குறிப்பிடுகின்றன.) புலன்களை (ஹ்ருஷீகங்களை) அடக்கிய ஹ்ருஷீகேஶ(தீர்த்தர்), பிறப்பு முதலியவற்றை நசுக்கும் ஜனார்தனர், நரஸிம்ஹனின் திருவடியைச் சார்ந்த நரஸிம்ஹர், அப்பெயரைப் பயின்ற உபேந்திரர்;",
        '0.128': "'நெடியது அல்லாதது' என்பதன் வேறு பெயருடையவர் (வாமனர்), ஸ்ரீராமனின் திருவடியைச் சார்ந்த ராமர், புலன் கடந்த குணங்களால் நிறைந்த அதோக்ஷஜர் — பக்தியும் பற்றின்மையும் கொண்ட கடல்கள்.",
        '0.129': "பாதங்களால் (சூரியர்கள் கதிர்களால் போல) பூமியைப் புனிதமாக்கி, ஹரியின் இருப்பிடத்தைக் காட்டி, தவறான மதங்களின் இருளை அகற்றி, அவர்கள் பூமிக்கு வந்த சூரியர்கள் போல இருந்தனர்.",
        '0.130': "மோக்ஷ ஶாஸ்த்ரம் என்னும் அமுதக் கடலின் சேவையால் என்றும் மகிழ்ந்த அவர்கள் சக்கரதாரியின் மிக அழகிய விக்ரஹங்களில் அவனுடைய திருவடிகளை அர்ச்சித்தனர்.",
        '0.131': "மத்வரின் சீடர்களின் சீடர்களும் மீண்டும் அவர்களுடைய சீடர்களுமான பலர், அனைவரும் நற்குண அணிகலன்களுடன், பூமியை நன்கு அழகுபடுத்தினர்.",
        '0.132': "அனைவரும் எல்லா நல்ல ஶாஸ்த்ரங்களையும் விளக்கும் இன்ப அமுதக் கடலில் எப்போதும் ஆழ்ந்து, தீய வாதிகளின் தவறான வாதங்களை மறுப்பதையே அணிகலனாகக் கொண்டிருந்தனர்.",
        '0.133': "சிலர் குறைந்த கல்விச் செல்வமுடையவராயினும் பெரும் பக்தி நிறைந்தவர்கள்; மற்றவர்கள் சிற்றறிவுடையவராயினும் நிறையக் கேட்டறிந்தவர்களும் பெருங்குணமுடையவர்களுமாவர்.",
        '0.134': "பல இல்லறத்தாரும் அவரிடமிருந்து முழு அருளைப் பெற்றனர்; அவர்களுள் லிகுச குலத்தின் மூன்று முடிமணிகள் மூன்று அக்னிகள் போல ஒளிர்ந்தனர்.",
        '0.135': "அந்த அறிஞர் சிறந்தோர் மத்வரின் ஆணையைப் பெரும்பாலும் ஒருபோதும் கைவிடவில்லை; சீடர்கள் என்னும் வயல்களில் நல்ல கல்வியின் விதைகளை விதைப்பதிலேயே ஈடுபட்டிருந்தனர்.",
        '0.136': "ஊர்த் தலைவர்களும் அந்தணர் தலைவர்களும் பூர்ணேக்ஷரின் (மத்வரின்) சீடத்துவத்தைப் பெற்றனர்; அவர்கள் நல்லோரைக் காப்பதாலேயே உயர்ந்த நிலை கிடைக்கும் என்பர்.",
        '0.137': "பணிவிடை, பற்று (பக்தி) முதலியவற்றால் மகிழ்ந்து ராமனுக்குப் பிரியமான அவர், ராமனைப் போலவே சிலருக்கு யோகிகளுக்கும் அரிதான தம் கதியை அளித்தார்.",
        '0.138': "யாருடைய கருணையின் உதயத்தால் இத்தகைய சீடர், சீடர்களின் சீடர்களின் சிறப்பு உண்டாயிற்றோ, பக்தியால் எளிதில் கிடைக்கும் அவருடைய திருவடிக் கற்பக மரத்தை யார் விரும்பமாட்டார்?",
        '0.139': "இவ்வாறு பூமியில் நல்லோரால் பூஜிக்கப்பட்ட முழு ஞானியர், இறைவன் ஶேஷ சயனத்தில் உறங்கும் (சாதுர்மாஸ்ய) காலத்தில், பக்தர்களின் அன்புக்காக, கண்வ தீர்த்தத்தின் காற்றால் புனிதமான கிராமத்தின் சிறந்த மடத்தில் தங்கினார்.",
        '0.140': "கல்வி அமுதின் ஒளியைப் பரப்பும், அழகிய ஒளியால் இனிய பகவான் ஆனந்ததீர்த்தரின் முகச் சந்திரனை இங்கே கண்ட பக்தர்களின் அடியாருக்குச் செய்யும் பணிவிடையும் கூட, ஸம்ஸாரத் துயர் தணிய மனிதனுக்கு எதைத்தான் தராது?",
        '0.141': "இவ்வாறு கவிகுலதிலகரான த்ரிவிக்ரம பண்டிதாசார்யரின் மகன் நாராயண பண்டிதாசார்யர் இயற்றிய, 'ஆனந்த' முத்திரையுடைய ஸ்ரீஸுமத்வவிஜய மஹாகாவ்யத்தின் பதினைந்தாம் ஸர்க்கம் நிறைவுற்றது.",
      },
    },
    'sumadhva-vijaya-16': {
      verses: {
        '0.0': "பிறகு இங்கே ஓர் அறிஞர், மதுசூதனனின் திருவடிச் சேவையின் பாக்கியமுடைய வேதநெறி நல்லோருக்கு, பந்தம் மோக்ஷம் இரண்டுக்கும் மூலமான வேதாந்தத்தையே விளக்குவது போல, பேரறிவாளரின் பெருமகிமையைத் தெளிவாக எடுத்துரைத்தார்.",
        '0.1': "கோமதி நதிக் கரையருகே கடைசி வர்ணத்தில் பிறந்த, வேதத்தைப் பகைக்கும், வாயாடியான ஓர் அரசன், தூய புகழ்ச் சந்திரனும் வேதங்களின் சிறப்பை நிறுவுபவரும் சொல்வன்மையாளரில் சிறந்தவருமான ஸர்வஜ்ஞரிடம் இவ்வாறு கூறினான்:",
        '0.2': "'எந்த வாக்கியம் எங்காவது தான் சொன்ன பயனில் தவறுகிறதோ அது பித்தனின் உளறல் போல ப்ரமாணம் அல்ல; அது எல்லா வேத வசனங்களும் ப்ரமாணம் அல்ல என்பதற்கு முற்றிலும் உதாரணமாகிறது.'",
        '0.3': "'வேதம் கூறும் பயன் தகுதிக்கேற்பக் கிடைக்கும்' என்று பேரறிவாளர் சொன்னபோது அந்தத் தந்திரசாலி கூறினான்: 'தகுதியுடைய அதிகாரி எங்கும் காணப்படவில்லை; ஆகவே கழுதைக் கொம்பைப் போல அவன் இருக்க முடியாது.'",
        '0.4': "அந்த ஏளனத்தைப் பொறுக்காத அந்த உயர்ந்தவர் உடனே தம் இரு தளிர்க் கைகளில் தாவரங்களின் விதைகளை எடுத்து, ஸூக்தத்தால் அவற்றிலிருந்து முளை, இலை, மலர், விதை ஆகியவற்றைத் தோற்றுவித்தார்.",
        '0.5': "ஒருமுறை இரவில் விளக்கவுரை செய்துகொண்டிருந்தபோது விளக்கு அணைந்துவிட, பெருங்கருணைக் கடலான அவர் தம் கால் கட்டைவிரல் நகத்தின் ஒளியாலேயே சீடர்களை மீண்டும் படிக்கச் செய்தார்.",
        '0.6': "ஓரிடத்தில் உயர்ந்த கரையிலிருந்து விழும் நீர்த் தாரைகளின் வேகத்தைத் தாங்கக் கூடிய, படித்துறைக்காக ஆயிரம் பேர் கொண்டுவந்து வலிமை போதாமல் விட்டுவிட்ட பெரிய பாறையைக் கண்டு பெருநோக்கர் கேட்டார்:",
        '0.7': "'மக்களின் நலனுக்காக இந்தப் பாறை ஏன் கொண்டு செல்லப்படவில்லை?' என்றதும் அங்குள்ள மக்கள் கூறினர்: 'யதிகளில் சிறந்தவரே, மனிதர்களால் இதைக் கொண்டு செல்ல முடியாது; பீமனே முயன்றாலும் கொண்டு செல்வானோ இல்லையோ!'",
        '0.8': "முன்பு வானர வடிவில் மலையைச் சுமந்தவரான அவர் தம் தூய தாமரைக் கையால் விளையாட்டாக அதைக் கொண்டு சென்று அங்கே வைத்தார்; இன்றும் துங்கைக் கரையிலுள்ள அந்தப் பாறை அவருடைய செயலுக்குச் சான்று.",
        '0.9': "அடங்கிய மனமுடைய யதிச் சீடர்களும் மற்றவர்களும் விவாதத்தில் ஈடுபட்டுக் கூட்டம் கூட்டமாக வழியை அழகுபடுத்த, சந்திரன் சூரியனுடன் இருக்கும் திதியில் (அமாவாசையில்) அந்த முழு அறிவாளர் கடலுக்குச் சென்றார்.",
        '0.10': "அந்தணர் சிறந்த கண்வருக்குப் பிரியமான குளத்தில் மூழ்கி நனைந்த உடலுடன், சூரிய கிரகணத்தின் பொருட்டுச் சிறியோர் முதியோர் உட்பட எல்லாக் கிராம மக்களும் அங்கே வந்துகொண்டிருந்தனர்.",
        '0.11': "பரிவாரத்துடன் இருந்த ஸர்வஜ்ஞரைக் கண்டு நல்லோர் மலர்ந்த கண்களுடனும் சிரிக்கும் முகங்களுடனும் மகிழ்ந்தனர்; மற்றவர்கள் முகம் சுளித்துப் பழித்தனர்; இது வியப்பல்ல, இரண்டும் இயல்பைச் சார்ந்தவை.",
        '0.12': "'இந்த உலக குருவைப் பழிக்காதீர்கள், பழிக்காதீர்கள்!' என்று அதட்டுவது போல, அலைகள் என்னும் கைகளை உயர்த்தி, கலங்கி, இடிமுழக்கம் போன்ற கர்ஜனையுடன் அச்சமூட்டும் வேடம் பூண்டு, தீயோரை அடக்கச் சினத்துடன் கடலரசன் பாய்ந்தான்.",
        '0.13': "மகிழ்ச்சியால் அசைந்து, விரைந்து முன்னேறி, ஆழ்ந்த குரலால் துதித்து, நுரைச் சிரிப்புடன், மிகுந்த அலைகள் என்னும் உறுப்புகளால் கடல் கரையில் மத்வரை வணங்குவது போலத் தோன்றியது.",
        '0.14': "மத்வரும் கடலும் ஒப்பானவர்கள்: சொல் (நீர்) விளையாட்டில் மேலானவர்கள், ஆழம் காண முடியாதவர்கள், கடக்க முடியாதவர்கள், பலவகைக் குண ரத்தினங்களை ஒளிரச் செய்பவர்கள்; ஆனால் பேரறிவாளரின் லாவண்யம் (அழகு) மக்களுக்கு இனியது, கடலின் லாவண்யம் (உப்பு) அப்படி அல்ல — இதுவே வேறுபாடு.",
        '0.15': "கடலின் விரைவான அலைகள் என்னும் கைகளால் துடைக்கப்பட்ட தூய அகன்ற கரை ஆசனத்தில் அமர்ந்து, பிரபு ஐதரேய ஶாகையின் ஸூக்தங்களை மிக அழகாக நெடுநேரம் விளக்கினார்.",
        '0.16': "'இவருடைய குரல் ஆழத்தால் கடலின் முழக்கத்தையும் அடக்குகிறது; ஆயினும் வியப்பு, கேட்க இனிமையாக உள்ளது; முழுநிலவு முகமுடைய இந்தப் புண்ணியர் யார்?' என்று எண்ணி மக்கள் கடல் விரைவில் அவரைச் சூழ்ந்தது.",
        '0.17': "'வேதங்களின் தகுந்த கருத்தைக் கூறுவதில் தேர்ந்த இவரை வேதப் பகைவர் என்று சொன்ன பெரும் பொறாமைக்காரர்களுக்குச் சீ, சீ!' என்று மக்கள் உரக்கக் கூறி, வியப்புடன் கைகூப்பி வணங்கினர்.",
        '0.18': "பெருமனத்தாரை பக்தியுடன் போற்றி, தேவர்களும் பணியும் அவருடைய பாதத் தூசியைத் தரித்து, அந்தணர் கூட்டங்கள் சிறந்த நேரத்தில் அவருடைய நீராடலால் மேலும் புனிதமான கடலில் நீராடினர்.",
        '0.19': "யானைக் கூட்டங்கள் போலத் தடுக்க முடியாத, மக்கள் கூட்டங்களை வீழ்த்தும் வலிமையான அலைகளால் தாக்கப்பட்டு உருட்டப்பட்ட பலர் அங்கே கடலில் நகைப்புக்கு உள்ளாயினர்.",
        '0.20': "அகன்ற அலைகளால் மறைந்த உடலுடன் மூழ்கிக்கொண்டிருந்த முழு அறிவாளரைக் கண்டு ஒரு தீயவன் 'ஐயோ, மூவுலகையும் வென்ற புகழ்பெற்ற குரு சிறிய அலையின் விளையாட்டில் விழுகிறார்!' என்று சிரித்தான்.",
        '0.21': "எண்ணற்ற (குணங்கள்) உடைய அவர் பிறரைக் கலக்கும் அற்பர்களின் இழிந்த சொற்களைப் பொருட்படுத்தவில்லை; பெருவீரமுடைய சிங்கம் நாய்களைக் குரைக்கச் செய்யும் நரிகளின் ஊளையைப் பொருட்படுத்துவதில்லை அல்லவா?",
        '0.22': "உலகங்களுக்குப் பிறப்பு, காப்பு, முடிவு அளிக்கும் தம் கடைக்கண் பார்வையைப் பேரறிவாளர் கடல் மீது செலுத்தினார்; அந்த மிகக் கனமானவரால் ஆட்கொள்ளப்பட்ட கடல் அசைவை விட்டுக் குளம் போலாயிற்று.",
        '0.23': "வேறு யாராலும் இயலாத இத்தகைய செயல்களாலும் தீயவனுக்கு அவர் மீது நிலையான மதிப்பு உண்டாகவில்லை; மீண்டும் பகைத்தான்; பாக்கியமற்ற அந்தத் தீய மனத்தானுக்கு அதுவே பொருத்தம்.",
        '0.24': "கண்டவாடன் தன் சகோதரனுடன் வந்தபோது, 'இவன் பணிவிடை செய்யத் தகுந்தவன்' என்ற சோதனையாளர்களின் சொல்லின்படி, தம் வலிமையை வெளிப்படுத்த அவர் தயக்கமின்றிச் சிறிது பணிவிடை செய்யும்படி அவனுக்கு ஆணையிட்டார்.",
        '0.25': "முப்பது சிறந்த ஆட்கள் கொண்டுவந்த கொடிமரத்தை காந்தாவரத்திலுள்ள ஸ்ரீகாந்தேஶ்வரர் கோயிலுக்குத் தனியாகக் கொண்டு சென்றவனும், லேசான கதையால் தென்னை மரத்தை அடித்து அசைந்த அதிலிருந்து விரும்பிய அளவு காய்களைப் பெற்றவனும் இவனே.",
        '0.26': "இத்தகைய வலிமையுடைய அவனும் அவனுடைய அண்ணனும் இருவரும் ஒரே நேரத்தில் இருபுறமும் குருவின் கழுத்தைப் பிடித்து நசுக்கப் பெருமுயற்சி செய்தனர்; போராட்டத்தால் அது படிப்படியாக மேலும் கடினமாயிற்று.",
        '0.27': "குருவின் ஆணைப்படி விசிறியால் விசிறப்பட்டும் வியர்த்துக் களைத்த அவ்விருவரும், இரும்பைவிடக் கடினமான, இடையிடையே தெளிவாகப் பேசிக்கொண்டே இருந்த கழுத்தை விட்டுத் தரையில் விழுந்தனர்.",
        '0.28': "அவ்விருவரும் தேறிய பின்னும் செருக்குக் குறையாததால், தூய இதயத்தார் தரையில் வைத்திருந்த தம் விரலைத் தூக்கும்படி கூறினார்; மிகுந்த முயற்சியுடன் வலிமையாகப் பிடித்தும் அதை அசைக்கக் கூட அவர்களால் முடியவில்லை.",
        '0.29': "மென்முறுவலுடன் அவர் சிரமமின்றி ஒரு வடுவின் மேல் அமர்ந்து நரஸிம்ஹர் கோயிலைச் சுற்றி வந்தார்; இவ்வாறு லகிமா முதலிய ஐஶ்வர்யங்கள் உடைய மத்வர் மூவுலகின் அதிசய ரத்தினங்களின் அரசரானார்.",
        '0.30': "அரசனின் ஐம்பது ஆட்கள் சிரமப்பட்டுக் கொண்டுவந்த மர ஏணியை வீட்டுக்குக் கொண்டு சென்ற பூர்வவாடன், குருவின் ஆணைப்படியே விளக்கவுரைக் குரலை அடக்க அவருடைய கழுத்தை நசுக்கினான்.",
        '0.31': "கடும் பிடிவாதத்துடன் முயன்ற அவன் வியர்த்தும், அவருடைய ப்ரவசன ஒலி முன்பைவிட அதிகமாக முழங்கியது; பெருமனத்தாரின் விரலைக் கூட அவனால் தூக்க முடியவில்லை; மக்களுக்கு வியப்பு உண்டாயிற்று.",
        '0.32': "ஶிவாக்னி முதலிய மற்றவர்களும் மேலும் வலிமையான முயற்சிகளால் பிரபுவைச் சோதித்தனர்; அவர் அதைப் புறக்கணிக்கவில்லை; அவரிடம் எங்கும் வலிமைக் குறைவு காணப்படவில்லை; 'இவரே பீமன்' என்று அவர்கள் உறுதியாக முடிவு செய்தனர்.",
        '0.33': "குறடால் மீண்டும் மீண்டும் பிடித்து இழுத்தும் அவருடைய உடலின் ஒரு மயிர் கூடப் பிடுங்கப்படவில்லை; மென்மையான மூக்கு நுனியில் மிக வலியவர்கள் முஷ்டியால் குத்தியும் அவருடைய முகச் சந்திரனின் அமைதி கலையவில்லை.",
        '0.34': "சிங்கம் வலுவற்ற நாய்களுடனும், கடல் ஓடை நதிகளின் சிறு நீருடனும், சூரியன் மின்மினிகளுடனும் நடந்துகொள்வது போல, மனிதர்களைப் போல நடித்து அவர் எதிர்வாதிகளுடன் நடந்துகொண்டார்.",
        '0.35': "பேரறிவாளர் நெடுங்காலமாக நைவேத்யம் இல்லாதிருந்த பாரந்தி கோயிலுக்கு வந்து, ஊர்த் தலைவர், அரசர்கள் மூலம் அரை நாளிலேயே ஏராளமான பூதபலிகளுடன் அதன் சிறப்பை மீட்டெடுத்தார்.",
        '0.36': "வணங்கத்தக்கோராலும் வணங்கப்படும் அவர், முன்பு பீமனாக இருந்தபோது சகோதரர்களுடன் இங்கே ஐந்து வடிவுடைய முராரியை நிறுவி, பாஞ்சாலி உடன் பலி நீர் அளிக்க வழிபட்டதை அப்போது நினைவுகூர்ந்தார்.",
        '0.37': "ஸரிதந்தரம் என்ற பகுதிக்கு வரும்போது அங்குள்ள குளம் கோடையில் வறண்டுவிட்டது என்று கேட்டு, அதே நேரத்தில் மேகக் கூட்டத்தால் பெருமழை பொழிவித்து அதை நிரப்பி மக்களை வியக்க வைத்தார்.",
        '0.38': "தீய ஆலோசனைகளாலும் தீயோர் கூட்டங்களாலும் தூண்டப்பட்ட ஶூத்ரத் தலைவனான ஊர்த் தலைவன் அவரைத் தாக்க வந்தான்; ஆனால் சென்றுகொண்டிருந்த அவரை உதய சூரியன் போலக் கண்டு வியந்து வணங்கினான்.",
        '0.39': "மூவுலகின் மருத்துவ நாதனான பகவானின் சிறந்த க்ஷேத்ரத்துக்குச் சென்று, ஆழ்ந்த உள்ளமுடைய ஆற்றலாளர் தம் பக்தர்களின் நலனுக்காக 'ஸ்ரீக்ருஷ்ணாம்ருத மஹார்ணவம்' என்ற நல்மொழித் தொகுப்பை இயற்றினார்.",
        '0.40': "அவர் மற்றொரு வளமான கிராமத்துக்குச் சென்றபோது, அங்குள்ள செருக்கு மிக்க தற்பெருமையாளர்களின் செருக்கை அடக்கவே ஒருவன் ஸர்வஜ்ஞரிடம் 'அங்குள்ள அறிஞர்கள் எங்கே? அவர்கள் பாழுங்கிணற்றுத் தவளைகள் போன்றவர்கள்!' என்றான்.",
        '0.41': "'ஸர்வஜ்ஞராயினும் இந்த யதிக்கு யாகத்தின் நுணுக்கங்கள் அதிகம் தெரியாது' என்று உறுதியாக முடிவு செய்த ஒருவன், பொறாமையால் சபையில் ஒளிர்ந்த அவரிடம் கர்மம் பற்றிய ஶ்ருதியின் கடினமான பகுதியைப் பற்றிக் கேட்டான்.",
        '0.42': "ஐயத்தின் சிறுதுளியும் இல்லாத அவர் அதை அவனுக்கு விளக்கி, ஆறாம் நாளில் யஜமானன் ஓதும், சந்தஸ்களிலிருந்து வழிந்த சாரத்தைச் சேகரிக்கும் நாராஶம்ஸீயின் இறுதி அழகிய மந்திர வகைகளையும் கூறினார்.",
        '0.43': "அத்தகைய உயர்ந்த புலமையைக் கண்டு போட்டியால் கலங்கிய மனமுடைய எதிர்த்தரப்பினர் 'இது பொருள் அல்ல' என்றனர்; 'அப்படியானால் நீங்களே சொல்லுங்கள்' என்று பேரறிவாளர் கூறியதும் அவர்கள் விரைவில் ஓடிவிட்டனர்.",
        '0.44': "பிறகு ஒருவன் மந்திரப் பாதங்களின் முன்னொட்டுடன் கூடிய வடிவங்களைக் கூறும் மஹாநாம்னீ பகுதியைப் பற்றிக் கேட்டான்; அச்சொல் தொகுப்பின் பொருளைக் கூறியவாறு அவர் அது நிலைத்திருக்க உடனே எழுதுவித்தார்.",
        '0.45': "உதித்த முழுநிலவு போன்ற மத்வரைக் கண்டு தீயோர் கூட்டம், அதைத் தன் போட்டியாளன் என்று எண்ணித் தொலைவிலிருந்து ஓடும் மெலிந்த நாய் போலக் கலங்கியது; அதனால் அமுதத்தின் இருப்பிடத்துக்கு என்ன தீங்கு?",
        '0.46': "கருணையாளர் சிலருக்கு மட்டுமே போதுமான ஏழைப் பக்தர்களின் உணவை நான்கு மடங்காக்கினார்; செல்வந்தர்களின் மகிழ்ச்சிக்காகப் பேரறிவாளர் முப்பது பேர் உண்ணும் அளவு உணவை உண்டார்.",
        '0.47': "அவர் மழை முதலியவற்றை நியமித்தார்; உலகை நியமிக்கும் வாயுவிடம் இதில் என்ன வியப்பு? ஆயினும் உலக குருவின் செயல்களை மீண்டும் உரைப்பது செயல்களில் சிறந்தது என்பதால் இங்கே வர்ணிக்கிறோம்.",
        '0.48': "இவ்வாறு அந்த அந்தணர் கூறினார். மத்வரின் பலவகைக் கதை இங்கே கதைகளிடையே போற்றப்பட்டது மட்டுமல்ல; தேவர் தலைவர்களாலேயே நேரடியாகக் கூறப்பட்டு, அவர்களுடைய மகிழ்ச்சிக்காகத் தேவசபையில் கந்தர்வர்களால் பாடப்பட்டது.",
        '0.49': "செய்யுளில் கூறப்பட்ட அக்கதையை, காகீ குறையற்ற இனிய குரலுடைய கந்தர்வர்கள் தகுந்த தானம், மூர்ச்சனைகளுடன் பஞ்சமம் முதலிய ஸ்வரங்களை எடுத்து, தேவலோகத்துக்குரிய ஒளிமிக்க காந்தார க்ராமத்தைத் தோற்றுவித்துப் பாடினர்.",
        '0.50': "அழகிய மகுடங்கள் தரித்த தலைகளைத் தாழ்த்தி, செம்பு நிற விரல் நுனிகளைக் கூப்பி, புன்னகைக்கும் முகத் தாமரைகளுடன், உறுதியான பக்தியுடைய தேவேந்திரர்கள் தஶதிஷணரின் (மத்வரின்) சரிதப் பாடலைக் கேட்டனர்.",
        '0.51': "அப்போது இடையறாத ஞானமுடையவரின் வெற்றிப் பெருவிழாவைப் போற்றியவாறு, வியந்தும் புன்னகைத்தும் தேவர்கள் முனிவர் கூட்டங்களுடனும் உபதேவர்களுடனும் அவரைக் காணப் புறப்பட்டனர்.",
        '0.52': "முராரியின் குணக் கூட்டங்களைக் காணக் கண்ணாடி போன்ற, அவர் இயற்றிய நல்ல ஶாஸ்த்ரத்தை வர்ணித்தவாறு, தம் ஒளியால் நட்சத்திரப் பாதையை ஒளிரச் செய்தவாறு அவர்கள் நிறைந்த மனவிளையாட்டுடையவரைக் கண்டனர்.",
        '0.53': "பூமியின் அப்பகுதியில் வசித்து, நற்புகழால் உலகங்களை அழகுபடுத்தி, பலவகைச் சிறப்புச் சீடர்களிடையே ஐதரேய உபநிஷத்தை விளக்கிக்கொண்டிருந்த அவரைத் தேவேந்திரர்கள் வானிலிருந்து வணங்கினர்.",
        '0.54': "திருவுடையவரும், சந்திர முகரும், தாமரைக் கண்ணரும், ஆழ்ந்த குரலினரும், மிகத் தெய்வீக இலக்கணங்கள் நிறைந்தவரும், ஹரியின் அன்பால் விருப்பங்கள் நிறைவேறியவருமான தம் குருவைக் கண்டு நிறைவுற்ற அவர்கள் சொற்களால் அவரை அர்ச்சித்தனர்:",
        '0.55': "'உங்கள் கதிர் (சொல்) கூட்டங்களால் தவறான ஆகமங்களின் இருளை நீக்கினீர்கள், முகுந்தனின் குணக் கூட்டத்தைக் காட்டினீர்கள், நற்குணங்களால் பதினான்கு உலகங்களையும் வென்றீர்கள்; குருவே, கருணையால் எங்களுக்கும் அடைக்கலமாகுங்கள்.",
        '0.56': "ப்ராணேஶா, வணங்குவோரின் நலனுக்காகப் பூமிக்கு வந்த உமக்கு வணக்கம்; ஸ்வாமி, ராமனுக்கு மிகப் பிரியமான, பெருங்குணமுடைய ஹனுமானே, வணக்கம்; மிக வலியவனே, க்ருஷ்ணனுக்குப் பிரியமான பீமனே, பகவானே, உமக்கு வணக்கம்; ஸ்ரீமன் மத்வரே, வணக்கம், எங்களுக்கு நல்ல பார்வையை அருளுங்கள்; ஜய, ஜய!'",
        '0.57': "இவ்வாறு கூறி, குருவின் அந்தப் பெரும் வெற்றித் திருவிழாவைக் கொண்டாடியவாறு, தேவேந்திரர்கள் ஹரியின் அன்பர்களில் சிறந்த ஸ்ரீமத் ஆனந்ததீர்த்தர் மீது எல்லோருக்கும் தெரியும்படி நறுமண மலர் மழை பொழிந்தனர்.",
        '0.58': "இவ்வாறு கவிகுலதிலகரான த்ரிவிக்ரம பண்டிதாசார்யரின் மகன் நாராயண பண்டிதாசார்யர் இயற்றிய, 'ஆனந்த' முத்திரையுடைய ஸ்ரீஸுமத்வவிஜய மஹாகாவ்யத்தின் பதினாறாம் ஸர்க்கம் நிறைவுற்றது.",
      },
    },
  },
};
